        /// <summary>
        /// <para>
        /// An application-defined callback function that processes <see cref="WM_TIMER"/> messages.
        /// The <see cref="TIMERPROC"/> type defines a pointer to this callback function.
        /// <c>TimerProc</c> is a placeholder for the application-defined function name.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nc-winuser-timerproc"/>
        /// </para>
        /// </summary>
        /// <param name="Arg1">
        /// A handle to the window associated with the timer.
        /// </param>
        /// <param name="Arg2">
        /// The WM_TIMER message.
        /// </param>
        /// <param name="Arg3">
        /// The timer's identifier.
        /// </param>
        /// <param name="Arg4">
        /// The number of milliseconds that have elapsed since the system was started.
        /// This is the value returned by the <see cref="GetTickCount"/> function.
        /// </param>
        public delegate void Timerproc(HWND Arg1, UINT Arg2, UINT_PTR Arg3, DWORD Arg4);

        /// <summary>
        /// <para>
        /// An application-defined callback (or hook) function that the system calls in response to events generated by an accessible object.
        /// The hook function processes the event notifications as required.
        /// Clients install the hook function and request specific types of event notifications by calling <see cref="SetWinEventHook"/>.
        /// </para>
        /// <para>
        /// The <see cref="WINEVENTPROC"/> type defines a pointer to this callback function.
        /// <c>WinEventProc</c> is a placeholder for the application-defined function name.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nc-winuser-wineventproc"/>
        /// </para>
        /// </summary>
        /// <param name="hWinEventHook">
        /// Handle to an event hook function.
        /// This value is returned by <see cref="SetWinEventHook"/> when the hook function is installed
        /// and is specific to each instance of the hook function.
        /// </param>
        /// <param name="event">
        /// Specifies the event that occurred.
        /// This value is one of the event constants.
        /// </param>
        /// <param name="hwnd">
        /// Handle to the window that generates the event, or <see cref="NULL"/> if no window is associated with the event.
        /// For example, the mouse pointer is not associated with a window.
        /// </param>
        /// <param name="idObject">
        /// Identifies the object associated with the event.
        /// This is one of the object identifiers or a custom object ID.
        /// </param>
        /// <param name="idChild">
        /// Identifies whether the event was triggered by an object or a child element of the object.
        /// If this value is <see cref="CHILDID_SELF"/>, the event was triggered by the object;
        /// otherwise, this value is the child ID of the element that triggered the event.
        /// </param>
        /// <param name="idEventThread"></param>
        /// <param name="dwmsEventTime">
        /// Specifies the time, in milliseconds, that the event was generated.
        /// </param>
        /// <remarks>
        /// <para>
        /// Within the hook function, the parameters <paramref name="hwnd"/>, <paramref name="idObject"/>,
        /// and <paramref name="idChild"/> are used when calling <see cref="AccessibleObjectFromEvent"/>.
        /// </para>
        /// <para>
        /// Servers generate events by calling <see cref="NotifyWinEvent"/>.
        /// </para>
        /// <para>
        /// Create multiple callback functions to handle different events. For more information, see Registering a Hook Function.
        /// </para>
        /// </remarks>
        public delegate void Wineventproc([In] HWINEVENTHOOK hWinEventHook, [In] EventConstants @event, [In] HWND hwnd, [In] LONG idObject,
            [In] LONG idChild, [In] DWORD idEventThread, [In] DWORD dwmsEventTime);


        /// <summary>
        /// 
        /// </summary>
        /// <returns></returns>
        [WindowsVersionRequirement(WindowsVersion.WindowsVista)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "CancelShutdown", ExactSpelling = true)]
        public static extern BOOL CancelShutdown();

        /// <summary>
        /// <para>
        /// Performs special kernel operations for console host applications.
        /// This includes reparenting the console window,
        /// allowing the console to pass foreground rights on to launched console subsystem applications and terminating attached processes.
        /// </para>
        /// <para>
        /// Note
        /// </para>
        /// <para>
        /// This function has no associated import library.
        /// This function is available as the resource named <see cref="ConsoleControl"/> in User32.dll.
        /// You must use the <see cref="LoadLibrary"/> and <see cref="GetProcAddress"/> functions to dynamically link to User32.dll.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/console/consolecontrol"/>
        /// </para>
        /// </summary>
        /// <param name="Command">
        /// One of the <see cref="CONSOLECONTROL"/> values indicating which console control function should be executed.
        /// </param>
        /// <param name="ConsoleInformation">
        /// A pointer to one of the <see cref="CONSOLEENDTASK"/>, <see cref="CONSOLEWINDOWOWNER"/>,
        /// or <see cref="CONSOLESETFOREGROUND"/> structures specifying additional data for the requested console control function.
        /// </param>
        /// <param name="ConsoleInformationLength">
        /// The size of the structure pointed to by the <paramref name="ConsoleInformation"/> parameter.
        /// </param>
        /// <returns>
        /// <para>
        /// If the function succeeds, the return value is <see cref="STATUS_SUCCESS"/>.
        /// </para>
        /// <para>
        /// If the function fails, the return value is an <see cref="NTSTATUS"/> indicating the reason for the failure.
        /// </para>
        /// </returns>
        /// <remarks>
        /// <para>
        /// This function is not defined in an SDK header and must be declared by the caller. This function is exported from user32.dll.
        /// </para>
        /// <para>
        /// Each command expects a different struct for the <paramref name="ConsoleInformation"/> parameter.
        /// </para>
        /// <para>
        /// <list type="bullet">
        /// <item>
        /// <description>
        /// <see cref="ConsoleNotifyConsoleApplication"/>: expects a pointer to a <see cref="CONSOLE_PROCESS_INFO"/>
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// <see cref="ConsoleSetCaretInfo"/>: expects a pointer to a <see cref="CONSOLE_CARET_INFO"/>
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// <see cref="ConsoleSetForeground"/>: expects a pointer to a <see cref="CONSOLESETFOREGROUND"/>
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// <see cref="ConsoleSetWindowOwner"/>: expects a pointer to a <see cref="CONSOLEWINDOWOWNER"/>
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// <see cref="ConsoleEndTask"/>: expects a pointer to a <see cref="CONSOLEENDTASK"/>
        /// </description>
        /// </item>
        /// </list>
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.Windows7)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "ConsoleControl", ExactSpelling = true)]
        public static extern NTSTATUS ConsoleControl([In] CONSOLECONTROL Command, [In] PVOID ConsoleInformation, [In] DWORD ConsoleInformationLength);

        /// <summary>
        /// <para>
        /// Captures the mouse and tracks its movement until the user releases the left button, presses the ESC key,
        /// or moves the mouse outside the drag rectangle around the specified point.
        /// The width and height of the drag rectangle are specified by the <see cref="SM_CXDRAG"/> and <see cref="SM_CYDRAG"/> values
        /// returned by the <see cref="GetSystemMetrics"/> function.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-dragdetect"/>
        /// </para>
        /// </summary>
        /// <param name="hwnd">
        /// A handle to the window receiving mouse input.
        /// </param>
        /// <param name="pt">
        /// Initial position of the mouse, in screen coordinates.
        /// The function determines the coordinates of the drag rectangle by using this point.
        /// </param>
        /// <returns>
        /// <para>
        /// If the user moved the mouse outside of the drag rectangle while holding down the left button, the return value is nonzero.
        /// </para>
        /// <para>
        /// If the user did not move the mouse outside of the drag rectangle while holding down the left button, the return value is zero.
        /// </para>
        /// </returns>
        /// <remarks>
        /// The system metrics for the drag rectangle are configurable, allowing for larger or smaller drag rectangles.
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsNT40)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "DragDetect", ExactSpelling = true, SetLastError = true)]
        public static extern BOOL DragDetect([In] HWND hwnd, [In] POINT pt);

        /// <summary>
        /// 
        /// </summary>
        /// <param name="hwnd"></param>
        /// <param name="hwndFrom"></param>
        /// <param name="fmt"></param>
