        /// <param name="hcur"></param>
        /// <returns></returns>
        [WindowsVersionRequirement(WindowsVersion.WindowsNT40)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "DragObject", ExactSpelling = true, SetLastError = true)]
        public static extern DWORD DragObject([In] HWND hwnd, [In] HWND hwndFrom, [In] UINT fmt, [In] ULONG_PTR data, [In] HCURSOR hcur);

        /// <summary>
        /// <para>
        /// Calls the <see cref="ExitWindowsEx"/> function to log off the interactive user.
        /// Applications should call <see cref="ExitWindowsEx"/> directly.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-exitwindows"/>
        /// </para>
        /// </summary>
        /// <param name="dwReserved">
        /// This parameter must be zero.
        /// </param>
        /// <param name="Code">
        /// This parameter must be zero.
        /// </param>
        /// <returns>
        /// If the call succeeds, the return value is nonzero.
        /// If the call fails, the return value is zero.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </returns>
        /// <remarks>
        /// <para>
        /// The system sends a <see cref="WM_QUERYENDSESSION"/> to the main window of each running application.
        /// </para>
        /// <para>
        /// An application agrees to terminate by returning <see cref="TRUE"/> when it receives this message
        /// (or by allowing the <see cref="DefWindowProc"/> function to process the message).
        /// If any application returns <see cref="FALSE"/> when it receives the <see cref="WM_QUERYENDSESSION"/> message, the logoff is canceled.
        /// </para>
        /// <para>
        /// After the system processes the results of the <see cref="WM_QUERYENDSESSION"/> message,
        /// it sends the <see cref="WM_ENDSESSION"/> message with the <c>wParam</c> parameter set to <see cref="TRUE"/>
        /// if the system is shutting down and to <see cref="FALSE"/> if it is not.
        /// </para>
        /// </remarks>
        public static BOOL ExitWindows(DWORD dwReserved, UINT Code) => ExitWindowsEx(EWX_LOGOFF, (SystemShutdownReasonCodes)0xFFFFFFFF);

        /// <summary>
        /// <para>
        /// Logs off the interactive user, shuts down the system, or shuts down and restarts the system.
        /// It sends the <see cref="WM_QUERYENDSESSION"/> message to all applications to determine if they can be terminated.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-exitwindowsex"/>
        /// </para>
        /// </summary>
        /// <param name="uFlags">
        /// <para>
        /// The shutdown type. This parameter must include one of the following values.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Value
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="EWX_HYBRID_SHUTDOWN"/>
        /// </para>
        /// <para>
        /// 0x00400000
        /// </para>
        /// </term>
        /// <term>
        /// Beginning with Windows 8:
        /// You can prepare the system for a faster startup by combining the <see cref="EWX_HYBRID_SHUTDOWN"/> flag with the <see cref="EWX_SHUTDOWN"/> flag.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="EWX_LOGOFF"/>
        /// </para>
        /// <para>
        /// 0
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Shuts down all processes running in the logon session of the process that called the <see cref="ExitWindowsEx"/> function.
        /// Then it logs the user off.
        /// </para>
        /// <para>
        /// This flag can be used only by processes running in an interactive user's logon session.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="EWX_POWEROFF"/>
        /// </para>
        /// <para>
        /// 0x00000008
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Shuts down the system and turns off the power. The system must support the power-off feature.
        /// </para>
        /// <para>
        /// The calling process must have the <see cref="SE_SHUTDOWN_NAME"/> privilege.
        /// For more information, see the following Remarks section.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="EWX_REBOOT"/>
        /// </para>
        /// <para>
        /// 0x00000002
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Shuts down the system and then restarts the system.
        /// </para>
        /// <para>
        /// The calling process must have the <see cref="SE_SHUTDOWN_NAME"/> privilege.
        /// For more information, see the following Remarks section.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="EWX_RESTARTAPPS"/>
        /// </para>
        /// <para>
        /// 0x00000040
        /// </para>
        /// </term>
        /// <term>
        /// Shuts down the system and then restarts it,
        /// as well as any applications that have been registered for restart using the <see cref="RegisterApplicationRestart"/> function.
        /// These application receive the <see cref="WM_QUERYENDSESSION"/> message with <c>lParam</c> set to the <see cref="ENDSESSION_CLOSEAPP"/> value.
        /// For more information, see Guidelines for Applications.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="EWX_SHUTDOWN"/>
        /// </para>
        /// <para>
        /// 0x00000001
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Shuts down the system to a point at which it is safe to turn off the power.
        /// All file buffers have been flushed to disk, and all running processes have stopped.
        /// </para>
        /// <para>
        /// The calling process must have the <see cref="SE_SHUTDOWN_NAME"/> privilege. For more information, see the following Remarks section.
        /// </para>
        /// <para>
        /// Specifying this flag will not turn off the power even if the system supports the power-off feature.
        /// You must specify <see cref="EWX_POWEROFF"/> to do this.
        /// </para>
        /// <para>
        /// Windows XP with SP1:
        /// If the system supports the power-off feature, specifying this flag turns off the power.
        /// </para>
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        /// This parameter can optionally include one of the following values.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Value
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="EWX_FORCE"/>
        /// </para>
        /// <para>
        /// 0x00000004
        /// </para>
        /// </term>
        /// <term>
        /// This flag has no effect if terminal services is enabled.
        /// Otherwise, the system does not send the <see cref="WM_QUERYENDSESSION"/> message.
        /// This can cause applications to lose data.
        /// Therefore, you should only use this flag in an emergency.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="EWX_FORCEIFHUNG"/>
        /// </para>
        /// <para>
        /// 0x00000010
        /// </para>
        /// </term>
        /// <term>
        /// Forces processes to terminate if they do not respond to
        /// the <see cref="WM_QUERYENDSESSION"/> or <see cref="WM_ENDSESSION"/> message within the timeout interval.
        /// For more information, see the Remarks.
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// </param>
        /// <param name="dwReason">
        /// <para>
        /// The reason for initiating the shutdown.
        /// This parameter must be one of the system shutdown reason codes.
        /// </para>
        /// <para>
        /// If this parameter is zero, the <see cref="SHTDN_REASON_FLAG_PLANNED"/> reason code will not be set
        /// and therefore the default action is an undefined shutdown that is logged as "No title for this reason could be found".
        /// By default, it is also an unplanned shutdown.
        /// Depending on how the system is configured, an unplanned shutdown triggers the creation of a file
        /// that contains the system state information, which can delay shutdown.
        /// Therefore, do not use zero for this parameter.
        /// </para>
        /// </param>
        /// <returns>
        /// <para>
        /// If the function succeeds, the return value is nonzero.
        /// Because the function executes asynchronously, a nonzero return value indicates that the shutdown has been initiated.
        /// It does not indicate whether the shutdown will succeed.
        /// It is possible that the system, the user, or another application will abort the shutdown.
        /// </para>
        /// <para>
        /// If the function fails, the return value is zero.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </para>
        /// </returns>
        /// <remarks>
        /// <para>
        /// The <see cref="ExitWindowsEx"/> function returns as soon as it has initiated the shutdown process.
        /// The shutdown or logoff then proceeds asynchronously.
        /// The function is designed to stop all processes in the caller's logon session.
        /// Therefore, if you are not the interactive user, the function can succeed without actually shutting down the computer.
        /// If you are not the interactive user, use the <see cref="InitiateSystemShutdown"/> or <see cref="InitiateSystemShutdownEx"/> function.
        /// </para>
        /// <para>
        /// A non-zero return value does not mean the logoff was or will be successful.
        /// The shutdown is an asynchronous process, and it can occur long after the API call has returned, or not at all.
        /// Even if the timeout value is zero, the shutdown can still be aborted by applications, services, or even the system.
        /// The non-zero return value indicates that the validation of the rights and parameters was successful
        /// and that the system accepted the shutdown request.
        /// </para>
        /// <para>
        /// When this function is called, the caller must specify whether or not applications with unsaved changes should be forcibly closed.
        /// If the caller chooses not to force these applications to close and an application with unsaved changes is running on the console session,
        /// the shutdown will remain in progress until the user logged into the console session aborts the shutdown,
        /// saves changes, closes the application, or forces the application to close.
        /// During this period, the shutdown may not be aborted except by the console user, and another shutdown may not be initiated.
        /// </para>
        /// <para>
        /// Calling this function with the value of the <paramref name="uFlags"/> parameter set to <see cref="EWX_FORCE"/> avoids this situation.
        /// Remember that doing this may result in loss of data.
        /// </para>
        /// <para>
        /// To set a shutdown priority for an application relative to other applications in the system,
        /// use the <see cref="SetProcessShutdownParameters"/> function.
        /// </para>
        /// <para>
        /// During a shutdown or log-off operation, running applications are allowed a specific amount of time to respond to the shutdown request.
        /// If this time expires before all applications have stopped,
        /// the system displays a user interface that allows the user to forcibly shut down the system or to cancel the shutdown request.
        /// If the <see cref="EWX_FORCE"/> value is specified, the system forces running applications to stop when the time expires.
        /// </para>
        /// <para>
        /// If the <see cref="EWX_FORCEIFHUNG"/> value is specified, the system forces hung applications to close and does not display the dialog box.
        /// </para>
        /// <para>
        /// Console processes receive a separate notification message, <see cref="CTRL_SHUTDOWN_EVENT"/> or <see cref="CTRL_LOGOFF_EVENT"/>, as the situation warrants.
        /// A console process routes these messages to its <see cref="HandlerRoutine"/> function.
        /// <see cref="ExitWindowsEx"/> sends these notification messages asynchronously;
        /// thus, an application cannot assume that the console notification messages have been handled when a call to <see cref="ExitWindowsEx"/> returns.
        /// </para>
        /// <para>
        /// To shut down or restart the system, the calling process must use the <see cref="AdjustTokenPrivileges"/> function
        /// to enable the <see cref="SE_SHUTDOWN_NAME"/> privilege.
        /// For more information, see Running with Special Privileges.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsNT40)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "ExitWindowsEx", ExactSpelling = true, SetLastError = true)]
        public static extern BOOL ExitWindowsEx([In] ExitWindowsExFlags uFlags, [In] SystemShutdownReasonCodes dwReason);

        /// <summary>
        /// <para>
        /// Retrieves an <see cref="AR_STATE"/> value containing the state of screen auto-rotation for the system,
        /// for example whether auto-rotation is supported, and whether it is enabled by the user.
        /// <see cref="GetAutoRotationState"/> provides a robust and diverse way of querying for auto-rotation state, and more.
        /// For example, if you want your app to behave differently when multiple monitors are attached
        /// then you can determine that from the <see cref="AR_STATE"/> returned.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-getautorotationstate"/>
        /// </para>
        /// </summary>
        /// <param name="pState">
        /// Pointer to a location in memory that will receive the current state of auto-rotation for the system.
        /// </param>
        /// <returns>
        /// <para>
        /// <see cref="TRUE"/> if the method succeeds, otherwise <see cref="FALSE"/>.
        /// </para>
        /// <para>
        /// See <see cref="GetDisplayAutoRotationPreferences"/> for an example of using this function.
        /// </para>
        /// </returns>
        [WindowsVersionRequirement(WindowsVersion.Windows8)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "GetAutoRotationState", ExactSpelling = true)]
        public static extern BOOL GetAutoRotationState([In][Out] ref AR_STATE pState);

        /// <summary>
        /// <para>
        /// Retrieves the count of handles to graphical user interface (GUI) objects in use by the specified process.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-getguiresources"/>
        /// </para>
        /// </summary>
        /// <param name="hProcess">
        /// <para>
        /// A handle to the process.
        /// The handle must refer to a process in the current session,
        /// and must have the <see cref="PROCESS_QUERY_LIMITED_INFORMATION"/> access right (see Process security and access rights).
        /// </para>
        /// <para>
        /// If this parameter is the special value <see cref="GR_GLOBAL"/>,
        /// then the resource usage is reported across all processes in the current session.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003, and Windows XP:
        /// The <see cref="GR_GLOBAL"/> value is not supported until Windows 7 and Windows Server 2008 R2.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP:
        /// The handle must have the <see cref="PROCESS_QUERY_INFORMATION"/> access right.
        /// </para>
        /// </param>
        /// <param name="uiFlags">
        /// <para>
        /// The GUI object type. This parameter can be one of the following values.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Value
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="GR_GDIOBJECTS"/>
        /// </para>
        /// <para>
        /// 0
        /// </para>
        /// </term>
        /// <term>
        /// Return the count of GDI objects.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="GR_GDIOBJECTS_PEAK"/>
        /// </para>
        /// <para>
        /// 2
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Return the peak count of GDI objects.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP:
        /// This value is not supported until Windows 7 and Windows Server 2008 R2.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="GR_USEROBJECTS"/>
        /// </para>
        /// <para>
        /// 1
        /// </para>
        /// </term>
        /// <term>
        /// Return the count of USER objects.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="GR_USEROBJECTS_PEAK"/>
        /// </para>
        /// <para>
        /// 4
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Return the peak count of USER objects.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP:
        /// This value is not supported until Windows 7 and Windows Server 2008 R2.
        /// </para>
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// </param>
        /// <returns>
        /// <para>
        /// If the function succeeds, the return value is the count of handles to GUI objects in use by the process.
        /// If no GUI objects are in use, the return value is zero.
        /// </para>
        /// <para>
        /// If the function fails, the return value is zero.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </para>
        /// </returns>
        /// <remarks>
        /// A process without a graphical user interface does not use GUI resources,
        /// therefore, <see cref="GetGuiResources"/> will return zero.
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.Windows2000)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "GetGuiResources", ExactSpelling = true, SetLastError = true)]
        public static extern DWORD GetGuiResources([In] HANDLE hProcess, [In] DWORD uiFlags);

        /// <summary>
        /// <para>
        /// Retrieves information about the active window or a specified GUI thread.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-getguithreadinfo"/>
        /// </para>
        /// </summary>
        /// <param name="idThread">
        /// The identifier for the thread for which information is to be retrieved.
        /// To retrieve this value, use the <see cref="GetWindowThreadProcessId"/> function.
        /// If this parameter is <see cref="NULL"/>, the function returns information for the foreground thread.
        /// </param>
        /// <param name="pgui">
        /// A pointer to a <see cref="GUITHREADINFO"/> structure that receives information describing the thread.
        /// Note that you must set the <see cref="GUITHREADINFO.cbSize"/> member to <c>sizeof(GUITHREADINFO)</c> before calling this function.
        /// </param>
        /// <returns>
        /// <para>
        /// If the function succeeds, the return value is nonzero.
        /// </para>
        /// <para>
        /// If the function fails, the return value is zero.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </para>
        /// </returns>
        /// <remarks>
        /// <para>
        /// This function succeeds even if the active window is not owned by the calling process.
        /// If the specified thread does not exist or have an input queue, the function will fail.
        /// </para>
        /// <para>
        /// This function is useful for retrieving out-of-context information about a thread.
        /// The information retrieved is the same as if an application retrieved the information about itself.
        /// </para>
        /// <para>
        /// For an edit control, the returned <see cref="GUITHREADINFO.rcCaret"/> rectangle
        /// contains the caret plus information on text direction and padding.
        /// Thus, it may not give the correct position of the cursor.
        /// The Sans Serif font uses four characters for the cursor:
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Cursor character
        /// </term>
        /// <term>
        /// Unicode code point
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <c>CURSOR_LTR</c>
        /// </term>
        /// <term>
        /// 0xf00c
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <c>CURSOR_RTL</c>
        /// </term>
        /// <term>
        /// 0xf00d
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <c>CURSOR_THAI</c>
        /// </term>
        /// <term>
        /// 0xf00e
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <c>CURSOR_USA</c>
        /// </term>
        /// <term>
        /// 0xfff (this is a marker value with no associated glyph)
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        /// To get the actual insertion point in the <see cref="GUITHREADINFO.rcCaret"/> rectangle, perform the following steps.
        /// </para>
        /// <para>
        /// <list type="number">
        /// <item>
        /// <description>
        /// Call <see cref="GetKeyboardLayout"/> to retrieve the current input language.
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// Determine the character used for the cursor, based on the current input language.
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// Call <see cref="CreateFont"/> using Sans Serif for the font,
        /// the height given by <see cref="GUITHREADINFO.rcCaret"/>, and a width of <c>zero</c>.
        /// For <c>fnWeight</c>, call <c>SystemParametersInfo(SPI_GETCARETWIDTH, 0, pvParam, 0)</c>.
        /// If <c>pvParam</c> is greater than 1, set <c>fnWeight</c> to 700, otherwise set <c>fnWeight</c> to 400.
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// Select the font into a device context (DC) and use <see cref="GetCharABCWidths"/>
        /// to get the <c>B</c> width of the appropriate cursor character.
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// Add the <c>B</c> width to <c>rcCaret.left</c> to obtain the actual insertion point.
        /// </description>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        /// The function may not return valid window handles in the <see cref="GUITHREADINFO"/> structure
        /// when called to retrieve information for the foreground thread, such as when a window is losing activation.
        /// </para>
        /// <para>
        /// DPI Virtualization
        /// </para>
        /// <para>
        /// The coordinates returned in the <see cref="GUITHREADINFO.rcCaret"/> rect of the <see cref="GUITHREADINFO"/> struct
        /// are logical coordinates in terms of the window associated with the caret.
        /// They are not virtualized into the mode of the calling thread.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.Windows2000)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "GetGUIThreadInfo", ExactSpelling = true, SetLastError = true)]
        public static extern BOOL GetGUIThreadInfo([In] DWORD idThread, [In][Out] ref GUITHREADINFO pgui);

        /// <summary>
        /// <para>
        /// Retrieves a handle to the Shell's desktop window.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-getshellwindow"/>
        /// </para>
        /// </summary>
        /// <returns>
        /// The return value is the handle of the Shell's desktop window.
        /// If no Shell process is present, the return value is <see cref="NULL"/>.
        /// </returns>
        [WindowsVersionRequirement(WindowsVersion.WindowsNT40)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "GetShellWindow", ExactSpelling = true)]
        public static extern HWND GetShellWindow();

