        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="COLOR_MENUBAR"/>
        /// </para>
        /// <para>
        /// 30
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// The background color for the menu bar when menus appear as flat menus (see <see cref="SystemParametersInfo"/>).
        /// However, <see cref="COLOR_MENU"/> continues to specify the background color of the menu popup.
        /// </para>
        /// <para>
        /// Windows 2000, Windows 10 or greater:
        /// This value is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="COLOR_MENUTEXT"/>
        /// </para>
        /// <para>
        /// 7
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Text in menus.
        /// The associated background color is <see cref="COLOR_MENU"/>.
        /// </para>
        /// <para>
        /// Windows 10 or greater: This value is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="COLOR_SCROLLBAR"/>
        /// </para>
        /// <para>
        /// 0
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Scroll bar gray area.
        /// </para>
        /// <para>
        /// Windows 10 or greater: This value is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="COLOR_WINDOW"/>
        /// </para>
        /// <para>
        /// 5
        /// </para>
        /// </term>
        /// <term>
        /// Window background.
        /// The associated foreground colors are <see cref="COLOR_WINDOWTEXT"/> and <c>COLOR_HOTLITE</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="COLOR_WINDOWFRAME"/>
        /// </para>
        /// <para>
        /// 6
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Window frame.
        /// </para>
        /// <para>
        /// Windows 10 or greater: This value is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="COLOR_WINDOWTEXT"/>
        /// </para>
        /// <para>
        /// 8
        /// </para>
        /// </term>
        /// <term>
        /// Text in windows. The associated background color is <see cref="COLOR_WINDOW"/>.
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// </param>
        /// <returns>
        /// <para>
        /// The function returns the red, green, blue (RGB) color value of the given element.
        /// </para>
        /// <para>
        /// If the <paramref name="nIndex"/> parameter is out of range, the return value is zero.
        /// Because zero is also a valid RGB value, you cannot use <see cref="GetSysColor"/>
        /// to determine whether a system color is supported by the current platform.
        /// Instead, use the <see cref="GetSysColorBrush"/> function, which returns <see cref="NULL"/> if the color is not supported.
        /// </para>
        /// </returns>
        /// <remarks>
        /// <para>
        /// To display the component of the RGB value, use the <see cref="GetRValue"/>, <see cref="GetGValue"/>, and <see cref="GetBValue"/> macros.
        /// </para>
        /// <para>
        /// System colors for monochrome displays are usually interpreted as shades of gray.
        /// </para>
        /// <para>
        /// To paint with a system color brush, an application should use <c>GetSysColorBrush(nIndex)</c>, instead of <c>CreateSolidBrush(GetSysColor(nIndex))</c>,
        /// because <see cref="GetSysColorBrush"/> returns a cached brush, instead of allocating a new one.
        /// </para>
        /// <para>
        /// Color is an important visual element of most user interfaces.
        /// For guidelines about using color in your applications, see Color - Win32 and Color in Windows 11.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsNT40)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "GetSysColor", ExactSpelling = true)]
        public static extern DWORD GetSysColor([In] SystemColors nIndex);

        /// <summary>
        /// <para>
        /// The <see cref="GetSysColorBrush"/> function retrieves a handle identifying a logical brush that corresponds to the specified color index.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-getsyscolorbrush"/>
        /// </para>
        /// </summary>
        /// <param name="nIndex">
        /// A color index.
        /// This value corresponds to the color used to paint one of the window elements.
        /// See <see cref="GetSysColor"/> for system color index values.
        /// </param>
        /// <returns>
        /// The return value identifies a logical brush if the <paramref name="nIndex"/> parameter is supported by the current platform.
        /// Otherwise, it returns <see cref="NULL"/>.
        /// </returns>
        /// <remarks>
        /// <para>
        /// A brush is a bitmap that the system uses to paint the interiors of filled shapes.
        /// An application can retrieve the current system colors by calling the <see cref="GetSysColor"/> function.
        /// An application can set the current system colors by calling the <see cref="SetSysColors"/> function.
        /// </para>
        /// <para>
        /// An application must not register a window class for a window using a system brush.
        /// To register a window class with a system color, see the documentation of the <see cref="WNDCLASS.hbrBackground"/> member
        /// of the <see cref="WNDCLASS"/> or <see cref="WNDCLASSEX"/> structures.
        /// </para>
        /// <para>
        /// System color brushes track changes in system colors.
        /// In other words, when the user changes a system color, the associated system color brush automatically changes to the new color.
        /// </para>
        /// <para>
        /// To paint with a system color brush, an application should use <see cref="GetSysColorBrush"/>
        /// instead of <see cref="CreateSolidBrush"/> (<see cref="GetSysColor"/>),
        /// because <see cref="GetSysColorBrush"/> returns a cached brush instead of allocating a new one.
        /// </para>
        /// <para>
        /// System color brushes are owned by the system so you don't need to destroy them.
        /// Although you don't need to delete the logical brush that <see cref="GetSysColorBrush"/> returns,
        /// no harm occurs by calling <see cref="DeleteObject"/>.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsNT40)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "GetSysColorBrush", ExactSpelling = true)]
        public static extern HBRUSH GetSysColorBrush([In] SystemColors nIndex);

        /// <summary>
        /// <para>
        /// Retrieves the specified system metric or system configuration setting.
        /// </para>
        /// <para>
        /// Note that all dimensions retrieved by <see cref="GetSystemMetrics"/> are in pixels.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-getsystemmetrics"/>
        /// </para>
        /// </summary>
        /// <param name="smIndex">
        /// <para>
        /// The system metric or configuration setting to be retrieved.
        /// This parameter can be one of the following values.
        /// Note that all <c>SM_CX*</c> values are widths and all <c>SM_CY*</c> values are heights.
        /// Also note that all settings designed to return Boolean data represent <see cref="TRUE"/> as any nonzero value, and <see cref="FALSE"/> as a zero value.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Value
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_ARRANGE"/>
        /// </para>
        /// <para>
        /// 56
        /// </para>
        /// </term>
        /// <term>
        /// The flags that specify how the system arranged minimized windows.
        /// For more information, see the Remarks section in this topic.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CLEANBOOT"/>
        /// </para>
        /// <para>
        /// 67
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// The value that specifies how the system is started:
        /// </para>
        /// <para>
        /// <list type="bullet">
        /// <item>
        /// <description>
        /// 0 Normal boot
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// 1 Fail-safe boot
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// 2 Fail-safe with network boot
        /// </description>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        /// A fail-safe boot (also called SafeBoot, Safe Mode, or Clean Boot) bypasses the user startup files.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CMONITORS"/>
        /// </para>
        /// <para>
        /// 80
        /// </para>
        /// </term>
        /// <term>
        /// The number of display monitors on a desktop.
        /// For more information, see the Remarks section in this topic.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CMOUSEBUTTONS"/>
        /// </para>
        /// <para>
        /// 43
        /// </para>
        /// </term>
        /// <term>
        /// The number of buttons on a mouse, or zero if no mouse is installed.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CONVERTIBLESLATEMODE"/>
        /// </para>
        /// <para>
        /// 0x2003
        /// </para>
        /// </term>
        /// <term>
        /// Reflects the state of the laptop or slate mode, 0 for Slate Mode and non-zero otherwise.
        /// When this system metric changes, the system sends a broadcast message
        /// via <see cref="WM_SETTINGCHANGE"/> with "ConvertibleSlateMode" in the <c>LPARAM</c>.
        /// Note that this system metric doesn't apply to desktop PCs.
        /// In that case, use <see cref="GetAutoRotationState"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CXBORDER"/>
        /// </para>
        /// <para>
        /// 5
        /// </para>
        /// </term>
        /// <term>
        /// The width of a window border, in pixels.
        /// This is equivalent to the <see cref="SM_CXEDGE"/> value for windows with the 3-D look.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CXCURSOR"/>
        /// </para>
        /// <para>
        /// 13
        /// </para>
        /// </term>
        /// <term>
        /// The nominal width of a cursor, in pixels.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CXDLGFRAME"/>
        /// </para>
        /// <para>
        /// 7
        /// </para>
        /// </term>
        /// <term>
        /// This value is the same as <see cref="SM_CXFIXEDFRAME"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CXDOUBLECLK"/>
        /// </para>
        /// <para>
        /// 36
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// The width of the rectangle around the location of a first click in a double-click sequence, in pixels.
        /// The second click must occur within the rectangle that is defined by <see cref="SM_CXDOUBLECLK"/> and <see cref="SM_CYDOUBLECLK"/>
        /// for the system to consider the two clicks a double-click.
        /// The two clicks must also occur within a specified time.
        /// </para>
        /// <para>
        /// To set the width of the double-click rectangle, call <see cref="SystemParametersInfo"/> with <see cref="SPI_SETDOUBLECLKWIDTH"/>.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CXDRAG"/>
        /// </para>
        /// <para>
        /// 68
        /// </para>
        /// </term>
        /// <term>
        /// The number of pixels on either side of a mouse-down point that the mouse pointer can move before a drag operation begins.
        /// This allows the user to click and release the mouse button easily without unintentionally starting a drag operation.
        /// If this value is negative, it is subtracted from the left of the mouse-down point and added to the right of it.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CXEDGE"/>
        /// </para>
        /// <para>
        /// 45
        /// </para>
        /// </term>
        /// <term>
        /// The width of a 3-D border, in pixels.
        /// This metric is the 3-D counterpart of <see cref="SM_CXBORDER"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CXFIXEDFRAME"/>
        /// </para>
        /// <para>
        /// 7
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// The thickness of the frame around the perimeter of a window that has a caption but is not sizable, in pixels.
        /// <see cref="SM_CXFIXEDFRAME"/> is the height of the horizontal border,
        /// and <see cref="SM_CYFIXEDFRAME"/> is the width of the vertical border.
        /// </para>
        /// <para>
        /// This value is the same as <see cref="SM_CXDLGFRAME"/>.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CXFOCUSBORDER"/>
        /// </para>
        /// <para>
        /// 83
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// The width of the left and right edges of the focus rectangle that the <see cref="DrawFocusRect"/> draws.
        /// This value is in pixels.
        /// </para>
        /// <para>
        /// Windows 2000: This value is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CXFRAME"/>
        /// </para>
        /// <para>
        /// 32
        /// </para>
        /// </term>
        /// <term>
        /// This value is the same as <see cref="SM_CXSIZEFRAME"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CXFULLSCREEN"/>
        /// </para>
        /// <para>
        /// 16
        /// </para>
        /// </term>
        /// <term>
        /// The width of the client area for a full-screen window on the primary display monitor, in pixels.
        /// To get the coordinates of the portion of the screen that is not obscured by the system taskbar or by application desktop toolbars,
        /// call the <see cref="SystemParametersInfo"/> function with the <see cref="SPI_GETWORKAREA"/> value.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CXHSCROLL"/>
        /// </para>
        /// <para>
        /// 21
        /// </para>
        /// </term>
        /// <term>
        /// The width of the arrow bitmap on a horizontal scroll bar, in pixels.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CXHTHUMB"/>
        /// </para>
        /// <para>
        /// 10
        /// </para>
        /// </term>
        /// <term>
        /// The width of the thumb box in a horizontal scroll bar, in pixels.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CXICON"/>
        /// </para>
        /// <para>
        /// 11
        /// </para>
        /// </term>
        /// <term>
        /// The system large width of an icon, in pixels.
        /// The <see cref="LoadIcon"/> function can load only icons with the dimensions that <see cref="SM_CXICON"/> and <see cref="SM_CYICON"/> specifies.
        /// See Icon Sizes for more info.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CXICONSPACING"/>
