        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CXMAXIMIZED"/>
        /// </para>
        /// <para>
        /// 61
        /// </para>
        /// </term>
        /// <term>
        /// The default width, in pixels, of a maximized top-level window on the primary display monitor.
