        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CXVIRTUALSCREEN"/>
        /// </para>
        /// <para>
        /// 78
        /// </para>
        /// </term>
        /// <term>
        /// The width of the virtual screen, in pixels.
