        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYBORDER"/>
        /// </para>
        /// <para>
        /// 6
        /// </para>
        /// </term>
        /// <term>
        /// The height of a window border, in pixels.
        /// This is equivalent to the <see cref="SM_CYEDGE"/> value for windows with the 3-D look.
