        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYCAPTION"/>
        /// </para>
        /// <para>
        /// 4
        /// </para>
        /// </term>
        /// <term>
        /// The height of a caption area, in pixels.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYCURSOR"/>
        /// </para>
        /// <para>
        /// 14
        /// </para>
        /// </term>
        /// <term>
        /// The nominal height of a cursor, in pixels.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYDLGFRAME"/>
        /// </para>
        /// <para>
        /// 8
        /// </para>
        /// </term>
        /// <term>
        /// This value is the same as SM_CYFIXEDFRAME.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYDOUBLECLK"/>
        /// </para>
        /// <para>
        /// 37
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// The height of the rectangle around the location of a first click in a double-click sequence, in pixels.
        /// The second click must occur within the rectangle defined by <see cref="SM_CXDOUBLECLK"/> and <see cref="SM_CYDOUBLECLK"/>
        /// for the system to consider the two clicks a double-click.
        /// The two clicks must also occur within a specified time.
        /// </para>
        /// <para>
        /// To set the height of the double-click rectangle, call <see cref="SystemParametersInfo"/> with <see cref="SPI_SETDOUBLECLKHEIGHT"/>.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYDRAG"/>
        /// </para>
        /// <para>
        /// 69
        /// </para>
        /// </term>
        /// <term>
        /// The number of pixels above and below a mouse-down point that the mouse pointer can move before a drag operation begins.
        /// This allows the user to click and release the mouse button easily without unintentionally starting a drag operation.
        /// If this value is negative, it is subtracted from above the mouse-down point and added below it.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYEDGE"/>
        /// </para>
        /// <para>
        /// 46
        /// </para>
        /// </term>
        /// <term>
        /// The height of a 3-D border, in pixels.
        /// This is the 3-D counterpart of <see cref="SM_CYBORDER"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYFIXEDFRAME"/>
        /// </para>
        /// <para>
        /// 8
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// The thickness of the frame around the perimeter of a window that has a caption but is not sizable, in pixels.
        /// <see cref="SM_CXFIXEDFRAME"/> is the height of the horizontal border,
        /// and <see cref="SM_CYFIXEDFRAME"/> is the width of the vertical border.
        /// </para>
        /// <para>
        /// This value is the same as <see cref="SM_CYDLGFRAME"/>.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYFOCUSBORDER"/>
        /// </para>
        /// <para>
        /// 84
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// The height of the top and bottom edges of the focus rectangle drawn by <see cref="DrawFocusRect"/>.
        /// This value is in pixels.
        /// </para>
        /// <para>
        /// Windows 2000: This value is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYFRAME"/>
        /// </para>
        /// <para>
        /// 33
        /// </para>
        /// </term>
        /// <term>
        /// This value is the same as <see cref="SM_CYSIZEFRAME"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYFULLSCREEN"/>
        /// </para>
        /// <para>
        /// 17
        /// </para>
        /// </term>
        /// <term>
        /// The height of the client area for a full-screen window on the primary display monitor, in pixels.
        /// To get the coordinates of the portion of the screen not obscured by the system taskbar or by application desktop toolbars,
        /// call the <see cref="SystemParametersInfo"/> function with the <see cref="SPI_GETWORKAREA"/> value.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYHSCROLL"/>
        /// </para>
        /// <para>
        /// 3
        /// </para>
        /// </term>
        /// <term>
        /// The height of a horizontal scroll bar, in pixels.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYICON"/>
        /// </para>
        /// <para>
        /// 12
        /// </para>
        /// </term>
        /// <term>
        /// The system large height of an icon, in pixels.
        /// The <see cref="LoadIcon"/> function can load only icons with the dimensions that <see cref="SM_CXICON"/> and <see cref="SM_CYICON"/> specifies.
        /// See Icon Sizes for more info.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYICONSPACING"/>
        /// </para>
        /// <para>
        /// 39
        /// </para>
        /// </term>
        /// <term>
        /// The height of a grid cell for items in large icon view, in pixels.
        /// Each item fits into a rectangle of size <see cref="SM_CXICONSPACING"/> by <see cref="SM_CYICONSPACING"/> when arranged.
        /// This value is always greater than or equal to <see cref="SM_CYICON"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYKANJIWINDOW"/>
        /// </para>
        /// <para>
        /// 18
        /// </para>
        /// </term>
        /// <term>
        /// For double byte character set versions of the system, this is the height of the Kanji window at the bottom of the screen, in pixels.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYMAXIMIZED"/>
        /// </para>
        /// <para>
        /// 62
        /// </para>
        /// </term>
        /// <term>
        /// The default height, in pixels, of a maximized top-level window on the primary display monitor.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYMAXTRACK"/>
        /// </para>
        /// <para>
        /// 60
        /// </para>
        /// </term>
        /// <term>
        /// The default maximum height of a window that has a caption and sizing borders, in pixels.
        /// This metric refers to the entire desktop.
        /// The user cannot drag the window frame to a size larger than these dimensions.
        /// A window can override this value by processing the <see cref="WM_GETMINMAXINFO"/> message.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYMENU"/>
        /// </para>
        /// <para>
        /// 15
        /// </para>
        /// </term>
        /// <term>
        /// The height of a single-line menu bar, in pixels.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYMENUCHECK"/>
        /// </para>
        /// <para>
        /// 72
        /// </para>
        /// </term>
        /// <term>
        /// The height of the default menu check-mark bitmap, in pixels.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYMENUSIZE"/>
        /// </para>
        /// <para>
        /// 55
        /// </para>
        /// </term>
        /// <term>
        /// The height of menu bar buttons, such as the child window close button that is used in the multiple document interface, in pixels.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYMIN"/>
        /// </para>
        /// <para>
        /// 29
        /// </para>
        /// </term>
        /// <term>
        /// The minimum height of a window, in pixels.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYMINIMIZED"/>
        /// </para>
        /// <para>
        /// 58
        /// </para>
        /// </term>
        /// <term>
        /// The height of a minimized window, in pixels.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYMINSPACING"/>
        /// </para>
        /// <para>
        /// 48
        /// </para>
        /// </term>
        /// <term>
        /// The height of a grid cell for a minimized window, in pixels.
        /// Each minimized window fits into a rectangle this size when arranged.
        /// This value is always greater than or equal to <see cref="SM_CYMINIMIZED"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYMINTRACK"/>
        /// </para>
        /// <para>
        /// 35
        /// </para>
        /// </term>
        /// <term>
        /// The minimum tracking height of a window, in pixels.
        /// The user cannot drag the window frame to a size smaller than these dimensions.
        /// A window can override this value by processing the <see cref="WM_GETMINMAXINFO"/> message.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYSCREEN"/>
        /// </para>
        /// <para>
        /// 1
        /// </para>
        /// </term>
        /// <term>
        /// The height of the screen of the primary display monitor, in pixels.
        /// This is the same value obtained by calling <see cref="GetDeviceCaps"/> as follows:
        /// <c>GetDeviceCaps( hdcPrimaryMonitor, VERTRES)</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYSIZE"/>
        /// </para>
        /// <para>
        /// 31
        /// </para>
        /// </term>
        /// <term>
        /// The height of a button in a window caption or title bar, in pixels.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYSIZEFRAME"/>
        /// </para>
        /// <para>
        /// 33
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// The thickness of the sizing border around the perimeter of a window that can be resized, in pixels.
        /// <see cref="SM_CXSIZEFRAME"/> is the width of the horizontal border,
        /// and <see cref="SM_CYSIZEFRAME"/> is the height of the vertical border.
        /// </para>
        /// <para>
        /// This value is the same as <see cref="SM_CYFRAME"/>.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYSMCAPTION"/>
        /// </para>
        /// <para>
        /// 51
        /// </para>
        /// </term>
        /// <term>
        /// The height of a small caption, in pixels.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYSMICON"/>
        /// </para>
        /// <para>
        /// 50
        /// </para>
        /// </term>
        /// <term>
        /// The system small height of an icon, in pixels.
        /// Small icons typically appear in window captions and in small icon view.
        /// See Icon Sizes for more info.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYSMSIZE"/>
        /// </para>
        /// <para>
        /// 53
        /// </para>
        /// </term>
        /// <term>
        /// The height of small caption buttons, in pixels.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYVIRTUALSCREEN"/>
        /// </para>
        /// <para>
        /// 79
        /// </para>
        /// </term>
        /// <term>
        /// The height of the virtual screen, in pixels.
        /// The virtual screen is the bounding rectangle of all display monitors.
        /// The <see cref="SM_YVIRTUALSCREEN"/> metric is the coordinates for the top of the virtual screen.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYVSCROLL"/>
        /// </para>
        /// <para>
        /// 20
        /// </para>
        /// </term>
        /// <term>
        /// The height of the arrow bitmap on a vertical scroll bar, in pixels.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_CYVTHUMB"/>
        /// </para>
        /// <para>
        /// 9
        /// </para>
        /// </term>
        /// <term>
        /// The height of the thumb box in a vertical scroll bar, in pixels.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_DBCSENABLED"/>
        /// </para>
        /// <para>
        /// 42
        /// </para>
        /// </term>
        /// <term>
        /// Nonzero if User32.dll supports DBCS; otherwise, 0.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_DEBUG"/>
        /// </para>
        /// <para>
        /// 22
        /// </para>
        /// </term>
        /// <term>
        /// Nonzero if the debug version of User.exe is installed; otherwise, 0.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_DIGITIZER"/>
        /// </para>
        /// <para>
        /// 94
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Nonzero if the current operating system is Windows 7 or Windows Server 2008 R2 and the Tablet PC Input service is started; otherwise, 0.
        /// The return value is a bitmask that specifies the type of digitizer input supported by the device.
        /// For more information, see Remarks.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista and Windows XP/2000: This value is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_IMMENABLED"/>
        /// </para>
        /// <para>
        /// 82
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Nonzero if Input Method Manager/Input Method Editor features are enabled; otherwise, 0.
        /// </para>
        /// <para>
        /// <see cref="SM_IMMENABLED"/> indicates whether the system is ready to use a Unicode-based IME on a Unicode application.
        /// To ensure that a language-dependent IME works, check <see cref="SM_DBCSENABLED"/> and the system ANSI code page.
        /// Otherwise the ANSI-to-Unicode conversion may not be performed correctly,
        /// or some components like fonts or registry settings may not be present.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_MAXIMUMTOUCHES"/>
        /// </para>
        /// <para>
        /// 95
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Nonzero if there are digitizers in the system; otherwise, 0.
        /// </para>
        /// <para>
        /// <see cref="SM_MAXIMUMTOUCHES"/> returns the aggregate maximum of the maximum number of contacts supported by every digitizer in the system.
        /// If the system has only single-touch digitizers, the return value is 1.
        /// If the system has multi-touch digitizers, the return value is the number of simultaneous contacts the hardware can provide.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista and Windows XP/2000: This value is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_MEDIACENTER"/>
        /// </para>
        /// <para>
        /// 87
        /// </para>
        /// </term>
        /// <term>
        /// Nonzero if the current operating system is the Windows XP, Media Center Edition, 0 if not.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_MENUDROPALIGNMENT"/>
        /// </para>
        /// <para>
        /// 40
        /// </para>
        /// </term>
        /// <term>
        /// Nonzero if drop-down menus are right-aligned with the corresponding menu-bar item; 0 if the menus are left-aligned.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_MIDEASTENABLED"/>
        /// </para>
        /// <para>
        /// 74
        /// </para>
        /// </term>
        /// <term>
        /// Nonzero if the system is enabled for Hebrew and Arabic languages, 0 if not.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_MOUSEPRESENT"/>
        /// </para>
        /// <para>
        /// 19
        /// </para>
        /// </term>
        /// <term>
        /// Nonzero if a mouse is installed; otherwise, 0.
        /// This value is rarely zero, because of support for virtual mice and
        /// because some systems detect the presence of the port instead of the presence of a mouse.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_MOUSEHORIZONTALWHEELPRESENT"/>
        /// </para>
        /// <para>
        /// 91
        /// </para>
        /// </term>
        /// <term>
        /// Nonzero if a mouse with a horizontal scroll wheel is installed; otherwise 0.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_MOUSEWHEELPRESENT"/>
        /// </para>
        /// <para>
        /// 75
        /// </para>
        /// </term>
        /// <term>
        /// Nonzero if a mouse with a vertical scroll wheel is installed; otherwise 0.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_NETWORK"/>
        /// </para>
        /// <para>
        /// 63
        /// </para>
        /// </term>
        /// <term>
        /// The least significant bit is set if a network is present; otherwise, it is cleared.
        /// The other bits are reserved for future use.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_PENWINDOWS"/>
        /// </para>
        /// <para>
        /// 41
        /// </para>
        /// </term>
        /// <term>
        /// Nonzero if the Microsoft Windows for Pen computing extensions are installed; zero otherwise.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_REMOTECONTROL"/>
        /// </para>
        /// <para>
        /// 0x2001
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// This system metric is used in a Terminal Services environment
        /// to determine if the current Terminal Server session is being remotely controlled.
        /// Its value is nonzero if the current session is remotely controlled; otherwise, 0.
        /// </para>
        /// <para>
        /// You can use terminal services management tools such as Terminal Services Manager (tsadmin.msc) and shadow.exe to control a remote session.
        /// When a session is being remotely controlled, another user can view the contents of that session and potentially interact with it.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_REMOTESESSION"/>
        /// </para>
        /// <para>
        /// 0x1000
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// This system metric is used in a Terminal Services environment.
        /// If the calling process is associated with a Terminal Services client session, the return value is nonzero.
        /// If the calling process is associated with the Terminal Services console session, the return value is 0.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP:
        /// The console session is not necessarily the physical console.
        /// For more information, see <see cref="WTSGetActiveConsoleSessionId"/>.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_SAMEDISPLAYFORMAT"/>
        /// </para>
        /// <para>
        /// 81
        /// </para>
        /// </term>
        /// <term>
        /// Nonzero if all the display monitors have the same color format, otherwise, 0.
        /// Two displays can have the same bit depth, but different color formats.
        /// For example, the red, green, and blue pixels can be encoded with different numbers of bits,
        /// or those bits can be located in different places in a pixel color value.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_SECURE"/>
        /// </para>
        /// <para>
        /// 44
        /// </para>
        /// </term>
        /// <term>
        /// This system metric should be ignored; it always returns 0.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_SERVERR2"/>
        /// </para>
        /// <para>
        /// 89
        /// </para>
        /// </term>
        /// <term>
        /// The build number if the system is Windows Server 2003 R2; otherwise, 0.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_SHOWSOUNDS"/>
        /// </para>
        /// <para>
        /// 70
        /// </para>
        /// </term>
        /// <term>
        /// Nonzero if the user requires an application to present information visually in situations
        /// where it would otherwise present the information only in audible form; otherwise, 0.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_SHUTTINGDOWN"/>
        /// </para>
        /// <para>
        /// 0x2000
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Nonzero if the current session is shutting down; otherwise, 0.
        /// </para>
        /// <para>
        /// Windows 2000: This value is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_SLOWMACHINE"/>
        /// </para>
        /// <para>
        /// 73
        /// </para>
        /// </term>
        /// <term>
        /// Nonzero if the computer has a low-end (slow) processor; otherwise, 0.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_STARTER"/>
        /// </para>
        /// <para>
        /// 88
        /// </para>
        /// </term>
        /// <term>
        /// Nonzero if the current operating system is Windows 7 Starter Edition, Windows Vista Starter, or Windows XP Starter Edition; otherwise, 0.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_SWAPBUTTON"/>
        /// </para>
        /// <para>
        /// 23
        /// </para>
        /// </term>
        /// <term>
        /// Nonzero if the meanings of the left and right mouse buttons are swapped; otherwise, 0.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_SYSTEMDOCKED"/>
        /// </para>
        /// <para>
        /// 0x2004
        /// </para>
        /// </term>
        /// <term>
        /// Reflects the state of the docking mode, 0 for Undocked Mode and non-zero otherwise.
        /// When this system metric changes, the system sends a broadcast message
        /// via <see cref="WM_SETTINGCHANGE"/> with "SystemDockMode" in the <c>LPARAM</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_TABLETPC"/>
        /// </para>
        /// <para>
        /// 86
        /// </para>
        /// </term>
        /// <term>
        /// Nonzero if the current operating system is the Windows XP Tablet PC edition
        /// or if the current operating system is Windows Vista or Windows 7 and the Tablet PC Input service is started; otherwise, 0.
        /// The <see cref="SM_DIGITIZER"/> setting indicates the type of digitizer input supported by a device running Windows 7 or Windows Server 2008 R2.
        /// For more information, see Remarks.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_XVIRTUALSCREEN"/>
        /// </para>
        /// <para>
        /// 76
        /// </para>
        /// </term>
        /// <term>
        /// The coordinates for the left side of the virtual screen.
        /// The virtual screen is the bounding rectangle of all display monitors.
        /// The <see cref="SM_CXVIRTUALSCREEN"/> metric is the width of the virtual screen.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SM_YVIRTUALSCREEN"/>
        /// </para>
        /// <para>
        /// 77
        /// </para>
        /// </term>
        /// <term>
        /// The coordinates for the top of the virtual screen.
        /// The virtual screen is the bounding rectangle of all display monitors.
        /// The <see cref="SM_CYVIRTUALSCREEN"/> metric is the height of the virtual screen.
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// </param>
        /// <returns>
        /// If the function succeeds, the return value is the requested system metric or configuration setting.
        /// If the function fails, the return value is 0.
        /// <see cref="GetLastError"/> does not provide extended error information.
        /// </returns>
        /// <remarks>
        /// <para>
        /// System metrics can vary from display to display.
        /// </para>
        /// <para>
        /// <c>GetSystemMetrics(SM_CMONITORS)</c> counts only visible display monitors.
        /// This is different from <see cref="EnumDisplayMonitors"/>,
        /// which enumerates both visible display monitors and invisible pseudo-monitors that are associated with mirroring drivers.
        /// An invisible pseudo-monitor is associated with a pseudo-device used to mirror application drawing for remoting or other purposes.
        /// </para>
        /// <para>
        /// The <see cref="SM_ARRANGE"/> setting specifies how the system arranges minimized windows, and consists of a starting position and a direction.
        /// The starting position can be one of the following values.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Value
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <see cref="ARW_BOTTOMLEFT"/>
        /// </term>
        /// <term>
        /// Start at the lower-left corner of the screen.
        /// The default position.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <see cref="ARW_BOTTOMRIGHT"/>
        /// </term>
        /// <term>
        /// Start at the lower-right corner of the screen.
        /// Equivalent to <see cref="ARW_STARTRIGHT"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <see cref="ARW_TOPLEFT"/>
        /// </term>
        /// <term>
        /// Start at the upper-left corner of the screen.
        /// Equivalent to <see cref="ARW_STARTTOP"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <see cref="ARW_TOPRIGHT"/>
        /// </term>
        /// <term>
        /// Start at the upper-right corner of the screen.
        /// Equivalent to <c>ARW_STARTTOP | SRW_STARTRIGHT</c>.
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        /// The direction in which to arrange minimized windows can be one of the following values.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Value
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <see cref="ARW_DOWN"/>
        /// </term>
        /// <term>
        /// Arrange vertically, top to bottom.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <see cref="ARW_HIDE"/>
        /// </term>
        /// <term>
        /// Hide minimized windows by moving them off the visible area of the screen.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <see cref="ARW_LEFT"/>
        /// </term>
        /// <term>
        /// Arrange horizontally, left to right.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <see cref="ARW_RIGHT"/>
        /// </term>
        /// <term>
        /// Arrange horizontally, right to left.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <see cref="ARW_UP"/>
        /// </term>
        /// <term>
        /// Arrange vertically, bottom to top.
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        /// The <see cref="SM_DIGITIZER"/> setting specifies the type of digitizers
        /// that are installed on a device running Windows 7 or Windows Server 2008 R2.
        /// The return value is a bitmask that specifies one or more of the following values.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Value
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="NID_INTEGRATED_TOUCH"/>
        /// </para>
        /// <para>
        /// 0x01
        /// </para>
        /// </term>
        /// <term>
        /// The device has an integrated touch digitizer.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="NID_EXTERNAL_TOUCH"/>
        /// </para>
        /// <para>
        /// 0x02
        /// </para>
        /// </term>
        /// <term>
        /// The device has an external touch digitizer.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="NID_INTEGRATED_PEN"/>
        /// </para>
        /// <para>
        /// 0x04
        /// </para>
        /// </term>
        /// <term>
        /// The device has an integrated pen digitizer.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="NID_EXTERNAL_PEN"/>
        /// </para>
        /// <para>
        /// 0x08
        /// </para>
        /// </term>
        /// <term>
        /// The device has an external pen digitizer.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="NID_MULTI_INPUT"/>
        /// </para>
        /// <para>
        /// 0x40
        /// </para>
        /// </term>
        /// <term>
        /// The device supports multiple sources of digitizer input.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="NID_READY"/>
        /// </para>
        /// <para>
        /// 0x80
        /// </para>
        /// </term>
        /// <term>
        /// The device is ready to receive digitizer input.
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        /// This API is not DPI aware, and should not be used if the calling thread is per-monitor DPI aware.
        /// For the DPI-aware version of this API, see <see cref="GetSystemMetricsForDpi"/>.
        /// For more information on DPI awareness, see the Windows High DPI documentation.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsNT40)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "GetSystemMetrics", ExactSpelling = true, SetLastError = true)]
        public static extern int GetSystemMetrics([In] SystemMetricIndexes smIndex);

        /// <summary>
        /// <para>
        /// The <see cref="GetUserObjectSecurity"/> function retrieves security information for the specified user object.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-getuserobjectsecurity"/>
        /// </para>
        /// </summary>
        /// <param name="hObj">
        /// A handle to the user object for which to return security information.
        /// </param>
        /// <param name="pSIRequested">
        /// A pointer to a <see cref="SECURITY_INFORMATION"/> value that specifies the security information being requested.
        /// </param>
        /// <param name="pSID">
        /// A pointer to a <see cref="SECURITY_DESCRIPTOR"/> structure in self-relative format that contains the requested information
        /// when the function returns. This buffer must be aligned on a 4-byte boundary.
        /// </param>
        /// <param name="nLength">
        /// The length, in bytes, of the buffer pointed to by the <paramref name="pSID"/> parameter.
        /// </param>
        /// <param name="lpnLengthNeeded">
        /// A pointer to a variable to receive the number of bytes required to store the complete security descriptor.
        /// If this variable's value is greater than the value of the <paramref name="nLength"/> parameter when the function returns,
        /// the function returns <see cref="FALSE"/> and none of the security descriptor is copied to the buffer.
        /// Otherwise, the entire security descriptor is copied.
        /// </param>
        /// <returns>
        /// <para>
        /// If the function succeeds, the function returns nonzero.
        /// </para>
        /// <para>
        /// If the function fails, it returns zero.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </para>
        /// </returns>
        /// <remarks>
        /// <para>
        /// To read the owner, group, or discretionary access control list (DACL) from the user object's security descriptor,
        /// the calling process must have been granted <see cref="READ_CONTROL"/> access when the handle was opened.
        /// </para>
        /// <para>
        /// To read the system access control list (SACL) from the security descriptor,
        /// the calling process must have been granted <see cref="ACCESS_SYSTEM_SECURITY"/> access when the handle was opened.
        /// The correct way to get this access is to enable the <see cref="SE_SECURITY_NAME"/> privilege in the caller's current token,
        /// open the handle for <see cref="ACCESS_SYSTEM_SECURITY"/> access, and then disable the privilege.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsNT40)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "GetUserObjectSecurity", ExactSpelling = true, SetLastError = true)]
        public static extern BOOL GetUserObjectSecurity([In] HANDLE hObj, [In] in SECURITY_INFORMATION pSIRequested,
            [In] PSECURITY_DESCRIPTOR pSID, [In] DWORD nLength, [Out] out DWORD lpnLengthNeeded);

        /// <summary>
        /// <para>
        /// Retrieves the signed x-coordinate from the specified <see cref="LPARAM"/> value.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/windowsx/nf-windowsx-get_x_lparam"/>
        /// </para>
        /// </summary>
        /// <param name="lp">
        /// The data from which the x-coordinate is to be extracted.
        /// </param>
        /// <returns>
        /// X-coordinate.
        /// </returns>
        /// <remarks>
        /// Use <see cref="GET_X_LPARAM"/> instead of <see cref="LOWORD"/> to extract signed coordinate data.
        /// Negative screen coordinates may be returned on multiple monitor systems.
        /// </remarks>
        public static int GET_X_LPARAM(DWORD lp) => (short)LOWORD(lp);

        /// <summary>
        /// <para>
        /// Retrieves the signed y-coordinate from the given <see cref="LPARAM"/> value.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/windowsx/nf-windowsx-get_y_lparam"/>
        /// </para>
        /// </summary>
        /// <param name="lp">
        /// The data from which the y-coordinate is to be extracted.
        /// </param>
        /// <returns>
        /// Y-coordinate.
        /// </returns>
        /// <remarks>
        /// Use <see cref="GET_Y_LPARAM"/> instead of <see cref="HIWORD"/> to extract signed coordinate data.
        /// Negative screen coordinates may be returned on multiple monitor systems.
        /// </remarks>
        public static int GET_Y_LPARAM(DWORD lp) => (short)HIWORD(lp);

        /// <summary>
        /// <para>
        /// Retrieves the high-order word from the specified 32-bit value.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/winmsg/hiword"/>
        /// </para>
        /// </summary>
        /// <param name="l">
        /// The value to be converted.
        /// </param>
        /// <returns>
        /// The return value is the high-order word of the specified value.
        /// </returns>
        public static WORD HIWORD(DWORD l) => unchecked((ushort)(((uint)l) >> 16));

        /// <summary>
        /// <para>
        /// Determines whether the calling thread is already a GUI thread.
        /// It can also optionally convert the thread to a GUI thread.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-isguithread"/>
        /// </para>
        /// </summary>
        /// <param name="bConvert">
        /// If <see cref="TRUE"/> and the thread is not a GUI thread, convert the thread to a GUI thread.
        /// </param>
        /// <returns>
        /// <para>
        /// The function returns a nonzero value in the following situations:
        /// </para>
        /// <para>
        /// <list type="bullet">
        /// <item>
        /// <description>
        /// If the calling thread is already a GUI thread.
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// If <paramref name="bConvert"/> is <see cref="TRUE"/> and the function successfully converts the thread to a GUI thread.
        /// </description>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        /// Otherwise, the function returns zero.
        /// </para>
        /// <para>
        /// If <paramref name="bConvert"/> is <see cref="TRUE"/> and the function cannot successfully convert the thread to a GUI thread,
        /// <see cref="IsGUIThread"/> returns <see cref="ERROR_NOT_ENOUGH_MEMORY"/>.
        /// </para>
        /// </returns>
        [WindowsVersionRequirement(WindowsVersion.WindowsXP)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "IsGUIThread", ExactSpelling = true, SetLastError = true)]
        public static extern BOOL IsGUIThread([In] BOOL bConvert);

        /// <summary>
        /// <para>
        /// Determines whether there is an installed WinEvent hook that might be notified of a specified event.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-iswineventhookinstalled"/>
        /// </para>
        /// </summary>
        /// <param name="event">
        /// The event constant that hooks might be notified of.
        /// The function checks whether there is an installed hook for this event constant.
        /// </param>
        /// <returns>
        /// <para>
        /// If there is a hook to be notified of the specified event, the return value is <see cref="TRUE"/>.
        /// </para>
        /// <para>
        /// If there are no hooks to be notified of the specified event, the return value is <see cref="FALSE"/>.
        /// </para>
        /// </returns>
        /// <remarks>
        /// <para>
        /// This method is guaranteed to never return a false negative.
        /// If this method returns <see cref="FALSE"/>, it means that no hooks in the system would be notified of the event.
        /// However, this method may return a false positive.
        /// In other words, it may return <see cref="TRUE"/> even though there are no hooks that would be notified.
        /// Thus, it is safe for components to circumvent some work if this method returns <see cref="FALSE"/>.
        /// </para>
        /// <para>
        /// Event hooks can be installed at any time, so server developers should not cache the return value for long periods of time.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsXP)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "IsWinEventHookInstalled", ExactSpelling = true)]
        public static extern BOOL IsWinEventHookInstalled([In] EventConstants @event);

        /// <summary>
        /// <para>
        /// Destroys the specified timer.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-killtimer"/>
        /// </para>
        /// </summary>
        /// <param name="hWnd">
        /// A handle to the window associated with the specified timer.
        /// This value must be the same as the hWnd value passed to the <see cref="SetTimer"/> function that created the timer.
        /// </param>
        /// <param name="uIDEvent">
        /// <para>
        /// The timer to be destroyed.
        /// If the window handle passed to <see cref="SetTimer"/> is valid, this parameter must be the same as the <paramref name="uIDEvent"/>
        /// </para>
        /// <para>
        /// value passed to <see cref="SetTimer"/>.
        /// If the application calls <see cref="SetTimer"/> with <paramref name="hWnd"/> set to <see cref="NULL"/>,
        /// this parameter must be the timer identifier returned by <see cref="SetTimer"/>.
        /// </para>
        /// </param>
        /// <returns>
        /// <para>
        /// If the function succeeds, the return value is nonzero.
        /// </para>
        /// <para>
        /// If the function fails, the return value is zero.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </para>
        /// </returns>
        /// <remarks>
        /// The <see cref="KillTimer"/> function does not remove <see cref="WM_TIMER"/> messages already posted to the message queue.
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsNT40)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "KillTimer", ExactSpelling = true, SetLastError = true)]
        public static extern BOOL KillTimer([In] HWND hWnd, [In] UINT_PTR uIDEvent);

        /// <summary>
        /// <para>
        /// Locks the workstation's display. Locking a workstation protects it from unauthorized use.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-lockworkstation"/>
        /// </para>
        /// </summary>
        /// <returns>
        /// <para>
        /// If the function succeeds, the return value is nonzero.
        /// Because the function executes asynchronously, a nonzero return value indicates that the operation has been initiated.
        /// It does not indicate whether the workstation has been successfully locked.
        /// </para>
        /// <para>
        /// If the function fails, the return value is zero.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </para>
        /// </returns>
        /// <remarks>
        /// <para>
        /// The <see cref="LockWorkStation"/> function is callable only by processes running on the interactive desktop.
        /// In addition, the user must be logged on, and the workstation cannot already be locked.
        /// </para>
        /// <para>
        /// Common reasons the workstation might not be locked even if the function succeeds include the following:
        /// no user is logged on, the workstation is already locked, the process is not running on the interactive desktop,
        /// or the request is denied by the Graphical Identification and Authentication (GINA) DLL.
        /// </para>
        /// <para>
        /// This function has the same result as pressing Ctrl+Alt+Del and clicking <c>Lock</c>.
        /// To unlock the workstation, the user must log in.
        /// There is no function you can call to determine whether the workstation is locked.
        /// To receive a notification when the user locks the workstation or logs in,
        /// use the <see cref="WTSRegisterSessionNotification"/> function to receive <see cref="WM_WTSSESSION_CHANGE"/> messages.
        /// You can use session notifications to track the desktop state so you know whether it is possible to interact with the user.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.Windows2000)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "LockWorkStation", ExactSpelling = true, SetLastError = true)]
        public static extern BOOL LockWorkStation();

        /// <summary>
        /// <para>
        /// Converts the logical coordinates of a point in a window to physical coordinates.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-logicaltophysicalpoint"/>
        /// </para>
        /// </summary>
        /// <param name="hWnd">
        /// A handle to the window whose transform is used for the conversion.
        /// Top level windows are fully supported.
        /// In the case of child windows, only the area of overlap between the parent and the child window is converted.
        /// </param>
        /// <param name="lpPoint">
        /// A pointer to a <see cref="POINT"/> structure that specifies the logical coordinates to be converted.
        /// The new physical coordinates are copied into this structure if the function succeeds.
        /// </param>
        /// <returns>
        /// </returns>
        /// <remarks>
        /// <para>
        /// Windows Vista introduces the concept of physical coordinates.
        /// Desktop Window Manager (DWM) scales non-dots per inch (dpi) aware windows when the display is high dpi.
        /// The window seen on the screen corresponds to the physical coordinates.
        /// The application continues to work in logical space.
        /// Therefore, the application's view of the window is different from that which appears on the screen.
        /// For scaled windows, logical and physical coordinates are different.
        /// </para>
        /// <para>
        /// <see cref="LogicalToPhysicalPoint"/> is a transformation API that can be called by a process that declares itself as dpi aware.
        /// The function uses the window identified by the <paramref name="hWnd"/> parameter and the logical coordinates
        /// given in the <see cref="POINT"/> structure to compute the physical coordinates.
        /// </para>
        /// <para>
        /// The <see cref="LogicalToPhysicalPoint"/> function replaces the logical coordinates in the <see cref="POINT"/> structure with the physical coordinates.
        /// The physical coordinates are relative to the upper-left corner of the screen. The coordinates have to be inside the client area of <paramref name="hWnd"/>.
        /// </para>
        /// <para>
        /// On all platforms, <see cref="LogicalToPhysicalPoint"/> will fail on a window that has either 0 width or height;
        /// an application must first establish a non-0 width and height by calling, for example, <see cref="MoveWindow"/>.
        /// On some versions of Windows (including Windows 7), <see cref="LogicalToPhysicalPoint"/> will still fail
        /// if <see cref="MoveWindow"/> has been called after a call to <see cref="ShowWindow"/> with <see cref="SW_HIDE"/> has hidden the window.
        /// </para>
        /// <para>
        /// In Windows 8, system–DPI aware applications translate between physical and logical space
        /// using <see cref="PhysicalToLogicalPoint"/> and <see cref="LogicalToPhysicalPoint"/>.
        /// In Windows 8.1, the additional virtualization of the system and inter-process communications means
        /// that for the majority of applications, you do not need these APIs.
        /// As a result, in Windows 8.1, <see cref="PhysicalToLogicalPoint"/> and <see cref="LogicalToPhysicalPoint"/> no longer transform points.
        /// The system returns all points to an application in its own coordinate space.
        /// This behavior preserves functionality for the majority of applications,
        /// but there are some exceptions in which you must make changes to ensure that the application works as expected.
        /// In those cases, use <see cref="PhysicalToLogicalPointForPerMonitorDPI"/> and <see cref="LogicalToPhysicalPointForPerMonitorDPI"/>.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsVista)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "LogicalToPhysicalPoint", ExactSpelling = true)]
        public static extern BOOL LogicalToPhysicalPoint([In] HWND hWnd, [In][Out] ref POINT lpPoint);

        /// <summary>
        /// <para>
        /// Retrieves the low-order word from the specified value.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/winmsg/loword"/>
        /// </para>
        /// </summary>
        /// <param name="l">
        /// The value to be converted.
        /// </param>
        /// <returns>
        /// The return value is the low-order word of the specified value.
        /// </returns>
        public static WORD LOWORD(DWORD l) => unchecked((ushort)(uint)l);

        /// <summary>
        /// <para>
        /// Plays a waveform sound.
        /// The waveform sound for each sound type is identified by an entry in the registry.
        /// </para>
        /// <para>
        /// Note
        /// </para>
        /// <para>
        /// On Windows Server 2022, the <c>Microsoft\Windows\Multimedia\SystemSoundsService</c> task in Task Scheduler is disabled.
        /// This task will need to be enabled for <see cref="MessageBeep"/> to function.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-messagebeep"/>
        /// </para>
        /// </summary>
        /// <param name="uType">
        /// <para>
        /// The sound to be played.
        /// The sounds are set by the user through the Sound control panel application, and then stored in the registry.
        /// </para>
        /// <para>
        /// This parameter can be one of the following values.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Value
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// 0xFFFFFFFF
        /// </term>
        /// <term>
        /// A simple beep.
        /// If the sound card is not available, the sound is generated using the speaker.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="MB_ICONASTERISK"/>
        /// </para>
        /// <para>
        /// 0x00000040L
        /// </para>
        /// </term>
        /// <term>
        /// See <see cref="MB_ICONINFORMATION"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="MB_ICONEXCLAMATION"/>
        /// </para>
        /// <para>
        /// 0x00000030L
        /// </para>
        /// </term>
        /// <term>
        /// See <see cref="MB_ICONWARNING"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="MB_ICONERROR"/>
        /// </para>
        /// <para>
        /// 0x00000010L
        /// </para>
        /// </term>
        /// <term>
        /// The sound specified as the Windows Critical Stop sound.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="MB_ICONHAND"/>
        /// </para>
        /// <para>
        /// 0x00000010L
        /// </para>
        /// </term>
        /// <term>
        /// See <see cref="MB_ICONERROR"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="MB_ICONINFORMATION"/>
        /// </para>
        /// <para>
        /// 0x00000040L
        /// </para>
        /// </term>
        /// <term>
        /// The sound specified as the Windows Asterisk sound.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="MB_ICONQUESTION"/>
        /// </para>
        /// <para>
        /// 0x00000020L
        /// </para>
        /// </term>
        /// <term>
        /// The sound specified as the Windows Question sound.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="MB_ICONSTOP"/>
        /// </para>
        /// <para>
        /// 0x00000010L
        /// </para>
        /// </term>
        /// <term>
        /// See <see cref="MB_ICONERROR"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="MB_ICONWARNING"/>
        /// </para>
        /// <para>
        /// 0x00000030L
        /// </para>
        /// </term>
        /// <term>
        /// The sound specified as the Windows Exclamation sound.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="MB_OK"/>
        /// </para>
        /// <para>
        /// 0x00000000L
        /// </para>
        /// </term>
        /// <term>
        /// The sound specified as the Windows Default Beep sound.
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// </param>
        /// <returns>
        /// <para>
        /// If the function succeeds, the return value is nonzero.
        /// </para>
        /// <para>
        /// If the function fails, the return value is zero.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </para>
        /// </returns>
        /// <remarks>
        /// <para>
        /// After queuing the sound, the <see cref="MessageBeep"/> function returns control to the calling function and plays the sound asynchronously.
        /// </para>
        /// <para>
        /// If it cannot play the specified alert sound, <see cref="MessageBeep"/> attempts to play the system default sound.
        /// If it cannot play the system default sound, the function produces a standard beep sound using the <see cref="Beep"/> function.
        /// Starting in Windows 7, this plays a simple tone on the default sound device.
        /// See the documentation for the <see cref="Beep"/> function for further details.
        /// </para>
        /// <para>
        /// The user can disable the warning beep by using the Sound control panel application.
        /// </para>
        /// <para>
        /// Note  To send a beep to a remote client, use the <see cref="Beep"/> function.
        /// The <see cref="Beep"/> function is redirected to the client, whereas <see cref="MessageBeep"/> is not.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsNT40)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "MessageBeep", ExactSpelling = true, SetLastError = true)]
        public static extern BOOL MessageBeep([In] MessageBoxFlags uType);

        /// <summary>
        /// <para>
        /// Signals the system that a predefined event occurred.
        /// If any client applications have registered a hook function for the event, the system calls the client's hook function.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-notifywinevent"/>
        /// </para>
        /// </summary>
        /// <param name="event">
        /// Specifies the event that occurred.
        /// This value must be one of the event constants.
        /// </param>
        /// <param name="hwnd">
        /// Handle to the window that contains the object that generated the event.
        /// </param>
        /// <param name="idObject">
        /// Identifies the object that generated the event.
        /// This value is either one of the predefined object identifiers or a custom object ID value.
        /// </param>
        /// <param name="idChild">
        /// Identifies whether the event was generated by an object or by a child element of the object.
        /// If this value is <see cref="CHILDID_SELF"/>, the event was generated by the object itself.
        /// If not <see cref="CHILDID_SELF"/>, this value is the child ID of the element that generated the event.
        /// </param>
        /// <remarks>
        /// <para>
        /// Servers call this function to notify the system that an event has occurred.
        /// Microsoft Active Accessibility checks to see if any client applications have set hook procedures for the event
        /// and, if so, calls the appropriate hook procedures.
        /// </para>
        /// <para>
        /// If no hook procedures are registered for the event, the performance penalty for calling this function is minor.
        /// </para>
        /// <para>
        /// Servers call <see cref="NotifyWinEvent"/> to announce the event to the system after the event has occurred;
        /// they must never notify the system of an event before the event has occurred.
        /// </para>
        /// <para>
        /// When the client's hook procedure is called, it receives a number of parameters that describe the event and the object that generated the event.
        /// The hook procedure uses the <see cref="AccessibleObjectFromEvent"/> function
        /// to retrieve a pointer to the <see cref="IAccessible"/> interface of the object that generated the event.
        /// </para>
        /// <para>
        /// Servers may receive a <see cref="WM_GETOBJECT"/> message immediately after calling this function.
        /// This can happen if there are any in-context clients that call <see cref="AccessibleObjectFromEvent"/> in the event callback.
        /// </para>
        /// <para>
        /// When servers call this function, they must be ready to handle <see cref="WM_GETOBJECT"/>,
        /// return an <see cref="IAccessible"/> interface pointer, and handle any of the <see cref="IAccessible"/> methods.
        /// </para>
        /// <para>
        /// Note to Server Developers: When you call <see cref="NotifyWinEvent"/>,
        /// if any clients are listening for that event in-context, their event handlers,
        /// which typically send <see cref="WM_GETOBJECT"/> and call <see cref="IAccessible"/> methods,
        /// will execute before <see cref="NotifyWinEvent"/> returns.
        /// When you call <see cref="NotifyWinEvent"/>, you should be prepared to handle these calls, if they occur.
        /// If you need to do extra setup to allow for this, you should do so before you call <see cref="NotifyWinEvent"/>, not after.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.Windows2000)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "NotifyWinEvent", ExactSpelling = true)]
        public static extern void NotifyWinEvent([In] EventConstants @event, [In] HWND hwnd, [In] LONG idObject, [In] LONG idChild);

        /// <summary>
        /// <para>
        /// Converts the physical coordinates of a point in a window to logical coordinates.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-physicaltologicalpoint"/>
        /// </para>
        /// </summary>
        /// <param name="hWnd">
        /// A handle to the window whose transform is used for the conversion.
        /// Top level windows are fully supported.
        /// In the case of child windows, only the area of overlap between the parent and the child window is converted.
        /// </param>
        /// <param name="lpPoint">
        /// A pointer to a <see cref="POINT"/> structure that specifies the physical/screen coordinates to be converted.
        /// The new logical coordinates are copied into this structure if the function succeeds.
        /// </param>
        /// <returns></returns>
        /// <remarks>
        /// <para>
        /// Windows Vista introduces the concept of physical coordinates.
        /// Desktop Window Manager (DWM) scales non-dots per inch (dpi) aware windows when the display is high dpi.
        /// The window seen on the screen corresponds to the physical coordinates.
        /// The application continues to work in logical space.
        /// Therefore, the application's view of the window is different from that which appears on the screen.
        /// For scaled windows, logical and physical coordinates are different.
        /// </para>
        /// <para>
        /// <see cref="LogicalToPhysicalPoint"/> is a transformation API that can be called by a process that declares itself as dpi aware.
        /// The function uses the window identified by the <paramref name="hWnd"/> parameter and the logical coordinates
        /// given in the <see cref="POINT"/> structure to compute the physical coordinates.
        /// </para>
        /// <para>
        /// The <see cref="LogicalToPhysicalPoint"/> function replaces the logical coordinates in the <see cref="POINT"/> structure with the physical coordinates.
        /// The physical coordinates are relative to the upper-left corner of the screen. The coordinates have to be inside the client area of <paramref name="hWnd"/>.
        /// </para>
        /// <para>
        /// On all platforms, <see cref="LogicalToPhysicalPoint"/> will fail on a window that has either 0 width or height;
        /// an application must first establish a non-0 width and height by calling, for example, <see cref="MoveWindow"/>.
        /// On some versions of Windows (including Windows 7), <see cref="LogicalToPhysicalPoint"/> will still fail
        /// if <see cref="MoveWindow"/> has been called after a call to <see cref="ShowWindow"/> with <see cref="SW_HIDE"/> has hidden the window.
        /// </para>
        /// <para>
        /// In Windows 8, system–DPI aware applications translate between physical and logical space
        /// using <see cref="PhysicalToLogicalPoint"/> and <see cref="LogicalToPhysicalPoint"/>.
        /// In Windows 8.1, the additional virtualization of the system and inter-process communications means
        /// that for the majority of applications, you do not need these APIs.
        /// As a result, in Windows 8.1, <see cref="PhysicalToLogicalPoint"/> and <see cref="LogicalToPhysicalPoint"/> no longer transform points.
        /// The system returns all points to an application in its own coordinate space.
        /// This behavior preserves functionality for the majority of applications,
        /// but there are some exceptions in which you must make changes to ensure that the application works as expected.
        /// In those cases, use <see cref="PhysicalToLogicalPointForPerMonitorDPI"/> and <see cref="LogicalToPhysicalPointForPerMonitorDPI"/>.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsVista)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "PhysicalToLogicalPoint", ExactSpelling = true)]
        public static extern BOOL PhysicalToLogicalPoint([In] HWND hWnd, [In][Out] ref POINT lpPoint);

        /// <summary>
        /// <para>
        /// Registers the device or type of device for which a window will receive notifications.
        /// </para>
        /// <para>
        ///  Note
        /// </para>
        /// <para>
        /// You can use <see cref="CM_Register_Notification"/> instead of <see cref="RegisterDeviceNotification"/>
        /// if your code targets Windows 8 or newer versions of Windows.
        /// The advantage of <see cref="CM_Register_Notification"/> is that it does not require a window handle to work.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-registerdevicenotificationw"/>
        /// </para>
        /// </summary>
        /// <param name="hRecipient">
        /// <para>
        /// A handle to the window or service that will receive device events for the devices
        /// specified in the <paramref name="NotificationFilter"/> parameter.
        /// The same window handle can be used in multiple calls to <see cref="RegisterDeviceNotification"/>.
        /// </para>
        /// <para>
        /// Services can specify either a window handle or service status handle.
        /// </para>
        /// </param>
        /// <param name="NotificationFilter">
        /// A pointer to a block of data that specifies the type of device for which notifications should be sent.
        /// This block always begins with the <see cref="DEV_BROADCAST_HDR"/> structure.
        /// The data following this header is dependent on the value of the <see cref="DEV_BROADCAST_HDR.dbch_devicetype"/> member,
        /// which can be <see cref="DBT_DEVTYP_DEVICEINTERFACE"/> or <see cref="DBT_DEVTYP_HANDLE"/>.
        /// For more information, see Remarks.
        /// </param>
        /// <param name="Flags">
        /// <para>
        /// This parameter can be one of the following values.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Value
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="DEVICE_NOTIFY_WINDOW_HANDLE"/>
        /// </para>
        /// <para>
        /// 0x00000000
        /// </para>
        /// </term>
        /// <term>
        /// The <paramref name="hRecipient"/> parameter is a window handle.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="DEVICE_NOTIFY_SERVICE_HANDLE"/>
        /// </para>
        /// <para>
        /// 0x00000001
        /// </para>
        /// </term>
        /// <term>
        /// The <paramref name="hRecipient"/> parameter is a service status handle.
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        /// In addition, you can specify the following value.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Value
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="DEVICE_NOTIFY_ALL_INTERFACE_CLASSES"/>
        /// </para>
        /// <para>
        /// 0x00000004
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Notifies the recipient of device interface events for all device interface classes.
        /// (The <see cref="DEV_BROADCAST_HDR.dbcc_classguid"/> member is ignored.)
        /// </para>
        /// <para>
        /// This value can be used only if the <see cref="DEV_BROADCAST_HDR.dbch_devicetype"/> member is <see cref="DBT_DEVTYP_DEVICEINTERFACE"/>.
        /// </para>
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// </param>
        /// <returns>
        /// <para>
        /// If the function succeeds, the return value is a device notification handle.
        /// </para>
        /// <para>
        /// If the function fails, the return value is <see cref="NULL"/>.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </para>
        /// </returns>
        /// <remarks>
        /// <para>
        /// Applications send event notifications using the <see cref="BroadcastSystemMessage"/> function.
        /// Any application with a top-level window can receive basic notifications by processing the <see cref="WM_DEVICECHANGE"/> message.
        /// Applications can use the <see cref="RegisterDeviceNotification"/> function to register to receive device notifications.
        /// </para>
        /// <para>
        /// Services can use the <see cref="RegisterDeviceNotification"/> function to register to receive device notifications.
        /// If a service specifies a window handle in the <paramref name="hRecipient"/> parameter,
        /// the notifications are sent to the window procedure.
        /// If <paramref name="hRecipient"/> is a service status handle,
        /// <see cref="SERVICE_CONTROL_DEVICEEVENT"/> notifications are sent to the service control handler.
        /// For more information about the service control handler, see <c>HandlerEx</c>.
        /// </para>
        /// <para>
        /// Be sure to handle Plug and Play device events as quickly as possible.
        /// Otherwise, the system may become unresponsive.
        /// If your event handler is to perform an operation that may block execution (such as I/O),
        /// it is best to start another thread to perform the operation asynchronously.
        /// </para>
        /// <para>
        /// Device notification handles returned by <see cref="RegisterDeviceNotification"/> must be closed
        /// by calling the <see cref="UnregisterDeviceNotification"/> function when they are no longer needed.
        /// </para>
        /// <para>
        /// The <see cref="DBT_DEVICEARRIVAL"/> and <see cref="DBT_DEVICEREMOVECOMPLETE"/> events
        /// are automatically broadcast to all top-level windows for port devices.
        /// Therefore, it is not necessary to call <see cref="RegisterDeviceNotification"/> for ports,
        /// and the function fails if the <see cref="DEV_BROADCAST_HDR.dbch_devicetype"/> member is <see cref="DBT_DEVTYP_PORT"/>.
        /// Volume notifications are also broadcast to top-level windows,
        /// so the function fails if <see cref="DEV_BROADCAST_HDR.dbch_devicetype"/> is <see cref="DBT_DEVTYP_VOLUME"/>.
        /// OEM-defined devices are not used directly by the system,
        /// so the function fails if <see cref="DEV_BROADCAST_HDR.dbch_devicetype"/> is <see cref="DBT_DEVTYP_OEM"/>.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.Windows2000)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "RegisterDeviceNotificationW", ExactSpelling = true, SetLastError = true)]
        public static extern HDEVNOTIFY RegisterDeviceNotification([In] HANDLE hRecipient, [In] LPVOID NotificationFilter, [In] DWORD Flags);

        /// <summary>
        /// <para>
        /// Registers the application to receive power setting notifications for the specific power setting event.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-registerpowersettingnotification"/>
        /// </para>
        /// </summary>
        /// <param name="hRecipient">
        /// Handle indicating where the power setting notifications are to be sent.
        /// For interactive applications, the <paramref name="Flags"/> parameter should be
        /// <see cref="RegisterPowerSettingNotificationFlags.DEVICE_NOTIFY_WINDOW_HANDLE"/>,
        /// and the <paramref name="hRecipient"/> parameter should be a window handle. 
        /// For services, the <paramref name="Flags"/> parameter should be
        /// <see cref="RegisterPowerSettingNotificationFlags.DEVICE_NOTIFY_SERVICE_HANDLE"/>,
        /// and the <paramref name="hRecipient"/> parameter should be a <see cref="SERVICE_STATUS_HANDLE"/> as returned
        /// from <see cref="RegisterServiceCtrlHandlerEx"/>.
        /// </param>
        /// <param name="PowerSettingGuid">
        /// The <see cref="GUID"/> of the power setting for which notifications are to be sent.
        /// For more information see Registering for Power Events.
        /// </param>
        /// <param name="Flags">
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Value
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="DEVICE_NOTIFY_WINDOW_HANDLE"/>
        /// </para>
        /// <para>
        /// 0
        /// </para>
        /// </term>
        /// <term>
        /// Notifications are sent using <see cref="WM_POWERBROADCAST"/> messages with a <c>wParam</c> parameter of <see cref="PBT_POWERSETTINGCHANGE"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="DEVICE_NOTIFY_SERVICE_HANDLE"/>
        /// </para>
        /// <para>
        /// 1
        /// </para>
        /// </term>
        /// <term>
        /// Notifications are sent to the <see cref="HandlerEx"/> callback function
        /// with a <c>dwControl</c> parameter of <see cref="SERVICE_CONTROL_POWEREVENT"/> and a <c>dwEventType</c> of <see cref="PBT_POWERSETTINGCHANGE"/>.
        /// </term>
        /// </item>
        /// </list>
        /// </param>
        /// <returns>
        /// Returns a notification handle for unregistering for power notifications.
        /// If the function fails, the return value is <see cref="NULL"/>.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </returns>
        [WindowsVersionRequirement(WindowsVersion.WindowsVista)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "RegisterPowerSettingNotification", ExactSpelling = true, SetLastError = true)]
        public static extern HPOWERNOTIFY RegisterPowerSettingNotification([In] HANDLE hRecipient, [In] in GUID PowerSettingGuid,
            [In] RegisterPowerSettingNotificationFlags Flags);

        /// <summary>
        /// <para>
        /// Creates a timer with the specified time-out value and coalescing tolerance delay.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-setcoalescabletimer"/>
        /// </para>
        /// </summary>
        /// <param name="hWnd">
        /// A handle to the window to be associated with the timer.
        /// This window must be owned by the calling thread.
        /// If a <see cref="NULL"/> value for <paramref name="hWnd"/> is passed in along with an <paramref name="nIDEvent"/> of an existing timer,
        /// that timer will be replaced in the same way that an existing non-<see cref="NULL"/> <paramref name="hWnd"/> timer will be.
        /// </param>
        /// <param name="nIDEvent">
        /// A timer identifier.
        /// If the <paramref name="hWnd"/> parameter is <see cref="NULL"/>, and the <paramref name="nIDEvent"/> does not match an existing timer,
        /// then the <paramref name="nIDEvent"/> is ignored and a new timer ID is generated.
        /// If the <paramref name="hWnd"/> parameter is not <see cref="NULL"/> and the window
        /// specified by <paramref name="hWnd"/> already has a timer with the value <paramref name="nIDEvent"/>,
        /// then the existing timer is replaced by the new timer.
        /// When <see cref="SetCoalescableTimer"/> replaces a timer, the timer is reset.
        /// Therefore, a message will be sent after the current time-out value elapses, but the previously set time-out value is ignored.
        /// If the call is not intended to replace an existing timer, <paramref name="nIDEvent"/> should be 0 if the <paramref name="hWnd"/> is <see cref="NULL"/>.
        /// </param>
        /// <param name="uElapse">
        /// <para>
        /// The time-out value, in milliseconds.
        /// </para>
        /// <para>
        /// If <paramref name="uElapse"/> is less than <see cref="USER_TIMER_MINIMUM"/> (0x0000000A), the timeout is set to <see cref="USER_TIMER_MINIMUM"/>.
        /// If <paramref name="uElapse"/> is greater than <see cref="USER_TIMER_MAXIMUM"/> (0x7FFFFFFF), the timeout is set to <see cref="USER_TIMER_MAXIMUM"/>.
        /// </para>
        /// <para>
        /// If the sum of <paramref name="uElapse"/> and <paramref name="uToleranceDelay"/> exceeds <see cref="USER_TIMER_MAXIMUM"/>,
        /// an <see cref="ERROR_INVALID_PARAMETER"/> exception occurs
        /// </para>
        /// </param>
        /// <param name="lpTimerFunc">
        /// A pointer to the function to be notified when the time-out value elapses.
        /// For more information about the function, see <c>TimerProc</c>.
        /// If <paramref name="lpTimerFunc"/> is <see cref="NULL"/>, the system posts a <see cref="WM_TIMER"/> message to the application queue.
        /// The <paramref name="hWnd"/> member of the message's <see cref="MSG"/> structure contains the value of the <paramref name="hWnd"/> parameter.
        /// </param>
        /// <param name="uToleranceDelay">
        /// <para>
        /// It can be one of the following values:
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Value
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="TIMERV_DEFAULT_COALESCING"/>
        /// </para>
        /// <para>
        /// 0x00000000
        /// </para>
        /// </term>
        /// <term>
        /// Uses the system default timer coalescing.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="TIMERV_NO_COALESCING"/>
        /// </para>
        /// <para>
        /// 0xFFFFFFFF
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Uses no timer coalescing. When this value is used, the created timer is not coalesced,
        /// no matter what the system default timer coalescing is or the application compatibility flags are.
        /// </para>
        /// <para>
        /// Note
        /// </para>
        /// <para>
        /// Do not use this value unless you are certain that the timer requires no coalescing. 
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// 0x1 - 0x7FFFFFF5
        /// </term>
        /// <term>
        /// <para>
        /// Specifies the coalescing tolerance delay, in milliseconds.
        /// </para>
        /// <para>
        /// Applications should set this value to the system default (<see cref="TIMERV_DEFAULT_COALESCING"/>) or the largest value possible.
        /// </para>
        /// <para>
        /// If the sum of <paramref name="uElapse"/> and <paramref name="uToleranceDelay"/> exceeds <see cref="USER_TIMER_MAXIMUM"/> (0x7FFFFFFF),
        /// an <see cref="ERROR_INVALID_PARAMETER"/> exception occurs.
        /// </para>
        /// <para>
        /// See Windows Timer Coalescing for more details and best practices.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// Any other value
        /// </term>
        /// <term>
        /// An invalid value.
        /// If <paramref name="uToleranceDelay"/> is set to an invalid value, the function fails and returns zero.
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// </param>
        /// <returns>
        /// <para>
        /// If the function succeeds and the <paramref name="hWnd"/> parameter is <see cref="NULL"/>,
        /// the return value is an integer identifying the new timer.
        /// An application can pass this value to the <see cref="KillTimer"/> function to destroy the timer.
        /// </para>
        /// <para>
        /// If the function succeeds and the <paramref name="hWnd"/> parameter is not <see cref="NULL"/>,
        /// then the return value is a nonzero integer.
        /// An application can pass the value of the <paramref name="nIDEvent"/> parameter to the <see cref="KillTimer"/> function to destroy the timer.
        /// </para>
        /// <para>
        /// If the function fails to create a timer, the return value is zero.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </para>
        /// </returns>
        /// <remarks>
        /// <para>
        /// An application can process <see cref="WM_TIMER"/> messages by including a <see cref="WM_TIMER"/> case statement in the window procedure
        /// or by specifying a <c>TimerProc</c> callback function when creating the timer.
        /// When you specify a <c>TimerProc</c> callback function,
        /// the default window procedure calls the callback function when it processes <see cref="WM_TIMER"/>.
        /// Therefore, you need to dispatch messages in the calling thread,
        /// even when you use <c>TimerProc</c> instead of processing <see cref="WM_TIMER"/>.
        /// </para>
        /// <para>
        /// The wParam parameter of the <see cref="WM_TIMER"/> message contains the value of the <paramref name="nIDEvent"/> parameter.
        /// </para>
        /// <para>
        /// The timer identifier, <paramref name="nIDEvent"/>, is specific to the associated window.
        /// Another window can have its own timer which has the same identifier as a timer owned by another window. The timers are distinct.
        /// </para>
        /// <para>
        /// <see cref="SetTimer"/> can reuse timer IDs in the case where <paramref name="hWnd"/> is <see cref="NULL"/>.
        /// </para>
        /// <para>
        /// When <paramref name="uToleranceDelay"/> is set to 0, the system default timer coalescing is used
        /// and <see cref="SetCoalescableTimer"/> behaves the same as <see cref="SetTimer"/>.
        /// </para>
        /// <para>
        /// Before using <see cref="SetCoalescableTimer"/> or other timer-related functions,
        /// it is recommended to set the <see cref="UOI_TIMERPROC_EXCEPTION_SUPPRESSION"/> flag to <see cref="FALSE"/>
        /// through the <see cref="SetUserObjectInformation"/> function,
        /// otherwise the application could behave unpredictably and could be vulnerable to security exploits.
        /// For more info, see <see cref="SetUserObjectInformation"/>.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.Windows8)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "SetCoalescableTimer", ExactSpelling = true, SetLastError = true)]
        public static extern UINT_PTR SetCoalescableTimer([In] HWND hWnd, [In] UINT_PTR nIDEvent, [In] UINT uElapse,
            [In] TIMERPROC lpTimerFunc, [In] ULONG uToleranceDelay);

        /// <summary>
        /// 
        /// </summary>
        /// <param name="dwLevel"></param>
        [WindowsVersionRequirement(WindowsVersion.WindowsNT40)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "SetDebugErrorLevel", ExactSpelling = true)]
        public static extern void SetDebugErrorLevel([In] DWORD dwLevel);

        /// <summary>
        /// <para>
        /// Sets the last-error code.
        /// </para>
        /// <para>
        /// Currently, this function is identical to the <see cref="SetLastError"/> function.
        /// The second parameter is ignored.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-setlasterrorex"/>
        /// </para>
        /// </summary>
        /// <param name="dwErrCode">
        /// The last-error code for the thread.
        /// </param>
        /// <param name="dwType">
        /// This parameter is ignored.
        /// </param>
        /// <remarks>
        /// <para>
        /// The last-error code is kept in thread local storage so that multiple threads do not overwrite each other's values.
        /// </para>
        /// <para>
        /// Most functions call <see cref="SetLastError"/> or <see cref="SetLastErrorEx"/> only when they fail.
        /// However, some system functions call <see cref="SetLastError"/> or <see cref="SetLastErrorEx"/> under conditions of success;
        /// those cases are noted in each function's documentation.
        /// </para>
        /// <para>
        /// Applications can optionally retrieve the value set by this function
        /// by using the <see cref="GetLastError"/> function immediately after a function fails.
        /// </para>
        /// <para>
        /// Error codes are 32-bit values (bit 31 is the most significant bit).
        /// Bit 29 is reserved for application-defined error codes; no system error code has this bit set.
        /// If you are defining an error code for your application,
        /// set this bit to indicate that the error code has been defined by the application
        /// and to ensure that your error code does not conflict with any system-defined error codes.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsNT40)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "SetLastErrorEx", ExactSpelling = true)]
        public static extern void SetLastErrorEx([In] DWORD dwErrCode, [In] DWORD dwType);

        /// <summary>
        /// <para>
        /// Sets the colors for the specified display elements.
        /// Display elements are the various parts of a window and the display that appear on the system display screen.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-setsyscolors"/>
        /// </para>
        /// </summary>
        /// <param name="cElements">
        /// The number of display elements in the <paramref name="lpaElements"/> array.
        /// </param>
        /// <param name="lpaElements">
        /// An array of integers that specify the display elements to be changed.
        /// For a list of display elements, see <see cref="GetSysColor"/>.
        /// </param>
        /// <param name="lpaRgbValues">
        /// <para>
        /// An array of <see cref="COLORREF"/> values that contain the new red, green, blue (RGB) color values
        /// for the display elements in the array pointed to by the <paramref name="lpaElements"/> parameter.
        /// </para>
        /// <para>
        /// To generate a <see cref="COLORREF"/>, use the <see cref="RGB"/> macro.
        /// </para>
        /// </param>
        /// <returns>
        /// <para>
        /// If the function succeeds, the return value is a nonzero value.
        /// </para>
        /// <para>
        /// If the function fails, the return value is zero.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </para>
        /// </returns>
        /// <remarks>
        /// <para>
        /// The <see cref="SetSysColors"/> function sends a <see cref="WM_SYSCOLORCHANGE"/> message
        /// to all windows to inform them of the change in color.
        /// It also directs the system to repaint the affected portions of all currently visible windows.
        /// </para>
        /// <para>
        /// It is best to respect the color settings specified by the user.
        /// If you are writing an application to enable the user to change the colors, then it is appropriate to use this function.
        /// However, this function affects only the current session.
        /// The new colors are not saved when the system terminates.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsNT40)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "SetSysColors", ExactSpelling = true, SetLastError = true)]
        public static extern BOOL SetSysColors([In] int cElements, [In] INT[] lpaElements, [In] COLORREF[] lpaRgbValues);

        /// <summary>
        /// <para>
        /// Creates a timer with the specified time-out value.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-settimer"/>
        /// </para>
        /// </summary>
        /// <param name="hWnd">
        /// A handle to the window to be associated with the timer.
        /// This window must be owned by the calling thread.
        /// If a <see cref="NULL"/> value for <paramref name="hWnd"/> is passed in along with an <paramref name="nIDEvent"/> of an existing timer,
        /// that timer will be replaced in the same way that an existing non-<see cref="NULL"/> <paramref name="hWnd"/> timer will be.
        /// </param>
        /// <param name="nIDEvent">
        /// A nonzero timer identifier.
        /// If the <paramref name="hWnd"/> parameter is <see cref="NULL"/>, and the <paramref name="nIDEvent"/> does not match an existing timer
        /// then it is ignored and a new timer ID is generated.
        /// If the <paramref name="hWnd"/> parameter is not <see cref="NULL"/> and the window specified
        /// by <paramref name="hWnd"/> already has a timer with the value <paramref name="nIDEvent"/>, then the existing timer is replaced by the new timer.
        /// When <see cref="SetTimer"/> replaces a timer, the timer is reset.
        /// Therefore, a message will be sent after the current time-out value elapses, but the previously set time-out value is ignored.
        /// If the call is not intended to replace an existing timer,
        /// <paramref name="nIDEvent"/> should be 0 if the <paramref name="hWnd"/> is <see cref="NULL"/>.
        /// </param>
        /// <param name="uElapse">
        /// <para>
        /// The time-out value, in milliseconds.
        /// </para>
        /// <para>
        /// If <paramref name="uElapse"/> is less than <see cref="USER_TIMER_MINIMUM"/>, the timeout is set to <see cref="USER_TIMER_MINIMUM"/>.
        /// If <paramref name="uElapse"/> is greater than <see cref="USER_TIMER_MAXIMUM"/>, the timeout is set to <see cref="USER_TIMER_MAXIMUM"/>.
        /// </para>
        /// </param>
        /// <param name="lpTimerFunc">
        /// A pointer to the function to be notified when the time-out value elapses.
        /// For more information about the function, see <see cref="TIMERPROC"/>.
        /// If <paramref name="lpTimerFunc"/> is <see cref="NULL"/>, the system posts a <see cref="WM_TIMER"/> message to the application queue.
        /// The <see cref="MSG.hwnd"/> member of the message's <see cref="MSG"/> structure contains the value of the <paramref name="hWnd"/> parameter.
        /// </param>
        /// <returns>
        /// <para>
        /// If the function succeeds and the <paramref name="hWnd"/> parameter is <see cref="NULL"/>,
        /// the return value is an integer identifying the new timer.
        /// An application can pass this value to the <see cref="KillTimer"/> function to destroy the timer.
        /// </para>
        /// <para>
        /// If the function succeeds and the <paramref name="hWnd"/> parameter is not <see cref="NULL"/>,
        /// then the return value is a nonzero integer.
        /// An application can pass the value of the <paramref name="nIDEvent"/> parameter to the <see cref="KillTimer"/> function to destroy the timer.
        /// </para>
        /// <para>
        /// If the function fails to create a timer, the return value is zero.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </para>
        /// </returns>
        /// <remarks>
        /// <para>
        /// An application can process <see cref="WM_TIMER"/> messages by including a <see cref="WM_TIMER"/> case statement
        /// in the window procedure or by specifying a <c>TimerProc</c> callback function when creating the timer.
        /// When you specify a <c>TimerProc</c> callback function, the <see cref="DispatchMessage"/> calls the callback function
        /// instead of calling the window procedure when it processes <see cref="WM_TIMER"/> with a non-<see cref="NULL"/> <c>lParam</c>.
        /// Therefore, you need to dispatch messages in the calling thread, even when you use <c>TimerProc</c> instead of processing <see cref="WM_TIMER"/>.
        /// </para>
        /// <para>
        /// The wParam parameter of the <see cref="WM_TIMER"/> message contains the value of the <paramref name="nIDEvent"/> parameter.
        /// </para>
        /// <para>
        /// The timer identifier, <paramref name="nIDEvent"/>, is specific to the associated window.
        /// Another window can have its own timer which has the same identifier as a timer owned by another window.
        /// The timers are distinct.
        /// </para>
        /// <para>
        /// <see cref="SetTimer"/> can reuse timer IDs in the case where <paramref name="hWnd"/> is <see cref="NULL"/>.
        /// </para>
        /// <para>
        /// Before using <see cref="SetTimer"/> or other timer-related functions,
        /// it is recommended to set the <see cref="UOI_TIMERPROC_EXCEPTION_SUPPRESSION"/> flag to <see cref="FALSE"/>
        /// through the <see cref="SetUserObjectInformation"/> function,
        /// otherwise the application could behave unpredictably and could be vulnerable to security exploits.
        /// For more info, see <see cref="SetUserObjectInformation"/>.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsNT40)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "SetTimer", ExactSpelling = true, SetLastError = true)]
        public static extern UINT_PTR SetTimer([In] HWND hWnd, [In] UINT_PTR nIDEvent, [In] UINT uElapse, [In] TIMERPROC lpTimerFunc);

        /// <summary>
        /// <para>
        /// Sets information about the specified window station or desktop object.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-setuserobjectinformationw"/>
        /// </para>
        /// </summary>
        /// <param name="hObj">
        /// A handle to the window station, desktop object or a current process pseudo handle.
        /// This handle can be returned by the <see cref="CreateWindowStation"/>, <see cref="OpenWindowStation"/>,
        /// <see cref="CreateDesktop"/>, <see cref="OpenDesktop"/> or <see cref="GetCurrentProcess"/> function.
        /// </param>
        /// <param name="nIndex">
        /// <para>
        /// The object information to be set.
        /// This parameter can be the following value.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Value
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="UOI_FLAGS"/>
        /// </para>
        /// <para>
        /// 1
        /// </para>
        /// </term>
        /// <term>
        /// Sets the object's handle flags.
        /// The <paramref name="pvInfo"/> parameter must point to a <see cref="USEROBJECTFLAGS"/> structure.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="UOI_TIMERPROC_EXCEPTION_SUPPRESSION"/>
        /// </para>
        /// <para>
        /// 7
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the exception handling behavior when calling <c>TimerProc</c>.
        /// <paramref name="hObj"/> must be the process handle returned by the <see cref="GetCurrentProcess"/> function.
        /// </para>
        /// <para>
        /// The <paramref name="pvInfo"/> parameter must point to a <see cref="BOOL"/>.
        /// If <see cref="TRUE"/>, Windows will enclose its calls to <c>TimerProc</c>
        /// with an exception handler that consumes and discards all exceptions.
        /// This has been the default behavior since Windows 2000, although that may change in future versions of Windows.
        /// </para>
        /// <para>
        /// If <paramref name="pvInfo"/> points to <see cref="FALSE"/>,
        /// Windows will not enclose its calls to <c>TimerProc</c> with an exception handler.
        /// A setting of <see cref="FALSE"/> is recommended.
        /// Otherwise, the application could behave unpredictably, and could be more vulnerable to security exploits.
        /// </para>
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// </param>
        /// <param name="pvInfo">
        /// A pointer to a buffer containing the object information, or a <see cref="BOOL"/>.
        /// </param>
        /// <param name="nLength">
        /// The size of the information contained in the buffer pointed to by <paramref name="pvInfo"/>, in bytes.
        /// </param>
        /// <returns>
        /// <para>
        /// If the function succeeds, the return value is nonzero.
        /// </para>
        /// <para>
        /// If the function fails the return value is zero.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </para>
        /// </returns>
        [WindowsVersionRequirement(WindowsVersion.WindowsNT40)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "SetUserObjectInformationW", ExactSpelling = true, SetLastError = true)]
        public static extern BOOL SetUserObjectInformation([In] HANDLE hObj, [In] int nIndex, [In] PVOID pvInfo, [In] DWORD nLength);

        /// <summary>
        /// <para>
        /// The <see cref="SetUserObjectSecurity"/> function sets the security of a user object.
        /// This can be, for example, a window or a DDE conversation.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-setuserobjectsecurity"/>
        /// </para>
        /// </summary>
        /// <param name="hObj">
        /// A handle to a user object for which security information is set.
        /// </param>
        /// <param name="pSIRequested">
        /// <para>
        /// A pointer to a value that indicates the components of the security descriptor to set. This parameter can be a combination of the following values.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Value
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <see cref="DACL_SECURITY_INFORMATION"/>
        /// </term>
        /// <term>
        /// Sets the discretionary access control list (DACL) of the object.
        /// The handle specified by <paramref name="hObj"/> must have <see cref="WRITE_DAC"/> access,
        /// or the calling process must be the owner of the object.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <see cref="GROUP_SECURITY_INFORMATION"/>
        /// </term>
        /// <term>
        /// Sets the primary group security identifier (SID) of the object.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <see cref="OWNER_SECURITY_INFORMATION"/>
        /// </term>
        /// <term>
        /// Sets the SID of the owner of the object.
        /// The handle specified by <paramref name="hObj"/> must have <see cref="WRITE_OWNER"/> access,
        /// or the calling process must be the owner of the object or have the <see cref="SE_TAKE_OWNERSHIP_NAME"/> privilege enabled.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <see cref="SACL_SECURITY_INFORMATION"/>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the system access control list (SACL) of the object.
        /// The handle specified by <paramref name="hObj"/> must have <see cref="ACCESS_SYSTEM_SECURITY"/> access.
        /// </para>
        /// <para>
        /// To obtain <see cref="ACCESS_SYSTEM_SECURITY"/> access
        /// </para>
        /// <para>
        /// <list type="number">
        /// <item>
        /// <description>
        /// Enable the <see cref="SE_SECURITY_NAME"/> privilege in the current access token of the caller.
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// Open the handle for <see cref="ACCESS_SYSTEM_SECURITY"/> access.
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// Disable the privilege.
        /// </description>
        /// </item>
        /// </list>
        /// </para>
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// </param>
        /// <param name="pSID">
        /// <para>
        /// A pointer to a <see cref="SECURITY_DESCRIPTOR"/> structure that contains the new security information.
        /// </para>
        /// <para>
        /// This buffer must be aligned on a 4-byte boundary.
        /// </para>
        /// </param>
        /// <returns>
        /// <para>
        /// If the function succeeds, the function returns nonzero.
        /// </para>
        /// <para>
        /// If the function fails, it returns zero.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </para>
        /// </returns>
        /// <remarks>
        /// The <see cref="SetUserObjectSecurity"/> function applies changes specified in a security descriptor
        /// to the security descriptor assigned to a user object.
        /// The security descriptor of the object must be in self-relative form.
        /// If necessary, this function allocates additional memory to increase the size of the security descriptor.
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsNT40)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "SetUserObjectSecurity", ExactSpelling = true, SetLastError = true)]
        public static extern BOOL SetUserObjectSecurity([In] HANDLE hObj, [In] in SECURITY_INFORMATION pSIRequested, [In] PSECURITY_DESCRIPTOR pSID);

        /// <summary>
        /// <para>
        /// Sets an event hook function for a range of events.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-setwineventhook"/>
        /// </para>
        /// </summary>
        /// <param name="eventMin">
        /// Specifies the event constant for the lowest event value in the range of events that are handled by the hook function.
        /// This parameter can be set to <see cref="EVENT_MIN"/> to indicate the lowest possible event value.
        /// </param>
        /// <param name="eventMax">
        /// Specifies the event constant for the highest event value in the range of events that are handled by the hook function.
        /// This parameter can be set to <see cref="EVENT_MAX"/> to indicate the highest possible event value.
        /// </param>
        /// <param name="hmodWinEventProc">
        /// Handle to the DLL that contains the hook function at <paramref name="pfnWinEventProc"/>,
        /// if the <see cref="WINEVENT_INCONTEXT"/> flag is specified in the <paramref name="dwFlags"/> parameter.
        /// If the hook function is not located in a DLL, or if the <see cref="WINEVENT_OUTOFCONTEXT"/> flag is specified,
        /// this parameter is <see cref="NULL"/>.
        /// </param>
        /// <param name="pfnWinEventProc">
        /// Pointer to the event hook function.
        /// For more information about this function, see WinEventProc.
        /// </param>
        /// <param name="idProcess">
        /// Specifies the ID of the process from which the hook function receives events.
        /// Specify zero (0) to receive events from all processes on the current desktop.
        /// </param>
        /// <param name="idThread">
        /// Specifies the ID of the thread from which the hook function receives events.
        /// If this parameter is zero, the hook function is associated with all existing threads on the current desktop.
        /// </param>
        /// <param name="dwFlags">
        /// <para>
        /// Flag values that specify the location of the hook function and of the events to be skipped.
        /// The following flags are valid:
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Value
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <see cref="WINEVENT_INCONTEXT"/>
        /// </term>
        /// <term>
        /// The DLL that contains the callback function is mapped into the address space of the process that generates the event.
        /// With this flag, the system sends event notifications to the callback function as they occur.
        /// The hook function must be in a DLL when this flag is specified.
        /// This flag has no effect when both the calling process and the generating process are not 32-bit or 64-bit processes,
        /// or when the generating process is a console application.
        /// For more information, see In-Context Hook Functions.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <see cref="WINEVENT_OUTOFCONTEXT"/>
        /// </term>
        /// <term>
        /// The callback function is not mapped into the address space of the process that generates the event.
        /// Because the hook function is called across process boundaries, the system must queue events.
        /// Although this method is asynchronous, events are guaranteed to be in sequential order.
        /// For more information, see Out-of-Context Hook Functions.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <see cref="WINEVENT_SKIPOWNPROCESS"/>
        /// </term>
        /// <term>
        /// Prevents this instance of the hook from receiving the events that are generated by threads in this process.
        /// This flag does not prevent threads from generating events.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <see cref="WINEVENT_SKIPOWNTHREAD"/>
        /// </term>
        /// <term>
        /// Prevents this instance of the hook from receiving the events that are generated by the thread that is registering this hook.
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        ///  
        /// </para>
        /// <para>
        /// The following flag combinations are valid:
        /// </para>
        /// <para>
        /// <list type="bullet">
        /// <item>
        /// <description>
        /// <c>WINEVENT_INCONTEXT | WINEVENT_SKIPOWNPROCESS</c>
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// <c>WINEVENT_INCONTEXT | WINEVENT_SKIPOWNTHREAD</c>
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// <c>WINEVENT_OUTOFCONTEXT | WINEVENT_SKIPOWNPROCESS</c>
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// <c>WINEVENT_OUTOFCONTEXT | WINEVENT_SKIPOWNTHREAD</c>
        /// </description>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        /// Additionally, client applications can specify <see cref="WINEVENT_INCONTEXT"/>, or <see cref="WINEVENT_OUTOFCONTEXT"/> alone.
        /// </para>
        /// <para>
        /// See Remarks section for information on Windows Store app development.
        /// </para>
        /// </param>
        /// <returns>
        /// <para>
        /// If successful, returns an <see cref="HWINEVENTHOOK"/> value that identifies this event hook instance.
        /// Applications save this return value to use it with the <see cref="UnhookWinEvent"/> function.
        /// </para>
        /// <para>
        /// If unsuccessful, returns zero.
        /// </para>
        /// </returns>
        /// <remarks>
        /// <para>
        /// This function allows clients to specify which processes and threads they are interested in.
        /// </para>
        /// <para>
        /// If the <paramref name="idProcess"/> parameter is nonzero and <paramref name="idThread"/> is zero,
        /// the hook function receives the specified events from all threads in that process.
        /// If the <paramref name="idProcess"/> parameter is zero and <paramref name="idThread"/> is nonzero,
        /// the hook function receives the specified events only from the thread specified by <paramref name="idThread"/>.
        /// If both are zero, the hook function receives the specified events from all threads and processes.
        /// </para>
        /// <para>
        /// Clients can call <see cref="SetWinEventHook"/> multiple times if they want to register additional hook functions or listen for additional events.
        /// </para>
        /// <para>
        /// The client thread that calls <see cref="SetWinEventHook"/> must have a message loop in order to receive events.
        /// </para>
        /// <para>
        /// When you use <see cref="SetWinEventHook"/> to set a callback in managed code,
        /// you should use the <see cref="GCHandle"/> structure to avoid exceptions.
        /// This tells the garbage collector not to move the callback.
        /// </para>
        /// <para>
        /// For out-of-context events, the event is delivered on the same thread that called <see cref="SetWinEventHook"/>.
        /// In some situations, even if you request <see cref="WINEVENT_INCONTEXT"/> events, the events will still be delivered out-of-context.
        /// These scenarios include events from console windows and events from processes that have a different bit-depth (64 bit versus 32 bits) than the caller.
        /// </para>
        /// <para>
        /// While a hook function processes an event, additional events may be triggered,
        /// which may cause the hook function to reenter before the processing for the original event is finished.
        /// The problem with reentrancy in hook functions is that events are completed out of sequence unless the hook function handles this situation.
        /// For more information, see Guarding Against Reentrancy.
        /// </para>
        /// <para>
        /// Windows Store app development If <paramref name="dwFlags"/> is <see cref="WINEVENT_INCONTEXT"/>
        /// AND (<paramref name="idProcess"/> = 0 | <paramref name="idThread"/> = 0),
        /// then window hook DLLs are not loaded in-process for the Windows Store app processes
        /// and the Windows Runtime broker process unless they are installed by UIAccess processes (accessibility tools).
        /// The notification is delivered on the installer's thread.
        /// </para>
        /// <para>
        /// This behavior is similar to what happens when there is an architecture mismatch between the hook DLL and the target application process,
        /// for example, when the hook DLL is 32-bit and the application process 64-bit.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.Windows2000)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "SetWinEventHook", ExactSpelling = true)]
        public static extern HWINEVENTHOOK SetWinEventHook([In] EventConstants eventMin, [In] EventConstants eventMax, [In] HMODULE hmodWinEventProc,
            [In] WINEVENTPROC pfnWinEventProc, [In] DWORD idProcess, [In] DWORD idThread, [In] SetWinEventHookFlags dwFlags);

        /// <summary>
        /// <para>
        /// Indicates that the system cannot be shut down and sets a reason string to be displayed to the user if system shutdown is initiated.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-shutdownblockreasoncreate"/>
        /// </para>
        /// </summary>
        /// <param name="hWnd">
        /// A handle to the main window of the application.
        /// </param>
        /// <param name="pwszReason">
        /// The reason the application must block system shutdown.
        /// This string will be truncated for display purposes after <see cref="MAX_STR_BLOCKREASON"/> characters.
        /// </param>
        /// <returns>
        /// <para>
        /// If the call succeeds, the return value is nonzero.
        /// </para>
        /// <para>
        /// If the call fails, the return value is zero.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </para>
        /// </returns>
        /// <remarks>
        /// <para>
        /// This function can only be called from the thread that created the window specified by the <paramref name="hWnd"/> parameter.
        /// Otherwise, the function fails and the last error code is <see cref="ERROR_ACCESS_DENIED"/>.
        /// </para>
        /// <para>
        /// Applications should call this function as they begin an operation that cannot be interrupted, such as burning a CD or DVD.
        /// When the operation has completed, call the <see cref="ShutdownBlockReasonDestroy"/> function to indicate that the system can be shut down.
        /// </para>
        /// <para>
        /// Because users are typically in a hurry when shutting down the system,
        /// they may spend only a few seconds looking at the shutdown reasons that are displayed by the system.
        /// Therefore, it is important that your reason strings are short and clear.
        /// For example "A CD burn is in progress." is better than
        /// "This application is blocking system shutdown because a CD burn is in progress. Do not shut down."
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsVista)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "ShutdownBlockReasonCreate", ExactSpelling = true, SetLastError = true)]
        public static extern BOOL ShutdownBlockReasonCreate([In] HWND hWnd, [In] LPCWSTR pwszReason);

        /// <summary>
        /// <para>
        /// Indicates that the system can be shut down and frees the reason string.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-shutdownblockreasondestroy"/>
        /// </para>
        /// </summary>
        /// <param name="hWnd">
        /// A handle to the main window of the application.
        /// </param>
        /// <returns>
        /// <para>
        /// If the call succeeds, the return value is nonzero.
        /// </para>
        /// <para>
        /// If the call fails, the return value is zero.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </para>
        /// </returns>
        /// <remarks>
        /// <para>
        /// This function can only be called from the thread that created the window
        /// specified by the <paramref name="hWnd"/> parameter.
        /// Otherwise, the function fails and the last error code is <see cref="ERROR_ACCESS_DENIED"/>.
        /// </para>
        /// <para>
        /// If system shutdown has been previously blocked by the <see cref="ShutdownBlockReasonCreate"/> function,
        /// this function frees the reason string. Otherwise, this function is a no-op.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsVista)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "ShutdownBlockReasonDestroy", ExactSpelling = true, SetLastError = true)]
        public static extern BOOL ShutdownBlockReasonDestroy([In] HWND hWnd);

        /// <summary>
        /// <para>
        /// Retrieves the reason string set by the <see cref="ShutdownBlockReasonCreate"/> function.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-shutdownblockreasonquery"/>
        /// </para>
        /// </summary>
        /// <param name="hWnd">
        /// A handle to the main window of the application.
        /// </param>
        /// <param name="pwszBuff">
        /// A pointer to a buffer that receives the reason string.
        /// If this parameter is <see cref="NULL"/>, the function retrieves the number of characters in the reason string.
        /// </param>
        /// <param name="pcchBuff">
        /// A pointer to a variable that specifies the size of the <paramref name="pwszBuff"/> buffer, in characters.
        /// If the function succeeds, this variable receives the number of characters copied into the buffer,
        /// including the null-terminating character.
        /// If the buffer is too small, the variable receives the required buffer size, in characters,
        /// not including the null-terminating character.
        /// </param>
        /// <returns>
        /// <para>
        /// If the call succeeds, the return value is nonzero.
        /// </para>
        /// <para>
        /// If the call fails, the return value is zero.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </para>
        /// </returns>
        /// <remarks>
        /// This function can only be called from the thread that created the window specified by the <paramref name="hWnd"/> parameter.
        /// Otherwise, the function fails and the last error code is <see cref="ERROR_ACCESS_DENIED"/>.
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsVista)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "ShutdownBlockReasonQuery", ExactSpelling = true, SetLastError = true)]
        public static extern BOOL ShutdownBlockReasonQuery([In] HWND hWnd, [In] LPWSTR pwszBuff, [Out] DWORD pcchBuff);

        /// <summary>
        /// <para>
        /// Triggers a visual signal to indicate that a sound is playing.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-soundsentry"/>
        /// </para>
        /// </summary>
        /// <returns>
        /// <para>
        /// This function returns one of the following values.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Return code
        /// </term>
        /// <term>
        /// Description
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <see cref="TRUE"/>
        /// </term>
        /// <term>
        /// The visual signal was or will be displayed correctly.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <see cref="FALSE"/>
        /// </term>
        /// <term>
        /// An error prevented the signal from being displayed.
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// </returns>
        /// <remarks>
        /// Set the notification behavior by calling <see cref="SystemParametersInfo"/> with the <see cref="SPI_SETSOUNDSENTRY"/> value.
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsVista)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "SoundSentry", ExactSpelling = true)]
        public static extern BOOL SoundSentry();

        /// <summary>
        /// <para>
        /// Important
        /// </para>
        /// <para>
        /// Some information relates to a prerelease product which may be substantially modified before it's commercially released.
        /// Microsoft makes no warranties, express or implied, with respect to the information provided here.
        /// </para>
        /// <para>
        /// Retrieves or sets the value of one of the system-wide parameters.
        /// This function can also update the user profile while setting a parameter.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-systemparametersinfow"/>
        /// </para>
        /// </summary>
        /// <param name="uiAction">
        /// <para>
        /// The system-wide parameter to be retrieved or set. The possible values are organized in the following tables of related parameters:
        /// </para>
        /// <para>
        /// <list type="bullet">
        /// <item>
        /// <description>
        /// Accessibility parameters
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// Desktop parameters
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// Icon parameters
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// Input parameters
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// Menu parameters
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// Power parameters
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// Screen saver parameters
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// Time-out parameters
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// UI effect parameters
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// Window parameters
        /// </description>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        /// The following are the accessibility parameters.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Accessibility parameter
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETACCESSTIMEOUT"/>
        /// </para>
        /// <para>
        /// 0x003C
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves information about the time-out period associated with the accessibility features.
        /// The <paramref name="pvParam"/> parameter must point to an <see cref="ACCESSTIMEOUT"/> structure that receives the information.
        /// Set the <see cref="ACCESSTIMEOUT.cbSize"/> member of this structure
        /// and the <paramref name="uiParam"/> parameter to <c>sizeof(ACCESSTIMEOUT)</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETAUDIODESCRIPTION"/>
        /// </para>
        /// <para>
        /// 0x0074
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether audio descriptions are enabled or disabled.
        /// The <paramref name="pvParam"/> parameter is a pointer to an <see cref="AUDIODESCRIPTION"/> structure.
        /// Set the <see cref="AUDIODESCRIPTION.cbSize"/> member of this structure
        /// and the <paramref name="uiParam"/> parameter to <c>sizeof(AUDIODESCRIPTION)</c>.
        /// </para>
        /// <para>
        /// While it is possible for users who have visual impairments to hear the audio in video content,
        /// there is a lot of action in video that does not have corresponding audio.
        /// Specific audio description of what is happening in a video helps these users understand the content better.
        /// This flag enables you to determine whether audio descriptions have been enabled and in which language.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETCLIENTAREAANIMATION"/>
        /// </para>
        /// <para>
        /// 0x1042
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether animations are enabled or disabled.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable 
        /// that receives <see cref="TRUE"/> if animations are enabled, or <see cref="FALSE"/> otherwise.
        /// </para>
        /// <para>
        /// Display features such as flashing, blinking, flickering, and moving content can cause seizures in users with photo-sensitive epilepsy.
        /// This flag enables you to determine whether such animations have been disabled in the client area.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETDISABLEOVERLAPPEDCONTENT"/>
        /// </para>
        /// <para>
        /// 0x1040
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether overlapped content is enabled or disabled.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if enabled, or <see cref="FALSE"/> otherwise.
        /// </para>
        /// <para>
        /// Display features such as background images, textured backgrounds, water marks on documents, alpha blending,
        /// and transparency can reduce the contrast between the foreground and background,
        /// making it harder for users with low vision to see objects on the screen.
        /// This flag enables you to determine whether such overlapped content has been disabled.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETFILTERKEYS"/>
        /// </para>
        /// <para>
        /// 0x0032
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves information about the FilterKeys accessibility feature.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="FILTERKEYS"/> structure that receives the information.
        /// Set the <see cref="FILTERKEYS.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(FILTERKEYS)</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETFOCUSBORDERHEIGHT"/>
        /// </para>
        /// <para>
        /// 0x2010
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the height, in pixels, of the top and bottom edges of the focus rectangle drawn with <see cref="DrawFocusRect"/>.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="UINT"/> value.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETFOCUSBORDERWIDTH"/>
        /// </para>
        /// <para>
        /// 0x200E
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the width, in pixels, of the left and right edges of the focus rectangle drawn with <see cref="DrawFocusRect"/>.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="UINT"/>.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETHIGHCONTRAST"/>
        /// </para>
        /// <para>
        /// 0x0042
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves information about the HighContrast accessibility feature.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="HIGHCONTRAST"/> structure that receives the information.
        /// Set the <see cref="HIGHCONTRAST.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(HIGHCONTRAST)</c>.
        /// </para>
        /// <para>
        /// For a general discussion, see Remarks.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETLOGICALDPIOVERRIDE"/>
        /// </para>
        /// <para>
        /// 0x009E
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves a value that determines whether Windows 8 is displaying apps
        /// using the default scaling plateau for the hardware or going to the next higher plateau.
        /// This value is based on the current "Make everything on your screen bigger" setting,
        /// found in the Ease of Access section of PC settings: 1 is on, 0 is off.
        /// </para>
        /// <para>
        /// Apps can provide text and image resources for each of several scaling plateaus: 100%, 140%, and 180%.
        /// Providing separate resources optimized for a particular scale avoids distortion due to resizing.
        /// Windows 8 determines the appropriate scaling plateau based on a number of factors, including screen size and pixel density.
        /// When "Make everything on your screen bigger" is selected (<see cref="SPI_GETLOGICALDPIOVERRIDE"/> returns a value of 1),
        /// Windows uses resources from the next higher plateau.
        /// For example, in the case of hardware that Windows determines should use a scale of <see cref="SCALE_100_PERCENT"/>,
        /// this override causes Windows to use the <see cref="SCALE_140_PERCENT"/> scale value, assuming that it does not violate other constraints.
        /// </para>
        /// <para>
        /// Note
        /// </para>
        /// <para>
        /// You should not use this value. It might be altered or unavailable in subsequent versions of Windows.
        /// Instead, use the <see cref="GetScaleFactorForDevice"/> function
        /// or the <c>DisplayProperties</c> class to retrieve the preferred scaling factor.
        /// Desktop applications should use desktop logical DPI rather than scale factor.
        /// Desktop logical DPI can be retrieved through the <see cref="GetDeviceCaps"/> function. 
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMESSAGEDURATION"/>
        /// </para>
        /// <para>
        /// 0x2016
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the time that notification pop-ups should be displayed, in seconds.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="ULONG"/> that receives the message duration.
        /// </para>
        /// <para>
        /// Users with visual impairments or cognitive conditions such as ADHD and dyslexia might need a longer time to read the text in notification messages.
        /// This flag enables you to retrieve the message duration.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMOUSECLICKLOCK"/>
        /// </para>
        /// <para>
        /// 0x101E
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the state of the Mouse ClickLock feature.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if enabled, or <see cref="FALSE"/> otherwise.
        /// For more information, see Mouse Input Overview.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMOUSECLICKLOCKTIME"/>
        /// </para>
        /// <para>
        /// 0x2008
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the time delay before the primary mouse button is locked.
        /// The <paramref name="pvParam"/> parameter must point to <see cref="DWORD"/> that receives the time delay, in milliseconds.
        /// This is only enabled if <see cref="SPI_SETMOUSECLICKLOCK"/> is set to <see cref="TRUE"/>.
        /// For more information, see Mouse Input Overview.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMOUSEKEYS"/>
        /// </para>
        /// <para>
        /// 0x0036
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves information about the MouseKeys accessibility feature.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="MOUSEKEYS"/> structure that receives the information.
        /// Set the <see cref="MOUSEKEYS.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(MOUSEKEYS)</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMOUSESONAR"/>
        /// </para>
        /// <para>
        /// 0x101C
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the state of the Mouse Sonar feature.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if enabled or <see cref="FALSE"/> otherwise.
        /// For more information, see Mouse Input Overview.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMOUSEVANISH"/>
        /// </para>
        /// <para>
        /// 0x1020
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the state of the Mouse Vanish feature.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if enabled or <see cref="FALSE"/> otherwise.
        /// For more information, see Mouse Input Overview.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETSCREENREADER"/>
        /// </para>
        /// <para>
        /// 0x0046
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether a screen reviewer utility is running.
        /// A screen reviewer utility directs textual information to an output device, such as a speech synthesizer or Braille display.
        /// When this flag is set, an application should provide textual information in situations
        /// where it would otherwise present the information graphically.
        /// </para>
        /// <para>
        /// The <paramref name="pvParam"/> parameter is a pointer to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if a screen reviewer utility is running, or <see cref="FALSE"/> otherwise.
        /// </para>
        /// <para>
        /// Note
        /// </para>
        /// <para>
        /// Narrator, the screen reader that is included with Windows,
        /// does not set the <see cref="SPI_SETSCREENREADER"/> or <see cref="SPI_GETSCREENREADER"/> flags. 
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETSERIALKEYS"/>
        /// </para>
        /// <para>
        /// 0x003E
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// This parameter is not supported.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000: The user should control this setting through the Control Panel.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETSHOWSOUNDS"/>
        /// </para>
        /// <para>
        /// 0x0038
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether the Show Sounds accessibility flag is on or off.
        /// If it is on, the user requires an application to present information visually in situations
        /// where it would otherwise present the information only in audible form.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if the feature is on, or <see cref="FALSE"/> if it is off.
        /// </para>
        /// <para>
        /// Using this value is equivalent to calling <see cref="GetSystemMetrics"/> with <see cref="SM_SHOWSOUNDS"/>.
        /// That is the recommended call.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETSOUNDSENTRY"/>
        /// </para>
        /// <para>
        /// 0x0040
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves information about the SoundSentry accessibility feature.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="SOUNDSENTRY"/> structure that receives the information.
        /// Set the <see cref="SOUNDSENTRY.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(SOUNDSENTRY)</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETSTICKYKEYS"/>
        /// </para>
        /// <para>
        /// 0x003A
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves information about the StickyKeys accessibility feature.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="STICKYKEYS"/> structure that receives the information.
        /// Set the <see cref="STICKYKEYS.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(STICKYKEYS)</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETTOGGLEKEYS"/>
        /// </para>
        /// <para>
        /// 0x0034
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves information about the ToggleKeys accessibility feature.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="TOGGLEKEYS"/> structure that receives the information.
        /// Set the <see cref="TOGGLEKEYS.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(TOGGLEKEYS)</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETACCESSTIMEOUT"/>
        /// </para>
        /// <para>
        /// 0x003D
        /// </para>
        /// </term>
        /// <term>
        /// Sets the time-out period associated with the accessibility features.
        /// The <paramref name="pvParam"/> parameter must point to an <see cref="ACCESSTIMEOUT"/> structure that contains the new parameters.
        /// Set the <see cref="ACCESSTIMEOUT.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(ACCESSTIMEOUT)</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETAUDIODESCRIPTION"/>
        /// </para>
        /// <para>
        /// 0x0075
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Turns the audio descriptions feature on or off.
        /// The <paramref name="pvParam"/> parameter is a pointer to an <see cref="AUDIODESCRIPTION"/> structure.
        /// </para>
        /// <para>
        /// While it is possible for users who are visually impaired to hear the audio in video content,
        /// there is a lot of action in video that does not have corresponding audio.
        /// Specific audio description of what is happening in a video helps these users understand the content better.
        /// This flag enables you to enable or disable audio descriptions in the languages they are provided in.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETCLIENTAREAANIMATION"/>
        /// </para>
        /// <para>
        /// 0x1043
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Turns client area animations on or off.
        /// The <paramref name="pvParam"/> parameter is a <see cref="BOOL"/> variable.
        /// Set <paramref name="pvParam"/> to <see cref="TRUE"/> to enable animations and other transient effects
        /// in the client area, or <see cref="FALSE"/> to disable them.
        /// </para>
        /// <para>
        /// Display features such as flashing, blinking, flickering, and moving content can cause seizures in users with photo-sensitive epilepsy.
        /// This flag enables you to enable or disable all such animations.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETDISABLEOVERLAPPEDCONTENT"/>
        /// </para>
        /// <para>
        /// 0x1041
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Turns overlapped content (such as background images and watermarks) on or off.
        /// The <paramref name="pvParam"/> parameter is a <see cref="BOOL"/> variable.
        /// Set <paramref name="pvParam"/> to <see cref="TRUE"/> to disable overlapped content, or <see cref="FALSE"/> to enable overlapped content.
        /// </para>
        /// <para>
        /// Display features such as background images, textured backgrounds, water marks on documents, alpha blending,
        /// and transparency can reduce the contrast between the foreground and background,
        /// making it harder for users with low vision to see objects on the screen.
        /// This flag enables you to enable or disable all such overlapped content.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETFILTERKEYS"/>
        /// </para>
        /// <para>
        /// 0x0033
        /// </para>
        /// </term>
        /// <term>
        /// Sets the parameters of the FilterKeys accessibility feature.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="FILTERKEYS"/> structure that contains the new parameters.
        /// Set the <see cref="FILTERKEYS.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(FILTERKEYS)</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETFOCUSBORDERHEIGHT"/>
        /// </para>
        /// <para>
        /// 0x2011
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the height of the top and bottom edges of the focus rectangle drawn with <see cref="DrawFocusRect"/>
        /// to the value of the <paramref name="pvParam"/> parameter.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETFOCUSBORDERWIDTH"/>
        /// </para>
        /// <para>
        /// 0x200F
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the height of the left and right edges of the focus rectangle drawn with <see cref="DrawFocusRect"/>
        /// to the value of the <paramref name="pvParam"/> parameter.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETHIGHCONTRAST"/>
        /// </para>
        /// <para>
        /// 0x0043
        /// </para>
        /// </term>
        /// <term>
        /// Sets the parameters of the HighContrast accessibility feature.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="HIGHCONTRAST"/> structure that contains the new parameters.
        /// Set the <see cref="HIGHCONTRAST.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(HIGHCONTRAST)</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETLOGICALDPIOVERRIDE"/>
        /// </para>
        /// <para>
        /// 0x009F
        /// </para>
        /// </term>
        /// <term>
        /// Do not use.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMESSAGEDURATION"/>
        /// </para>
        /// <para>
        /// 0x2017
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the time that notification pop-ups should be displayed, in seconds.
        /// The <paramref name="pvParam"/> parameter specifies the message duration.
        /// </para>
        /// <para>
        /// Users with visual impairments or cognitive conditions such as ADHD and dyslexia might need a longer time to read the text in notification messages.
        /// This flag enables you to set the message duration.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMOUSECLICKLOCK"/>
        /// </para>
        /// <para>
        /// 0x101F
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Turns the Mouse ClickLock accessibility feature on or off.
        /// This feature temporarily locks down the primary mouse button
        /// when that button is clicked and held down for the time specified by <see cref="SPI_SETMOUSECLICKLOCKTIME"/>.
        /// The <paramref name="pvParam"/> parameter specifies <see cref="TRUE"/> for on, or <see cref="FALSE"/> for off.
        /// The default is off.
        /// For more information, see Remarks and AboutMouse Input.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMOUSECLICKLOCKTIME"/>
        /// </para>
        /// <para>
        /// 0x2009
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Adjusts the time delay before the primary mouse button is locked.
        /// The <paramref name="uiParam"/> parameter should be set to 0.
        /// The <paramref name="pvParam"/> parameter points to a <see cref="DWORD"/> that specifies the time delay in milliseconds.
        /// For example, specify 1000 for a 1 second delay.
        /// The default is 1200.
        /// For more information, see Mouse Input Overview.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMOUSEKEYS"/>
        /// </para>
        /// <para>
        /// 0x0037
        /// </para>
        /// </term>
        /// <term>
        /// Sets the parameters of the MouseKeys accessibility feature.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="MOUSEKEYS"/> structure that contains the new parameters.
        /// Set the <see cref="MOUSEKEYS.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(MOUSEKEYS)</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMOUSESONAR"/>
        /// </para>
        /// <para>
        /// 0x101D
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Turns the Sonar accessibility feature on or off.
        /// This feature briefly shows several concentric circles around the mouse pointer when the user presses and releases the CTRL key.
        /// The <paramref name="pvParam"/> parameter specifies <see cref="TRUE"/> for on and <see cref="FALSE"/> for off.
        /// The default is off.
        /// For more information, see Mouse Input Overview.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMOUSEVANISH"/>
        /// </para>
        /// <para>
        /// 0x1021
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Turns the Vanish feature on or off.
        /// This feature hides the mouse pointer when the user types; the pointer reappears when the user moves the mouse.
        /// The <paramref name="pvParam"/> parameter specifies <see cref="TRUE"/> for on and <see cref="FALSE"/> for off.
        /// The default is off.
        /// For more information, see Mouse Input Overview.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETSCREENREADER"/>
        /// </para>
        /// <para>
        /// 0x0047
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether a screen review utility is running.
        /// The <paramref name="uiParam"/> parameter specifies <see cref="TRUE"/> for on, or <see cref="FALSE"/> for off.
        /// </para>
        /// <para>
        /// Note
        /// </para>
        /// <para>
        /// Narrator, the screen reader that is included with Windows,
        /// does not set the <see cref="SPI_SETSCREENREADER"/> or <see cref="SPI_GETSCREENREADER"/> flags. 
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETSERIALKEYS"/>
        /// </para>
        /// <para>
        /// 0x003F
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// This parameter is not supported.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000: The user should control this setting through the Control Panel.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETSHOWSOUNDS"/>
        /// </para>
        /// <para>
        /// 0x0039
        /// </para>
        /// </term>
        /// <term>
        /// Turns the ShowSounds accessibility feature on or off.
        /// The <paramref name="uiParam"/> parameter specifies <see cref="TRUE"/> for on, or <see cref="FALSE"/> for off.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETSOUNDSENTRY"/>
        /// </para>
        /// <para>
        /// 0x0041
        /// </para>
        /// </term>
        /// <term>
        /// Sets the parameters of the <see cref="SoundSentry"/> accessibility feature.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="SOUNDSENTRY"/> structure that contains the new parameters.
        /// Set the <see cref="SOUNDSENTRY.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(SOUNDSENTRY)</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETSTICKYKEYS"/>
        /// </para>
        /// <para>
        /// 0x003B
        /// </para>
        /// </term>
        /// <term>
        /// Sets the parameters of the StickyKeys accessibility feature.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="STICKYKEYS"/> structure that contains the new parameters.
        /// Set the <see cref="STICKYKEYS.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(STICKYKEYS)</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETTOGGLEKEYS"/>
        /// </para>
        /// <para>
        /// 0x0035
        /// </para>
        /// </term>
        /// <term>
        /// Sets the parameters of the ToggleKeys accessibility feature.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="TOGGLEKEYS"/> structure that contains the new parameters.
        /// Set the <see cref="TOGGLEKEYS.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(TOGGLEKEYS)</c>.
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        /// The following are the desktop parameters.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Desktop parameter
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETCLEARTYPE"/>
        /// </para>
        /// <para>
        /// 0x1048
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether ClearType is enabled.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if ClearType is enabled, or <see cref="FALSE"/> otherwise.
        /// </para>
        /// <para>
        /// ClearType is a software technology that improves the readability of text on liquid crystal display (LCD) monitors.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETDESKWALLPAPER"/>
        /// </para>
        /// <para>
        /// 0x0073
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the full path of the bitmap file for the desktop wallpaper.
        /// The <paramref name="pvParam"/> parameter must point to a buffer to receive the null-terminated path string.
        /// Set the <paramref name="uiParam"/> parameter to the size, in characters, of the <paramref name="pvParam"/> buffer.
        /// The returned string will not exceed <see cref="MAX_PATH"/> characters.
        /// If there is no desktop wallpaper, the returned string is empty.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETDROPSHADOW"/>
        /// </para>
        /// <para>
        /// 0x1024
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether the drop shadow effect is enabled.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that returns <see cref="TRUE"/> if enabled or <see cref="FALSE"/> if disabled.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETFLATMENU"/>
        /// </para>
        /// <para>
        /// 0x1022
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether native User menus have flat menu appearance.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that returns <see cref="TRUE"/> if the flat menu appearance is set, or <see cref="FALSE"/> otherwise.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETFONTSMOOTHING"/>
        /// </para>
        /// <para>
        /// 0x004A
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether the font smoothing feature is enabled.
        /// This feature uses font antialiasing to make font curves appear smoother by painting pixels at different gray levels.
        /// </para>
        /// <para>
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if the feature is enabled, or <see cref="FALSE"/> if it is not.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETFONTSMOOTHINGCONTRAST"/>
        /// </para>
        /// <para>
        /// 0x200C
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves a contrast value that is used in ClearType smoothing.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="UINT"/> that receives the information.
        /// Valid contrast values are from 1000 to 2200.
        /// The default value is 1400.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETFONTSMOOTHINGORIENTATION"/>
        /// </para>
        /// <para>
        /// 0x2012
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the font smoothing orientation.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="UINT"/> that receives the information.
        /// The possible values are <see cref="FE_FONTSMOOTHINGORIENTATIONBGR"/> (blue-green-red) and <see cref="FE_FONTSMOOTHINGORIENTATIONRGB"/> (red-green-blue).
        /// </para>
        /// <para>
        /// Windows XP/2000: This parameter is not supported until Windows XP with SP2.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETFONTSMOOTHINGTYPE"/>
        /// </para>
        /// <para>
        /// 0x200A
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the type of font smoothing.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="UINT"/> that receives the information.
        /// The possible values are <see cref="FE_FONTSMOOTHINGSTANDARD"/> and <see cref="FE_FONTSMOOTHINGCLEARTYPE"/>.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETWORKAREA"/>
        /// </para>
        /// <para>
        /// 0x0030
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the size of the work area on the primary display monitor.
        /// The work area is the portion of the screen not obscured by the system taskbar or by application desktop toolbars.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="RECT"/> structure
        /// that receives the coordinates of the work area, expressed in physical pixel size.
        /// Any DPI virtualization mode of the caller has no effect on this output.
        /// </para>
        /// <para>
        /// To get the work area of a monitor other than the primary display monitor, call the <see cref="GetMonitorInfo"/> function.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETCLEARTYPE"/>
        /// </para>
        /// <para>
        /// 0x1049
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Turns ClearType on or off. The <paramref name="pvParam"/> parameter is a <see cref="BOOL"/> variable.
        /// Set <paramref name="pvParam"/> to <see cref="TRUE"/> to enable ClearType, or <see cref="FALSE"/> to disable it.
        /// </para>
        /// <para>
        /// ClearType is a software technology that improves the readability of text on LCD monitors.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETCURSORS"/>
        /// </para>
        /// <para>
        /// 0x0057
        /// </para>
        /// </term>
        /// <term>
        /// Reloads the system cursors.
        /// Set the <paramref name="uiParam"/> parameter to zero and the <paramref name="pvParam"/> parameter to <see cref="NULL"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETDESKPATTERN"/>
        /// </para>
        /// <para>
        /// 0x0015
        /// </para>
        /// </term>
        /// <term>
        /// Sets the current desktop pattern by causing Windows to read the Pattern= setting from the WIN.INI file.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETDESKWALLPAPER"/>
        /// </para>
        /// <para>
        /// 0x0014
        /// </para>
        /// </term>
        /// <term>
        /// Note  When the <see cref="SPI_SETDESKWALLPAPER"/> flag is used,
        /// <see cref="SystemParametersInfo"/> returns <see cref="TRUE"/> unless there is an error (like when the specified file doesn't exist). 
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETDROPSHADOW"/>
        /// </para>
        /// <para>
        /// 0x1025
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Enables or disables the drop shadow effect.
        /// Set <paramref name="pvParam"/> to <see cref="TRUE"/> to enable the drop shadow effect or <see cref="FALSE"/> to disable it.
        /// You must also have <see cref="CS_DROPSHADOW"/> in the window class style.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETFLATMENU"/>
        /// </para>
        /// <para>
        /// 0x1023
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Enables or disables flat menu appearance for native User menus.
        /// Set <paramref name="pvParam"/> to <see cref="TRUE"/> to enable flat menu appearance or <see cref="FALSE"/> to disable it.
        /// </para>
        /// <para>
        /// When enabled, the menu bar uses <see cref="COLOR_MENUBAR"/> for the menubar background,
        /// <see cref="COLOR_MENU"/> for the menu-popup background, <see cref="COLOR_MENUHILIGHT"/> for the fill of the current menu selection,
        /// and <see cref="COLOR_HIGHLIGHT"/> for the outline of the current menu selection.
        /// If disabled, menus are drawn using the same metrics and colors as in Windows 2000.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETFONTSMOOTHING"/>
        /// </para>
        /// <para>
        /// 0x004B
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Enables or disables the font smoothing feature,
        /// which uses font antialiasing to make font curves appear smoother by painting pixels at different gray levels.
        /// </para>
        /// <para>
        /// To enable the feature, set the <paramref name="uiParam"/> parameter to <see cref="TRUE"/>.
        /// To disable the feature, set <paramref name="uiParam"/> to <see cref="FALSE"/>.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETFONTSMOOTHINGCONTRAST"/>
        /// </para>
        /// <para>
        /// 0x200D
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the contrast value used in ClearType smoothing.
        /// The <paramref name="pvParam"/> parameter is the contrast value.
        /// Valid contrast values are from 1000 to 2200. The default value is 1400.
        /// </para>
        /// <para>
        /// <see cref="SPI_SETFONTSMOOTHINGTYPE"/> must also be set to <see cref="FE_FONTSMOOTHINGCLEARTYPE"/>.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETFONTSMOOTHINGORIENTATION"/>
        /// </para>
        /// <para>
        /// 0x2013
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the font smoothing orientation.
        /// The <paramref name="pvParam"/> parameter is either <see cref="FE_FONTSMOOTHINGORIENTATIONBGR"/> (blue-green-red)
        /// or <see cref="FE_FONTSMOOTHINGORIENTATIONRGB"/> (red-green-blue).
        /// </para>
        /// <para>
        /// Windows XP/2000: This parameter is not supported until Windows XP with SP2.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETFONTSMOOTHINGTYPE"/>
        /// </para>
        /// <para>
        /// 0x200B
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the font smoothing type.
        /// The <paramref name="pvParam"/> parameter is either <see cref="FE_FONTSMOOTHINGSTANDARD"/>, if standard anti-aliasing is used,
        /// or <see cref="FE_FONTSMOOTHINGCLEARTYPE"/>, if ClearType is used.
        /// The default is <see cref="FE_FONTSMOOTHINGSTANDARD"/>.
        /// </para>
        /// <para>
        /// <see cref="SPI_SETFONTSMOOTHING"/> must also be set.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETWORKAREA"/>
        /// </para>
        /// <para>
        /// 0x002F
        /// </para>
        /// </term>
        /// <term>
        /// Sets the size of the work area.
        /// The work area is the portion of the screen not obscured by the system taskbar or by application desktop toolbars.
        /// The <paramref name="pvParam"/> parameter is a pointer to a <see cref="RECT"/> structure
        /// that specifies the new work area rectangle, expressed in virtual screen coordinates.
        /// In a system with multiple display monitors, the function sets the work area of the monitor that contains the specified rectangle.
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        /// The following are the icon parameters.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Icon parameter
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETICONMETRICS"/>
        /// </para>
        /// <para>
        /// 0x002D
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the metrics associated with icons.
        /// The <paramref name="pvParam"/> parameter must point to an <see cref="ICONMETRICS"/> structure that receives the information.
        /// Set the <see cref="ICONMETRICS.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(ICONMETRICS)</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETICONTITLELOGFONT"/>
        /// </para>
        /// <para>
        /// 0x001F
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the logical font information for the current icon-title font.
        /// The <paramref name="uiParam"/> parameter specifies the size of a <see cref="LOGFONT"/> structure,
        /// and the <paramref name="pvParam"/> parameter must point to the <see cref="LOGFONT"/> structure to fill in.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETICONTITLEWRAP"/>
        /// </para>
        /// <para>
        /// 0x0019
        /// </para>
        /// </term>
        /// <term>
        /// Determines whether icon-title wrapping is enabled.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if enabled, or <see cref="FALSE"/> otherwise.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_ICONHORIZONTALSPACING"/>
        /// </para>
        /// <para>
        /// 0x000D
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets or retrieves the width, in pixels, of an icon cell.
        /// The system uses this rectangle to arrange icons in large icon view.
        /// </para>
        /// <para>
        /// To set this value, set <paramref name="uiParam"/> to the new value and set <paramref name="pvParam"/> to <see cref="NULL"/>.
        /// You cannot set this value to less than <see cref="SM_CXICON"/>.
        /// </para>
        /// <para>
        /// To retrieve this value, <paramref name="pvParam"/> must point to an integer that receives the current value.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_ICONVERTICALSPACING"/>
        /// </para>
        /// <para>
        /// 0x0018
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets or retrieves the height, in pixels, of an icon cell.
        /// </para>
        /// <para>
        /// To set this value, set <paramref name="uiParam"/> to the new value and set <paramref name="pvParam"/> to <see cref="NULL"/>.
        /// You cannot set this value to less than <see cref="SM_CYICON"/>.
        /// </para>
        /// <para>
        /// To retrieve this value, <paramref name="pvParam"/> must point to an integer that receives the current value.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETICONMETRICS"/>
        /// </para>
        /// <para>
        /// 0x002E
        /// </para>
        /// </term>
        /// <term>
        /// Sets the metrics associated with icons.
        /// The <paramref name="pvParam"/> parameter must point to an <see cref="ICONMETRICS"/> structure that contains the new parameters.
        /// Set the <see cref="ICONMETRICS.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(ICONMETRICS)</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETICONS"/>
        /// </para>
        /// <para>
        /// 0x0058
        /// </para>
        /// </term>
        /// <term>
        /// Reloads the system icons.
        /// Set the <paramref name="uiParam"/> parameter to zero and the <paramref name="pvParam"/> parameter to <see cref="NULL"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETICONTITLELOGFONT"/>
        /// </para>
        /// <para>
        /// 0x0022
        /// </para>
        /// </term>
        /// <term>
        /// Sets the font that is used for icon titles.
        /// The <paramref name="uiParam"/> parameter specifies the size of a <see cref="LOGFONT"/> structure,
        /// and the <paramref name="pvParam"/> parameter must point to a <see cref="LOGFONT"/> structure.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETICONTITLEWRAP"/>
        /// </para>
        /// <para>
        /// 0x001A
        /// </para>
        /// </term>
        /// <term>
        /// Turns icon-title wrapping on or off.
        /// The <paramref name="uiParam"/> parameter specifies <see cref="TRUE"/> for on, or <see cref="FALSE"/> for off.
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        /// The following are the input parameters.
        /// They include parameters related to the keyboard, mouse, pen, input language, and the warning beeper.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Input parameter
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETBEEP"/>
        /// </para>
        /// <para>
        /// 0x0001
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether the warning beeper is on.
        /// </para>
        /// <para>
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if the beeper is on, or <see cref="FALSE"/> if it is off.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETBLOCKSENDINPUTRESETS"/>
        /// </para>
        /// <para>
        /// 0x1026
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves a <see cref="BOOL"/> indicating whether an application can reset the screensaver's timer
        /// by calling the <see cref="SendInput"/> function to simulate keyboard or mouse input.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if the simulated input will be blocked, or <see cref="FALSE"/> otherwise.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETCONTACTVISUALIZATION"/>
        /// </para>
        /// <para>
        /// 0x2018
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the current contact visualization setting.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="ULONG"/> variable that receives the setting.
        /// For more information, see Contact Visualization.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETDEFAULTINPUTLANG"/>
        /// </para>
        /// <para>
        /// 0x0059
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the input locale identifier for the system default input language.
        /// The <paramref name="pvParam"/> parameter must point to an <see cref="HKL"/> variable that receives this value.
        /// For more information, see Languages, Locales, and Keyboard Layouts.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETGESTUREVISUALIZATION"/>
        /// </para>
        /// <para>
        /// 0x201A
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the current gesture visualization setting.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="ULONG"/> variable that receives the setting.
        /// For more information, see Gesture Visualization.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETKEYBOARDCUES"/>
        /// </para>
        /// <para>
        /// 0x100A
        /// </para>
        /// </term>
        /// <term>
        /// Determines whether menu access keys are always underlined.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if menu access keys are always underlined,
        /// and <see cref="FALSE"/> if they are underlined only when the menu is activated by the keyboard.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETKEYBOARDDELAY"/>
        /// </para>
        /// <para>
        /// 0x0016
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the keyboard repeat-delay setting,
        /// which is a value in the range from 0 (approximately 250 ms delay) through 3 (approximately 1 second delay).
        /// The actual delay associated with each value may vary depending on the hardware.
        /// The <paramref name="pvParam"/> parameter must point to an integer variable that receives the setting.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETKEYBOARDPREF"/>
        /// </para>
        /// <para>
        /// 0x0044
        /// </para>
        /// </term>
        /// <term>
        /// Determines whether the user relies on the keyboard instead of the mouse,
        /// and wants applications to display keyboard interfaces that would otherwise be hidden.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if the user relies on the keyboard; or <see cref="FALSE"/> otherwise.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETKEYBOARDSPEED"/>
        /// </para>
        /// <para>
        /// 0x000A
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the keyboard repeat-speed setting, which is a value
        /// in the range from 0 (approximately 2.5 repetitions per second) through 31 (approximately 30 repetitions per second).
        /// The actual repeat rates are hardware-dependent and may vary from a linear scale by as much as 20%.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="DWORD"/> variable that receives the setting.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMOUSE"/>
        /// </para>
        /// <para>
        /// 0x0003
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the two mouse threshold values and the mouse acceleration.
        /// The <paramref name="pvParam"/> parameter must point to an array of three integers that receives these values.
        /// See <see cref="mouse_event"/> for further information.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMOUSEHOVERHEIGHT"/>
        /// </para>
        /// <para>
        /// 0x0064
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the height, in pixels, of the rectangle within which the mouse pointer has to stay
        /// for <see cref="TrackMouseEvent"/> to generate a <see cref="WM_MOUSEHOVER"/> message.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="UINT"/> variable that receives the height.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMOUSEHOVERTIME"/>
        /// </para>
        /// <para>
        /// 0x0066
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the time, in milliseconds, that the mouse pointer has to stay in the hover rectangle
        /// for <see cref="TrackMouseEvent"/> to generate a <see cref="WM_MOUSEHOVER"/> message.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="UINT"/> variable that receives the time.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMOUSEHOVERWIDTH"/>
        /// </para>
        /// <para>
        /// 0x0062
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the width, in pixels, of the rectangle within which the mouse pointer has to stay
        /// for <see cref="TrackMouseEvent"/> to generate a <see cref="WM_MOUSEHOVER"/> message. 
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="UINT"/> variable that receives the width.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMOUSESPEED"/>
        /// </para>
        /// <para>
        /// 0x0070
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the current mouse speed.
        /// The mouse speed determines how far the pointer will move based on the distance the mouse moves.
        /// The <paramref name="pvParam"/> parameter must point to an integer that receives a value which ranges between 1 (slowest) and 20 (fastest).
        /// A value of 10 is the default.
        /// The value can be set by an end-user using the mouse control panel application or by an application using <see cref="SPI_SETMOUSESPEED"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMOUSETRAILS"/>
        /// </para>
        /// <para>
        /// 0x005E
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether the Mouse Trails feature is enabled.
        /// This feature improves the visibility of mouse cursor movements by briefly showing a trail of cursors and quickly erasing them.
        /// </para>
        /// <para>
        /// The <paramref name="pvParam"/> parameter must point to an integer variable that receives a value.
        /// if the value is zero or 1, the feature is disabled.
        /// If the value is greater than 1, the feature is enabled and the value indicates the number of cursors drawn in the trail.
        /// The <paramref name="uiParam"/> parameter is not used.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMOUSEWHEELROUTING"/>
        /// </para>
        /// <para>
        /// 0x201C
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the routing setting for wheel button input.
        /// The routing setting determines whether wheel button input is sent to the app with focus (foreground) or the app under the mouse cursor.
        /// </para>
        /// <para>
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="DWORD"/> variable that receives the routing option.
        /// If the value is zero or <see cref="MOUSEWHEEL_ROUTING_FOCUS"/>, mouse wheel input is delivered to the app with focus.
        /// If the value is 1 or <see cref="MOUSEWHEEL_ROUTING_HYBRID"/> (default), mouse wheel input is delivered to the app
        /// with focus (desktop apps) or the app under the mouse cursor (Windows Store apps).
        /// The <paramref name="uiParam"/> parameter is not used.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETPENVISUALIZATION"/>
        /// </para>
        /// <para>
        /// 0x201E
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the current pen gesture visualization setting.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="ULONG"/> variable
        /// that receives the setting. For more information, see Pen Visualization.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETSNAPTODEFBUTTON"/>
        /// </para>
        /// <para>
        /// 0x005F
        /// </para>
        /// </term>
        /// <term>
        /// Determines whether the snap-to-default-button feature is enabled.
        /// If enabled, the mouse cursor automatically moves to the default button, such as OK or Apply, of a dialog box.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if the feature is on, or <see cref="FALSE"/> if it is off.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETSYSTEMLANGUAGEBAR"/>
        /// </para>
        /// <para>
        /// 0x1050
        /// </para>
        /// </term>
        /// <term>
        /// Starting with Windows 8: Determines whether the system language bar is enabled or disabled.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if the language bar is enabled, or <see cref="FALSE"/> otherwise.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETTHREADLOCALINPUTSETTINGS"/>
        /// </para>
        /// <para>
        /// 0x104E
        /// </para>
        /// </term>
        /// <term>
        /// Starting with Windows 8: Determines whether the active input settings
        /// have Local (per-thread, <see cref="TRUE"/>) or Global (session, <see cref="FALSE"/>) scope.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETTOUCHPADPARAMETERS"/>
        /// </para>
        /// <para>
        /// 0x00AE
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Starting with Windows 11, version 24H2:
        /// Retrieves details about the Precision Touchpad, including user settings and system information related to the touchpad.
        /// </para>
        /// <para>
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="TOUCHPAD_PARAMETERS"/> structure.
        /// </para>
        /// <para>
        /// The <paramref name="uiParam"/> parameter must specify the size of the structure.
        /// </para>
        /// <para>
        /// The value of the <see cref="TOUCHPAD_PARAMETERS.versionNumber"/> field in the <see cref="TOUCHPAD_PARAMETERS"/> structure
        /// must be set to the appropriate value for the version of the structure being used.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETWHEELSCROLLCHARS"/>
        /// </para>
        /// <para>
        /// 0x006C
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the number of characters to scroll when the horizontal mouse wheel is moved.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="UINT"/> variable that receives the number of lines.
        /// The default value is 3.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETWHEELSCROLLLINES"/>
        /// </para>
        /// <para>
        /// 0x0068
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the number of lines to scroll when the vertical mouse wheel is moved.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="UINT"/> variable
        /// that receives the number of lines.
        /// The default value is 3.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETBEEP"/>
        /// </para>
        /// <para>
        /// 0x0002
        /// </para>
        /// </term>
        /// <term>
        /// Turns the warning beeper on or off.
        /// The <paramref name="uiParam"/> parameter specifies <see cref="TRUE"/> for on, or <see cref="FALSE"/> for off.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETBLOCKSENDINPUTRESETS"/>
        /// </para>
        /// <para>
        /// 0x1027
        /// </para>
        /// </term>
        /// <term>
        /// Determines whether an application can reset the screensaver's timer
        /// by calling the <see cref="SendInput"/> function to simulate keyboard or mouse input.
        /// The <paramref name="uiParam"/> parameter specifies <see cref="TRUE"/> if the screensaver will not be deactivated by simulated input,
        /// or <see cref="FALSE"/> if the screensaver will be deactivated by simulated input.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETCONTACTVISUALIZATION"/>
        /// </para>
        /// <para>
        /// 0x2019
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the current contact visualization setting.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="ULONG"/> variable that identifies the setting.
        /// For more information, see Contact Visualization.
        /// </para>
        /// <para>
        /// Note
        /// </para>
        /// <para>
        /// If contact visualizations are disabled, gesture visualizations cannot be enabled. 
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETDEFAULTINPUTLANG"/>
        /// </para>
        /// <para>
        /// 0x005A
        /// </para>
        /// </term>
        /// <term>
        /// Sets the default input language for the system shell and applications.
        /// The specified language must be displayable using the current system character set.
        /// The <paramref name="pvParam"/> parameter must point to an <see cref="HKL"/> variable
        /// that contains the input locale identifier for the default language.
        /// For more information, see Languages, Locales, and Keyboard Layouts.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETDOUBLECLICKTIME"/>
        /// </para>
        /// <para>
        /// 0x0020
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the double-click time for the mouse to the value of the <paramref name="uiParam"/> parameter.
        /// If the <paramref name="uiParam"/> value is greater than 5000 milliseconds,
        /// the system sets the double-click time to 5000 milliseconds.
        /// </para>
        /// <para>
        /// The double-click time is the maximum number of milliseconds that can occur between the first and second clicks of a double-click.
        /// You can also call the <see cref="SetDoubleClickTime"/> function to set the double-click time.
        /// To get the current double-click time, call the <see cref="GetDoubleClickTime"/> function.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETDOUBLECLKHEIGHT"/>
        /// </para>
        /// <para>
        /// 0x001E
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the height of the double-click rectangle to the value of the <paramref name="uiParam"/> parameter.
        /// </para>
        /// <para>
        /// The double-click rectangle is the rectangle within which the second click of a double-click must fall for it to be registered as a double-click.
        /// </para>
        /// <para>
        /// To retrieve the height of the double-click rectangle, call <see cref="GetSystemMetrics"/> with the <see cref="SM_CYDOUBLECLK"/> flag.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETDOUBLECLKWIDTH"/>
        /// </para>
        /// <para>
        /// 0x001D
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the width of the double-click rectangle to the value of the <paramref name="uiParam"/> parameter.
        /// </para>
        /// <para>
        /// The double-click rectangle is the rectangle within which the second click of a double-click must fall for it to be registered as a double-click.
        /// </para>
        /// <para>
        /// To retrieve the width of the double-click rectangle, call <see cref="GetSystemMetrics"/> with the <see cref="SM_CXDOUBLECLK"/> flag.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETGESTUREVISUALIZATION"/>
        /// </para>
        /// <para>
        /// 0x201B
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the current gesture visualization setting.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="ULONG"/> variable that identifies the setting.
        /// For more information, see Gesture Visualization.
        /// </para>
        /// <para>
        /// Note
        /// </para>
        /// <para>
        /// If contact visualizations are disabled, gesture visualizations cannot be enabled.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETKEYBOARDCUES"/>
        /// </para>
        /// <para>
        /// 0x100B
        /// </para>
        /// </term>
        /// <term>
        /// Sets the underlining of menu access key letters.
        /// The <paramref name="pvParam"/> parameter is a <see cref="BOOL"/> variable.
        /// Set <paramref name="pvParam"/> to <see cref="TRUE"/> to always underline menu access keys,
        /// or <see cref="FALSE"/> to underline menu access keys only when the menu is activated from the keyboard.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETKEYBOARDDELAY"/>
        /// </para>
        /// <para>
        /// 0x0017
        /// </para>
        /// </term>
        /// <term>
        /// Sets the keyboard repeat-delay setting.
        /// The <paramref name="uiParam"/> parameter must specify 0, 1, 2, or 3,
        /// where zero sets the shortest delay approximately 250 ms) and 3 sets the longest delay (approximately 1 second).
        /// The actual delay associated with each value may vary depending on the hardware.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETKEYBOARDPREF"/>
        /// </para>
        /// <para>
        /// 0x0045
        /// </para>
        /// </term>
        /// <term>
        /// Sets the keyboard preference.
        /// The <paramref name="uiParam"/> parameter specifies <see cref="TRUE"/> if the user relies on the keyboard instead of the mouse,
        /// and wants applications to display keyboard interfaces that would otherwise be hidden;
        /// <paramref name="uiParam"/> is <see cref="FALSE"/> otherwise.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETKEYBOARDSPEED"/>
        /// </para>
        /// <para>
        /// 0x000B
        /// </para>
        /// </term>
        /// <term>
        /// Sets the keyboard repeat-speed setting.
        /// The <paramref name="uiParam"/> parameter must specify a value in the range
        /// from 0 (approximately 2.5 repetitions per second) through 31 (approximately 30 repetitions per second).
        /// The actual repeat rates are hardware-dependent and may vary from a linear scale by as much as 20%.
        /// If <paramref name="uiParam"/> is greater than 31, the parameter is set to 31.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETLANGTOGGLE"/>
        /// </para>
        /// <para>
        /// 0x005B
        /// </para>
        /// </term>
        /// <term>
        /// Sets the hot key set for switching between input languages.
        /// The <paramref name="uiParam"/> and <paramref name="pvParam"/> parameters are not used.
        /// The value sets the shortcut keys in the keyboard property sheets by reading the registry again.
        /// The registry must be set before this flag is used. the path in the registry is <c>HKEY_CURRENT_USER\Keyboard Layout\Toggle</c>.
        /// Valid values are "1" = ALT+SHIFT, "2" = CTRL+SHIFT, and "3" = none.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMOUSE"/>
        /// </para>
        /// <para>
        /// 0x0004
        /// </para>
        /// </term>
        /// <term>
        /// Sets the two mouse threshold values and the mouse acceleration.
        /// The <paramref name="pvParam"/> parameter must point to an array of three integers that specifies these values.
        /// See <see cref="mouse_event"/> for further information.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMOUSEBUTTONSWAP"/>
        /// </para>
        /// <para>
        /// 0x0021
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Swaps or restores the meaning of the left and right mouse buttons.
        /// The <paramref name="uiParam"/> parameter specifies <see cref="TRUE"/> to swap the meanings of the buttons,
        /// or <see cref="FALSE"/> to restore their original meanings.
        /// </para>
        /// <para>
        /// To retrieve the current setting, call <see cref="GetSystemMetrics"/> with the <see cref="SM_SWAPBUTTON"/> flag.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMOUSEHOVERHEIGHT"/>
        /// </para>
        /// <para>
        /// 0x0065
        /// </para>
        /// </term>
        /// <term>
        /// Sets the height, in pixels, of the rectangle within which the mouse pointer has to stay
        /// for <see cref="TrackMouseEvent"/> to generate a <see cref="WM_MOUSEHOVER"/> message.
        /// Set the <paramref name="uiParam"/> parameter to the new height.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMOUSEHOVERTIME"/>
        /// </para>
        /// <para>
        /// 0x0067
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the time, in milliseconds, that the mouse pointer has to stay in the hover rectangle
        /// for <see cref="TrackMouseEvent"/> to generate a <see cref="WM_MOUSEHOVER"/> message.
        /// This is used only if you pass <see cref="HOVER_DEFAULT"/> in the <c>dwHoverTime</c> parameter in the call to <see cref="TrackMouseEvent"/>.
        /// Set the <paramref name="uiParam"/> parameter to the new time.
        /// </para>
        /// <para>
        /// The time specified should be between <see cref="USER_TIMER_MAXIMUM"/> and <see cref="USER_TIMER_MINIMUM"/>.
        /// If <paramref name="uiParam"/> is less than <see cref="USER_TIMER_MINIMUM"/>, the function will use <see cref="USER_TIMER_MINIMUM"/>.
        /// If <paramref name="uiParam"/> is greater than <see cref="USER_TIMER_MAXIMUM"/>, the function will be <see cref="USER_TIMER_MAXIMUM"/>.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP:
        /// The operating system does not enforce the use of <see cref="USER_TIMER_MAXIMUM"/> and <see cref="USER_TIMER_MINIMUM"/>
        /// until Windows Server 2003 with SP1 and Windows XP with SP2.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMOUSEHOVERWIDTH"/>
        /// </para>
        /// <para>
        /// 0x0063
        /// </para>
        /// </term>
        /// <term>
        /// Sets the width, in pixels, of the rectangle within which the mouse pointer has to stay
        /// for <see cref="TrackMouseEvent"/> to generate a <see cref="WM_MOUSEHOVER"/> message.
        /// Set the <paramref name="uiParam"/> parameter to the new width.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMOUSESPEED"/>
        /// </para>
        /// <para>
        /// 0x0071
        /// </para>
        /// </term>
        /// <term>
        /// Sets the current mouse speed.
        /// The <paramref name="pvParam"/> parameter is an integer between 1 (slowest) and 20 (fastest).
        /// A value of 10 is the default.
        /// This value is typically set using the mouse control panel application.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMOUSETRAILS"/>
        /// </para>
        /// <para>
        /// 0x005D
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Enables or disables the Mouse Trails feature, which improves the visibility of mouse cursor movements
        /// by briefly showing a trail of cursors and quickly erasing them.
        /// </para>
        /// <para>
        /// To disable the feature, set the <paramref name="uiParam"/> parameter to zero or 1.
        /// To enable the feature, set <paramref name="uiParam"/> to a value greater than 1 to indicate the number of cursors drawn in the trail.
        /// </para>
        /// <para>
        /// Windows 2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMOUSEWHEELROUTING"/>
        /// </para>
        /// <para>
        /// 0x201D
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the routing setting for wheel button input.
        /// The routing setting determines whether wheel button input is sent to the app with focus (foreground) or the app under the mouse cursor.
        /// </para>
        /// <para>
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="DWORD"/> variable that receives the routing option.
        /// If the value is zero or <see cref="MOUSEWHEEL_ROUTING_FOCUS"/>, mouse wheel input is delivered to the app with focus.
        /// If the value is 1 or <see cref="MOUSEWHEEL_ROUTING_HYBRID"/> (default), mouse wheel input is delivered to the app
        /// with focus (desktop apps) or the app under the mouse cursor (Windows Store apps).
        /// Set the <paramref name="uiParam"/> parameter to zero.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETPENVISUALIZATION"/>
        /// </para>
        /// <para>
        /// 0x201F
        /// </para>
        /// </term>
        /// <term>
        /// Sets the current pen gesture visualization setting.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="ULONG"/> variable that identifies the setting.
        /// For more information, see Pen Visualization.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETSNAPTODEFBUTTON"/>
        /// </para>
        /// <para>
        /// 0x0060
        /// </para>
        /// </term>
        /// <term>
        /// Enables or disables the snap-to-default-button feature.
        /// If enabled, the mouse cursor automatically moves to the default button, such as OK or Apply, of a dialog box.
        /// Set the <paramref name="uiParam"/> parameter to <see cref="TRUE"/> to enable the feature, or <see cref="FALSE"/> to disable it.
        /// Applications should use the <see cref="ShowWindow"/> function when displaying a dialog box so the dialog manager can position the mouse cursor.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETSYSTEMLANGUAGEBAR"/>
        /// </para>
        /// <para>
        /// 0x1051
        /// </para>
        /// </term>
        /// <term>
        /// Starting with Windows 8: Turns the legacy language bar feature on or off.
        /// The <paramref name="pvParam"/> parameter is a pointer to a <see cref="BOOL"/> variable.
        /// Set <paramref name="pvParam"/> to <see cref="TRUE"/> to enable the legacy language bar, or <see cref="FALSE"/> to disable it.
        /// The flag is supported on Windows 8 where the legacy language bar is replaced by Input Switcher and therefore turned off by default.
        /// Turning the legacy language bar on is provided for compatibility reasons and has no effect on the Input Switcher.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETTHREADLOCALINPUTSETTINGS"/>
        /// </para>
        /// <para>
        /// 0x104F
        /// </para>
        /// </term>
        /// <term>
        /// Starting with Windows 8: Determines whether the active input settings have
        /// Local (per-thread, <see cref="TRUE"/>) or Global (session, <see cref="FALSE"/>) scope.
        /// The <paramref name="pvParam"/> parameter must be a <see cref="BOOL"/> variable, casted by PVOID.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETTOUCHPADPARAMETERS"/>
        /// </para>
        /// <para>
        /// 0x00AF
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Starting with Windows 11, version 24H2:
        /// Sets details about the Precision Touchpad, including user settings and system information related to the touchpad.
        /// </para>
        /// <para>
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="TOUCHPAD_PARAMETERS"/> structure.
        /// </para>
        /// <para>
        /// The <paramref name="uiParam"/> parameter must specify the size of the structure.
        /// </para>
        /// <para>
        /// The value of the <see cref="TOUCHPAD_PARAMETERS.versionNumber"/> field in the <see cref="TOUCHPAD_PARAMETERS"/> structure
        /// must be set to the appropriate value for the version of the structure being used.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETWHEELSCROLLCHARS"/>
        /// </para>
        /// <para>
        /// 0x006D
        /// </para>
        /// </term>
        /// <term>
        /// Sets the number of characters to scroll when the horizontal mouse wheel is moved.
        /// The number of characters is set from the <paramref name="uiParam"/> parameter.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETWHEELSCROLLLINES"/>
        /// </para>
        /// <para>
        /// 0x0069
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the number of lines to scroll when the vertical mouse wheel is moved.
        /// The number of lines is set from the <paramref name="uiParam"/> parameter.
        /// </para>
        /// <para>
        /// The number of lines is the suggested number of lines to scroll when the mouse wheel is rolled without using modifier keys.
        /// If the number is 0, then no scrolling should occur.
        /// If the number of lines to scroll is greater than the number of lines viewable,
        /// and in particular if it is <see cref="WHEEL_PAGESCROLL"/> (#defined as <see cref="UINT_MAX"/>),
        /// the scroll operation should be interpreted as clicking once in the page down or page up regions of the scroll bar.
        /// </para>
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        ///  
        /// </para>
        /// <para>
        /// The following are the menu parameters.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Menu parameter
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMENUDROPALIGNMENT"/>
        /// </para>
        /// <para>
        /// 0x001B
        /// </para>
        /// </term>
        /// <term>
        /// Determines whether pop-up menus are left-aligned or right-aligned, relative to the corresponding menu-bar item.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if right-aligned, or <see cref="FALSE"/> otherwise.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMENUFADE"/>
        /// </para>
        /// <para>
        /// 0x1012
        /// </para>
        /// </term>
        /// <term>
        /// Determines whether menu fade animation is enabled.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> when fade animation is enabled and <see cref="FALSE"/> when it isdisabled.
        /// If fade animation is disabled, menus use slide animation.
        /// This flag is ignored unless menu animation is enabled, which you can do using the <see cref="SPI_SETMENUANIMATION"/> flag.
        /// For more information, see <see cref="AnimateWindow"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMENUSHOWDELAY"/>
        /// </para>
        /// <para>
        /// 0x006A
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the time, in milliseconds, that the system waits before displaying a shortcut menu when the mouse cursor is over a submenu item.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="DWORD"/> variable that receives the time of the delay.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMENUDROPALIGNMENT"/>
        /// </para>
        /// <para>
        /// 0x001C
        /// </para>
        /// </term>
        /// <term>
        /// Sets the alignment value of pop-up menus.
        /// The <paramref name="uiParam"/> parameter specifies <see cref="TRUE"/> for right alignment, or <see cref="FALSE"/> for left alignment.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMENUFADE"/>
        /// </para>
        /// <para>
        /// 0x1013
        /// </para>
        /// </term>
        /// <term>
        /// Enables or disables menu fade animation.
        /// Set <paramref name="pvParam"/> to <see cref="TRUE"/> to enable the menu fade effect or <see cref="FALSE"/> to disable it.
        /// If fade animation is disabled, menus use slide animation.
        /// The menu fade effect is possible only if the system has a color depth of more than 256 colors.
        /// This flag is ignored unless <see cref="SPI_SETMENUANIMATION"/> is also set.
        /// For more information, see <see cref="AnimateWindow"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMENUSHOWDELAY"/>
        /// </para>
        /// <para>
        /// 0x006B
        /// </para>
        /// </term>
        /// <term>
        /// Sets <paramref name="uiParam"/> to the time, in milliseconds,
        /// that the system waits before displaying a shortcut menu when the mouse cursor is over a submenu item.
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        ///  
        /// </para>
        /// <para>
        /// The following are the power parameters.
        /// </para>
        /// <para>
        /// Beginning with Windows Server 2008 and Windows Vista, these power parameters are not supported.
        /// Instead, to determine the current display power state,
        /// an application should register for <see cref="GUID_MONITOR_POWER_STATE"/> notifications.
        /// To determine the current display power down time-out,
        /// an application should register for notification of changes to the <see cref="GUID_VIDEO_POWERDOWN_TIMEOUT"/> power setting.
        /// For more information, see Registering for Power Events.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000: To determine the current display power state, use the following power parameters.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Power parameter
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETLOWPOWERACTIVE"/>
        /// </para>
        /// <para>
        /// 0x0053
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// This parameter is not supported.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000:
        /// Determines whether the low-power phase of screen saving is enabled.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if enabled, or <see cref="FALSE"/> if disabled.
        /// This flag is supported for 32-bit applications only.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETLOWPOWERTIMEOUT"/>
        /// </para>
        /// <para>
        /// 0x004F
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// This parameter is not supported.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000:
        /// Retrieves the time-out value for the low-power phase of screen saving.
        /// The <paramref name="pvParam"/> parameter must point to an integer variable that receives the value.
        /// This flag is supported for 32-bit applications only.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETPOWEROFFACTIVE"/>
        /// </para>
        /// <para>
        /// 0x0054
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// This parameter is not supported.
        /// When the power-off phase of screen saving is enabled, the <see cref="GUID_VIDEO_POWERDOWN_TIMEOUT"/> power setting is greater than zero.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000:
        /// Determines whether the power-off phase of screen saving is enabled.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if enabled, or <see cref="FALSE"/> if disabled.
        /// This flag is supported for 32-bit applications only.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETPOWEROFFTIMEOUT"/>
        /// </para>
        /// <para>
        /// 0x0050
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// This parameter is not supported. Instead, check the <see cref="GUID_VIDEO_POWERDOWN_TIMEOUT"/> power setting.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000:
        /// Retrieves the time-out value for the power-off phase of screen saving.
        /// The <paramref name="pvParam"/> parameter must point to an integer variable that receives the value.
        /// This flag is supported for 32-bit applications only.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETLOWPOWERACTIVE"/>
        /// </para>
        /// <para>
        /// 0x0055
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// This parameter is not supported.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000:
        /// Activates or deactivates the low-power phase of screen saving.
        /// Set <paramref name="uiParam"/> to 1 to activate, or zero to deactivate.
        /// The <paramref name="pvParam"/> parameter must be <see cref="NULL"/>.
        /// This flag is supported for 32-bit applications only.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETLOWPOWERTIMEOUT"/>
        /// </para>
        /// <para>
        /// 0x0051
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// This parameter is not supported.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000:
        /// Sets the time-out value, in seconds, for the low-power phase of screen saving.
        /// The <paramref name="uiParam"/> parameter specifies the new value.
        /// The <paramref name="pvParam"/> parameter must be <see cref="NULL"/>.
        /// This flag is supported for 32-bit applications only.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETPOWEROFFACTIVE"/>
        /// </para>
        /// <para>
        /// 0x0056
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// This parameter is not supported.
        /// Instead, set the <see cref="GUID_VIDEO_POWERDOWN_TIMEOUT"/> power setting.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000:
        /// Activates or deactivates the power-off phase of screen saving.
        /// Set <paramref name="uiParam"/> to 1 to activate, or zero to deactivate.
        /// The <paramref name="pvParam"/> parameter must be <see cref="NULL"/>.
        /// This flag is supported for 32-bit applications only.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETPOWEROFFTIMEOUT"/>
        /// </para>
        /// <para>
        /// 0x0052
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// This parameter is not supported. Instead, set the <see cref="GUID_VIDEO_POWERDOWN_TIMEOUT"/> power setting to a time-out value.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000:
        /// Sets the time-out value, in seconds, for the power-off phase of screen saving.
        /// The <paramref name="uiParam"/> parameter specifies the new value.
        /// The <paramref name="pvParam"/> parameter must be <see cref="NULL"/>.
        /// This flag is supported for 32-bit applications only.
        /// </para>
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        /// The following are the screen saver parameters.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Screen saver parameter
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETSCREENSAVEACTIVE"/>
        /// </para>
        /// <para>
        /// 0x0010
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether screen saving is enabled.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if screen saving is enabled, or <see cref="FALSE"/> otherwise.
        /// </para>
        /// <para>
        /// Windows 7, Windows Server 2008 R2 and Windows 2000:
        /// The function returns <see cref="TRUE"/> even when screen saving is not enabled.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETSCREENSAVERRUNNING"/>
        /// </para>
        /// <para>
        /// 0x0072
        /// </para>
        /// </term>
        /// <term>
        /// Determines whether a screen saver is currently running on the window station of the calling process.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if a screen saver is currently running, or <see cref="FALSE"/> otherwise.
        /// Note that only the interactive window station, WinSta0, can have a screen saver running.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETSCREENSAVESECURE"/>
        /// </para>
        /// <para>
        /// 0x0076
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether the screen saver requires a password to display the Windows desktop.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if the screen saver requires a password, or <see cref="FALSE"/> otherwise.
        /// The <paramref name="uiParam"/> parameter is ignored.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETSCREENSAVETIMEOUT"/>
        /// </para>
        /// <para>
        /// 0x000E
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the screen saver time-out value, in seconds.
        /// The <paramref name="pvParam"/> parameter must point to an integer variable that receives the value.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETSCREENSAVEACTIVE"/>
        /// </para>
        /// <para>
        /// 0x0011
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the state of the screen saver.
        /// The <paramref name="uiParam"/> parameter specifies <see cref="TRUE"/> to activate screen saving, or <see cref="FALSE"/> to deactivate it.
        /// </para>
        /// <para>
        /// If the machine has entered power saving mode or system lock state, an <see cref="ERROR_OPERATION_IN_PROGRESS"/> exception occurs.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETSCREENSAVESECURE"/>
        /// </para>
        /// <para>
        /// 0x0077
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets whether the screen saver requires the user to enter a password to display the Windows desktop.
        /// The <paramref name="uiParam"/> parameter is a <see cref="BOOL"/> variable.
        /// The <paramref name="pvParam"/> parameter is ignored.
        /// Set <paramref name="uiParam"/> to <see cref="TRUE"/> to require a password, or <see cref="FALSE"/> to not require a password.
        /// </para>
        /// <para>
        /// If the machine has entered power saving mode or system lock state, an <see cref="ERROR_OPERATION_IN_PROGRESS"/> exception occurs.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETSCREENSAVETIMEOUT"/>
        /// </para>
        /// <para>
        /// 0x000F
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the screen saver time-out value to the value of the <paramref name="uiParam"/> parameter.
        /// This value is the amount of time, in seconds, that the system must be idle before the screen saver activates.
        /// </para>
        /// <para>
        /// If the machine has entered power saving mode or system lock state, an <see cref="ERROR_OPERATION_IN_PROGRESS"/> exception occurs.
        /// </para>
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        /// The following are the time-out parameters for applications and services.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Time-out parameter
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETHUNGAPPTIMEOUT"/>
        /// </para>
        /// <para>
        /// 0x0078
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the number of milliseconds that a thread can go without dispatching a message before the system considers it unresponsive.
        /// The <paramref name="pvParam"/> parameter must point to an integer variable that receives the value.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETWAITTOKILLTIMEOUT"/>
        /// </para>
        /// <para>
        /// 0x007A
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the number of milliseconds that the system waits before terminating an application that does not respond to a shutdown request.
        /// The <paramref name="pvParam"/> parameter must point to an integer variable that receives the value.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETWAITTOKILLSERVICETIMEOUT"/>
        /// </para>
        /// <para>
        /// 0x007C
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the number of milliseconds that the service control manager waits before terminating a service that does not respond to a shutdown request.
        /// The <paramref name="pvParam"/> parameter must point to an integer variable that receives the value.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETHUNGAPPTIMEOUT"/>
        /// </para>
        /// <para>
        /// 0x0079
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the hung application time-out to the value of the <paramref name="uiParam"/> parameter.
        /// This value is the number of milliseconds that a thread can go without dispatching a message before the system considers it unresponsive.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETWAITTOKILLTIMEOUT"/>
        /// </para>
        /// <para>
        /// 0x007B
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the application shutdown request time-out to the value of the <paramref name="uiParam"/> parameter.
        /// This value is the number of milliseconds that the system waits before terminating an application that does not respond to a shutdown request.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETWAITTOKILLSERVICETIMEOUT"/>
        /// </para>
        /// <para>
        /// 0x007D
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the service shutdown request time-out to the value of the <paramref name="uiParam"/> parameter.
        /// This value is the number of milliseconds that the system waits before terminating a service that does not respond to a shutdown request.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        ///  
        /// </para>
        /// <para>
        /// The following are the UI effects.
        /// The <see cref="SPI_SETUIEFFECTS"/> value is used to enable or disable all UI effects at once.
        /// This table contains the complete list of UI effect values.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// UI effects parameter
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETCOMBOBOXANIMATION"/>
        /// </para>
        /// <para>
        /// 0x1004
        /// </para>
        /// </term>
        /// <term>
        /// Determines whether the slide-open effect for combo boxes is enabled.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> for enabled, or <see cref="FALSE"/> for disabled.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETCURSORSHADOW"/>
        /// </para>
        /// <para>
        /// 0x101A
        /// </para>
        /// </term>
        /// <term>
        /// Determines whether the cursor has a shadow around it.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if the shadow is enabled, <see cref="FALSE"/> if it is disabled.
        /// This effect appears only if the system has a color depth of more than 256 colors.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETGRADIENTCAPTIONS"/>
        /// </para>
        /// <para>
        /// 0x1008
        /// </para>
        /// </term>
        /// <term>
        /// Determines whether the gradient effect for window title bars is enabled.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> for enabled, or <see cref="FALSE"/> for disabled.
        /// For more information about the gradient effect, see the <see cref="GetSysColor"/> function.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETHOTTRACKING"/>
        /// </para>
        /// <para>
        /// 0x100E
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether hot tracking of user-interface elements, such as menu names on menu bars, is enabled.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> for enabled, or <see cref="FALSE"/> for disabled.
        /// </para>
        /// <para>
        /// Hot tracking means that when the cursor moves over an item, it is highlighted but not selected.
        /// You can query this value to decide whether to use hot tracking in the user interface of your application.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETLISTBOXSMOOTHSCROLLING"/>
        /// </para>
        /// <para>
        /// 0x1006
        /// </para>
        /// </term>
        /// <term>
        /// Determines whether the smooth-scrolling effect for list boxes is enabled.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> for enabled, or <see cref="FALSE"/> for disabled.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMENUANIMATION"/>
        /// </para>
        /// <para>
        /// 0x1002
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether the menu animation feature is enabled.
        /// This master switch must be on to enable menu animation effects.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if animation is enabled and <see cref="FALSE"/> if it is disabled.
        /// </para>
        /// <para>
        /// If animation is enabled, <see cref="SPI_GETMENUFADE"/> indicates whether menus use fade or slide animation.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMENUUNDERLINES"/>
        /// </para>
        /// <para>
        /// 0x100A
        /// </para>
        /// </term>
        /// <term>
        /// Same as <see cref="SPI_GETKEYBOARDCUES"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETSELECTIONFADE"/>
        /// </para>
        /// <para>
        /// 0x1014
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether the selection fade effect is enabled.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if enabled or <see cref="FALSE"/> if disabled.
        /// </para>
        /// <para>
        /// The selection fade effect causes the menu item selected by the user to remain on the screen briefly while fading out after the menu is dismissed.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETTOOLTIPANIMATION"/>
        /// </para>
        /// <para>
        /// 0x1016
        /// </para>
        /// </term>
        /// <term>
        /// Determines whether ToolTip animation is enabled.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if enabled or <see cref="FALSE"/> if disabled.
        /// If ToolTip animation is enabled, <see cref="SPI_GETTOOLTIPFADE"/> indicates whether ToolTips use fade or slide animation.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETTOOLTIPFADE"/>
        /// </para>
        /// <para>
        /// 0x1018
        /// </para>
        /// </term>
        /// <term>
        /// If <see cref="SPI_SETTOOLTIPANIMATION"/> is enabled,
        /// <see cref="SPI_GETTOOLTIPFADE"/> indicates whether ToolTip animation uses a fade effect or a slide effect.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> for fade animation or <see cref="FALSE"/> for slide animation.
        /// For more information on slide and fade effects, see <see cref="AnimateWindow"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETUIEFFECTS"/>
        /// </para>
        /// <para>
        /// 0x103E
        /// </para>
        /// </term>
        /// <term>
        /// Determines whether UI effects are enabled or disabled.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if all UI effects are enabled, or <see cref="FALSE"/> if they are disabled.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETCOMBOBOXANIMATION"/>
        /// </para>
        /// <para>
        /// 0x1005
        /// </para>
        /// </term>
        /// <term>
        /// Enables or disables the slide-open effect for combo boxes.
        /// Set the <paramref name="pvParam"/> parameter to <see cref="TRUE"/> to enable the gradient effect, or <see cref="FALSE"/> to disable it.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETCURSORSHADOW"/>
        /// </para>
        /// <para>
        /// 0x101B
        /// </para>
        /// </term>
        /// <term>
        /// Enables or disables a shadow around the cursor.
        /// The <paramref name="pvParam"/> parameter is a <see cref="BOOL"/> variable.
        /// Set <paramref name="pvParam"/> to <see cref="TRUE"/> to enable the shadow or <see cref="FALSE"/> to disable the shadow.
        /// This effect appears only if the system has a color depth of more than 256 colors.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETGRADIENTCAPTIONS"/>
        /// </para>
        /// <para>
        /// 0x1009
        /// </para>
        /// </term>
        /// <term>
        /// Enables or disables the gradient effect for window title bars.
        /// Set the <paramref name="pvParam"/> parameter to <see cref="TRUE"/> to enable it, or <see cref="FALSE"/> to disable it.
        /// The gradient effect is possible only if the system has a color depth of more than 256 colors.
        /// For more information about the gradient effect, see the <see cref="GetSysColor"/> function.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETHOTTRACKING"/>
        /// </para>
        /// <para>
        /// 0x100F
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Enables or disables hot tracking of user-interface elements such as menu names on menu bars.
        /// Set the <paramref name="pvParam"/> parameter to <see cref="TRUE"/> to enable it, or <see cref="FALSE"/> to disable it.
        /// </para>
        /// <para>
        /// Hot-tracking means that when the cursor moves over an item, it is highlighted but not selected.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETLISTBOXSMOOTHSCROLLING"/>
        /// </para>
        /// <para>
        /// 0x1007
        /// </para>
        /// </term>
        /// <term>
        /// Enables or disables the smooth-scrolling effect for list boxes.
        /// Set the <paramref name="pvParam"/> parameter to <see cref="TRUE"/> to enable the smooth-scrolling effect, or <see cref="FALSE"/> to disable it.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMENUANIMATION"/>
        /// </para>
        /// <para>
        /// 0x1003
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Enables or disables menu animation.
        /// This master switch must be on for any menu animation to occur.
        /// The <paramref name="pvParam"/> parameter is a <see cref="BOOL"/> variable;
        /// set <paramref name="pvParam"/> to <see cref="TRUE"/> to enable animation and <see cref="FALSE"/> to disable animation.
        /// </para>
        /// <para>
        /// If animation is enabled, <see cref="SPI_GETMENUFADE"/> indicates whether menus use fade or slide animation.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMENUUNDERLINES"/>
        /// </para>
        /// <para>
        /// 0x100B
        /// </para>
        /// </term>
        /// <term>
        /// Same as <see cref="SPI_SETKEYBOARDCUES"/>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETSELECTIONFADE"/>
        /// </para>
        /// <para>
        /// 0x1015
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Set <paramref name="pvParam"/> to <see cref="TRUE"/> to enable the selection fade effect or <see cref="FALSE"/> to disable it.
        /// </para>
        /// <para>
        /// The selection fade effect causes the menu item selected by the user to remain on the screen briefly
        /// while fading out after the menu is dismissed.
        /// The selection fade effect is possible only if the system has a color depth of more than 256 colors.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETTOOLTIPANIMATION"/>
        /// </para>
        /// <para>
        /// 0x1017
        /// </para>
        /// </term>
        /// <term>
        /// Set <paramref name="pvParam"/> to <see cref="TRUE"/> to enable ToolTip animation or <see cref="FALSE"/> to disable it.
        /// If enabled, you can use <see cref="SPI_SETTOOLTIPFADE"/> to specify fade or slide animation.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETTOOLTIPFADE"/>
        /// </para>
        /// <para>
        /// 0x1019
        /// </para>
        /// </term>
        /// <term>
        /// If the <see cref="SPI_SETTOOLTIPANIMATION"/> flag is enabled,
        /// use <see cref="SPI_SETTOOLTIPFADE"/> to indicate whether ToolTip animation uses a fade effect or a slide effect.
        /// Set <paramref name="pvParam"/> to <see cref="TRUE"/> for fade animation or <see cref="FALSE"/> for slide animation.
        /// The tooltip fade effect is possible only if the system has a color depth of more than 256 colors.
        /// For more information on the slide and fade effects, see the <see cref="AnimateWindow"/> function.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETUIEFFECTS"/>
        /// </para>
        /// <para>
        /// 0x103F
        /// </para>
        /// </term>
        /// <term>
        /// Enables or disables UI effects.
        /// Set the <paramref name="pvParam"/> parameter to <see cref="TRUE"/> to enable all UI effects or <see cref="FALSE"/> to disable all UI effects.
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// <para>
        /// The following are the window parameters.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Window parameter
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETACTIVEWINDOWTRACKING"/>
        /// </para>
        /// <para>
        /// 0x1000
        /// </para>
        /// </term>
        /// <term>
        /// Determines whether active window tracking (activating the window the mouse is on) is on or off.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> for on, or <see cref="FALSE"/> for off.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETACTIVEWNDTRKZORDER"/>
        /// </para>
        /// <para>
        /// 0x100C
        /// </para>
        /// </term>
        /// <term>
        /// Determines whether windows activated through active window tracking will be brought to the top.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> for on, or <see cref="FALSE"/> for off.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETACTIVEWNDTRKTIMEOUT"/>
        /// </para>
        /// <para>
        /// 0x2002
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the active window tracking delay, in milliseconds.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="DWORD"/> variable that receives the time.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETANIMATION"/>
        /// </para>
        /// <para>
        /// 0x0048
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the animation effects associated with user actions.
        /// The <paramref name="pvParam"/> parameter must point to an <see cref="ANIMATIONINFO"/> structure that receives the information.
        /// Set the <see cref="ANIMATIONINFO.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(ANIMATIONINFO)</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETBORDER"/>
        /// </para>
        /// <para>
        /// 0x0005
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the border multiplier factor that determines the width of a window's sizing border.
        /// The <paramref name="pvParam"/> parameter must point to an integer variable that receives this value.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETCARETWIDTH"/>
        /// </para>
        /// <para>
        /// 0x2006
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the caret width in edit controls, in pixels.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="DWORD"/> variable that receives this value.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETDOCKMOVING"/>
        /// </para>
        /// <para>
        /// 0x0090
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether a window is docked when it is moved to the top, left, or right edges of a monitor or monitor array.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if enabled, or <see cref="FALSE"/> otherwise.
        /// </para>
        /// <para>
        /// Use <see cref="SPI_GETWINARRANGING"/> to determine whether this behavior is enabled.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETDRAGFROMMAXIMIZE"/>
        /// </para>
        /// <para>
        /// 0x008C
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether a maximized window is restored when its caption bar is dragged.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if enabled, or <see cref="FALSE"/> otherwise.
        /// </para>
        /// <para>
        /// Use <see cref="SPI_GETWINARRANGING"/> to determine whether this behavior is enabled.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETDRAGFULLWINDOWS"/>
        /// </para>
        /// <para>
        /// 0x0026
        /// </para>
        /// </term>
        /// <term>
        /// Determines whether dragging of full windows is enabled.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if enabled, or <see cref="FALSE"/> otherwise.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETFOREGROUNDFLASHCOUNT"/>
        /// </para>
        /// <para>
        /// 0x2004
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the number of times <see cref="SetForegroundWindow"/> will flash the taskbar button when rejecting a foreground switch request.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="DWORD"/> variable that receives the value.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETFOREGROUNDLOCKTIMEOUT"/>
        /// </para>
        /// <para>
        /// 0x2000
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the amount of time following user input, in milliseconds,
        /// during which the system will not allow applications to force themselves into the foreground.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="DWORD"/> variable that receives the time.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMINIMIZEDMETRICS"/>
        /// </para>
        /// <para>
        /// 0x002B
        /// </para>
        /// </term>
        /// <term>
        /// Retrieves the metrics associated with minimized windows.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="MINIMIZEDMETRICS"/> structure that receives the information.
        /// Set the <see cref="MINIMIZEDMETRICS.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(MINIMIZEDMETRICS)</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMOUSEDOCKTHRESHOLD"/>
        /// </para>
        /// <para>
        /// 0x007E
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the threshold in pixels where docking behavior is triggered by using a mouse to drag a window to the edge of a monitor or monitor array.
        /// The default threshold is 1. The <paramref name="pvParam"/> parameter must point to a <see cref="DWORD"/> variable that receives the value.
        /// </para>
        /// <para>
        /// Use <see cref="SPI_GETWINARRANGING"/> to determine whether this behavior is enabled.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMOUSEDRAGOUTTHRESHOLD"/>
        /// </para>
        /// <para>
        /// 0x0084
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the threshold in pixels where undocking behavior is triggered
        /// by using a mouse to drag a window from the edge of a monitor or a monitor array toward the center.
        /// The default threshold is 20.
        /// </para>
        /// <para>
        /// Use <see cref="SPI_GETWINARRANGING"/> to determine whether this behavior is enabled.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETMOUSESIDEMOVETHRESHOLD"/>
        /// </para>
        /// <para>
        /// 0x0088
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the threshold in pixels from the top of a monitor or a monitor array
        /// where a vertically maximized window is restored when dragged with the mouse.
        /// The default threshold is 50.
        /// </para>
        /// <para>
        /// Use <see cref="SPI_GETWINARRANGING"/> to determine whether this behavior is enabled.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETNONCLIENTMETRICS"/>
        /// </para>
        /// <para>
        /// 0x0029
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the metrics associated with the nonclient area of nonminimized windows.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="NONCLIENTMETRICS"/> structure that receives the information.
        /// Set the <see cref="NONCLIENTMETRICS.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(NONCLIENTMETRICS)</c>.
        /// </para>
        /// <para>
        /// Windows Server 2003 and Windows XP/2000: See Remarks for <see cref="NONCLIENTMETRICS"/>.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETPENDOCKTHRESHOLD"/>
        /// </para>
        /// <para>
        /// 0x0080
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the threshold in pixels where docking behavior is triggered
        /// by using a pen to drag a window to the edge of a monitor or monitor array.
        /// The default is 30.
        /// </para>
        /// <para>
        /// Use <see cref="SPI_GETWINARRANGING"/> to determine whether this behavior is enabled.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETPENDRAGOUTTHRESHOLD"/>
        /// </para>
        /// <para>
        /// 0x0086
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the threshold in pixels where undocking behavior is triggered
        /// by using a pen to drag a window from the edge of a monitor or monitor array toward its center.
        /// The default threshold is 30.
        /// </para>
        /// <para>
        /// Use <see cref="SPI_GETWINARRANGING"/> to determine whether this behavior is enabled.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETPENSIDEMOVETHRESHOLD"/>
        /// </para>
        /// <para>
        /// 0x008A
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Retrieves the threshold in pixels from the top of a monitor or monitor array
        /// where a vertically maximized window is restored when dragged with the mouse.
        /// The default threshold is 50.
        /// </para>
        /// <para>
        /// Use <see cref="SPI_GETWINARRANGING"/> to determine whether this behavior is enabled.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETSHOWIMEUI"/>
        /// </para>
        /// <para>
        /// 0x006E
        /// </para>
        /// </term>
        /// <term>
        /// Determines whether the IME status window is visible (on a per-user basis).
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if the status window is visible, or <see cref="FALSE"/> if it is not.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETSNAPSIZING"/>
        /// </para>
        /// <para>
        /// 0x008E
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether a window is vertically maximized when it is sized to the top or bottom of a monitor or monitor array.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if enabled, or <see cref="FALSE"/> otherwise.
        /// </para>
        /// <para>
        /// Use <see cref="SPI_GETWINARRANGING"/> to determine whether this behavior is enabled.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_GETWINARRANGING"/>
        /// </para>
        /// <para>
        /// 0x0082
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Determines whether window arrangement is enabled.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="BOOL"/> variable
        /// that receives <see cref="TRUE"/> if enabled, or <see cref="FALSE"/> otherwise.
        /// </para>
        /// <para>
        /// Window arrangement reduces the number of mouse, pen, or touch interactions needed
        /// to move and size top-level windows by simplifying the default behavior of a window when it is dragged or sized.
        /// </para>
        /// <para>
        /// The following parameters retrieve individual window arrangement settings:
        /// </para>
        /// <para>
        /// <see cref="SPI_GETDOCKMOVING"/>
        /// </para>
        /// <para>
        /// <see cref="SPI_GETMOUSEDOCKTHRESHOLD"/>
        /// </para>
        /// <para>
        /// <see cref="SPI_GETMOUSEDRAGOUTTHRESHOLD"/>
        /// </para>
        /// <para>
        /// <see cref="SPI_GETMOUSESIDEMOVETHRESHOLD"/>
        /// </para>
        /// <para>
        /// <see cref="SPI_GETPENDOCKTHRESHOLD"/>
        /// </para>
        /// <para>
        /// <see cref="SPI_GETPENDRAGOUTTHRESHOLD"/>
        /// </para>
        /// <para>
        /// <see cref="SPI_GETPENSIDEMOVETHRESHOLD"/>
        /// </para>
        /// <para>
        /// <see cref="SPI_GETSNAPSIZING"/>
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETACTIVEWINDOWTRACKING"/>
        /// </para>
        /// <para>
        /// 0x1001
        /// </para>
        /// </term>
        /// <term>
        /// Sets active window tracking (activating the window the mouse is on) either on or off.
        /// Set <paramref name="pvParam"/> to <see cref="TRUE"/> for on or <see cref="FALSE"/> for off.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETACTIVEWNDTRKZORDER"/>
        /// </para>
        /// <para>
        /// 0x100D
        /// </para>
        /// </term>
        /// <term>
        /// Determines whether or not windows activated through active window tracking should be brought to the top.
        /// Set <paramref name="pvParam"/> to <see cref="TRUE"/> for on or <see cref="FALSE"/> for off.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETACTIVEWNDTRKTIMEOUT"/>
        /// </para>
        /// <para>
        /// 0x2003
        /// </para>
        /// </term>
        /// <term>
        /// Sets the active window tracking delay.
        /// Set <paramref name="pvParam"/> to the number of milliseconds to delay before activating the window under the mouse pointer.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETANIMATION"/>
        /// </para>
        /// <para>
        /// 0x0049
        /// </para>
        /// </term>
        /// <term>
        /// Sets the animation effects associated with user actions.
        /// The <paramref name="pvParam"/> parameter must point to an <see cref="ANIMATIONINFO"/> structure that contains the new parameters.
        /// Set the <see cref="ANIMATIONINFO.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(ANIMATIONINFO)</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETBORDER"/>
        /// </para>
        /// <para>
        /// 0x0006
        /// </para>
        /// </term>
        /// <term>
        /// Sets the border multiplier factor that determines the width of a window's sizing border.
        /// The <paramref name="uiParam"/> parameter specifies the new value.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETCARETWIDTH"/>
        /// </para>
        /// <para>
        /// 0x2007
        /// </para>
        /// </term>
        /// <term>
        /// Sets the caret width in edit controls.
        /// Set <paramref name="pvParam"/> to the desired width, in pixels.
        /// The default and minimum value is 1.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETDOCKMOVING"/>
        /// </para>
        /// <para>
        /// 0x0091
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets whether a window is docked when it is moved to the top, left, or right docking targets on a monitor or monitor array.
        /// Set <paramref name="pvParam"/> to <see cref="TRUE"/> for on or <see cref="FALSE"/> for off.
        /// </para>
        /// <para>
        /// <see cref="SPI_GETWINARRANGING"/> must be <see cref="TRUE"/> to enable this behavior.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETDRAGFROMMAXIMIZE"/>
        /// </para>
        /// <para>
        /// 0x008D
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets whether a maximized window is restored when its caption bar is dragged.
        /// Set <paramref name="pvParam"/> to <see cref="TRUE"/> for on or <see cref="FALSE"/> for off.
        /// </para>
        /// <para>
        /// <see cref="SPI_GETWINARRANGING"/> must be <see cref="TRUE"/> to enable this behavior.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETDRAGFULLWINDOWS"/>
        /// </para>
        /// <para>
        /// 0x0025
        /// </para>
        /// </term>
        /// <term>
        /// Sets dragging of full windows either on or off.
        /// The <paramref name="uiParam"/> parameter specifies <see cref="TRUE"/> for on, or <see cref="FALSE"/> for off.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETDRAGHEIGHT"/>
        /// </para>
        /// <para>
        /// 0x004D
        /// </para>
        /// </term>
        /// <term>
        /// Sets the height, in pixels, of the rectangle used to detect the start of a drag operation.
        /// Set <paramref name="uiParam"/> to the new value. To retrieve the drag height,
        /// call <see cref="GetSystemMetrics"/> with the <see cref="SM_CYDRAG"/> flag.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETDRAGWIDTH"/>
        /// </para>
        /// <para>
        /// 0x004C
        /// </para>
        /// </term>
        /// <term>
        /// Sets the width, in pixels, of the rectangle used to detect the start of a drag operation.
        /// Set <paramref name="uiParam"/> to the new value.
        /// To retrieve the drag width, call <see cref="GetSystemMetrics"/> with the <see cref="SM_CXDRAG"/> flag.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETFOREGROUNDFLASHCOUNT"/>
        /// </para>
        /// <para>
        /// 0x2005
        /// </para>
        /// </term>
        /// <term>
        /// Sets the number of times <see cref="SetForegroundWindow"/> will flash the taskbar button
        /// when rejecting a foreground switch request.
        /// Set <paramref name="pvParam"/> to the number of times to flash.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETFOREGROUNDLOCKTIMEOUT"/>
        /// </para>
        /// <para>
        /// 0x2001
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the amount of time following user input, in milliseconds,
        /// during which the system does not allow applications to force themselves into the foreground.
        /// Set <paramref name="pvParam"/> to the new time-out value.
        /// </para>
        /// <para>
        /// The calling thread must be able to change the foreground window, otherwise the call fails.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMINIMIZEDMETRICS"/>
        /// </para>
        /// <para>
        /// 0x002C
        /// </para>
        /// </term>
        /// <term>
        /// Sets the metrics associated with minimized windows.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="MINIMIZEDMETRICS"/> structure that contains the new parameters.
        /// Set the <see cref="MINIMIZEDMETRICS.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(MINIMIZEDMETRICS)</c>.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMOUSEDOCKTHRESHOLD"/>
        /// </para>
        /// <para>
        /// 0x007F
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the threshold in pixels where docking behavior is triggered
        /// by using a mouse to drag a window to the edge of a monitor or monitor array.
        /// The default threshold is 1. The <paramref name="pvParam"/> parameter must point to a <see cref="DWORD"/> variable that contains the new value.
        /// </para>
        /// <para>
        /// <see cref="SPI_GETWINARRANGING"/> must be <see cref="TRUE"/> to enable this behavior.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMOUSEDRAGOUTTHRESHOLD"/>
        /// </para>
        /// <para>
        /// 0x0085
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the threshold in pixels where undocking behavior is triggered
        /// by using a mouse to drag a window from the edge of a monitor or monitor array to its center.
        /// The default threshold is 20.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="DWORD"/> variable that contains the new value.
        /// </para>
        /// <para>
        /// <see cref="SPI_GETWINARRANGING"/> must be <see cref="TRUE"/> to enable this behavior.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETMOUSESIDEMOVETHRESHOLD"/>
        /// </para>
        /// <para>
        /// 0x0089
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the threshold in pixels from the top of the monitor where a vertically maximized window is restored when dragged with the mouse.
        /// The default threshold is 50.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="DWORD"/> variable that contains the new value.
        /// </para>
        /// <para>
        /// <see cref="SPI_GETWINARRANGING"/> must be <see cref="TRUE"/> to enable this behavior.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETNONCLIENTMETRICS"/>
        /// </para>
        /// <para>
        /// 0x002A
        /// </para>
        /// </term>
        /// <term>
        /// Sets the metrics associated with the nonclient area of nonminimized windows.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="NONCLIENTMETRICS"/> structure that contains the new parameters.
        /// Set the <see cref="NONCLIENTMETRICS.cbSize"/> member of this structure and the <paramref name="uiParam"/> parameter to <c>sizeof(NONCLIENTMETRICS)</c>.
        /// Also, the <see cref="LOGFONT.lfHeight"/> member of the <see cref="LOGFONT"/> structure must be a negative value.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETPENDOCKTHRESHOLD"/>
        /// </para>
        /// <para>
        /// 0x0081
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the threshold in pixels where docking behavior is triggered
        /// by using a pen to drag a window to the edge of a monitor or monitor array.
        /// The default threshold is 30. The <paramref name="pvParam"/> parameter must point to a <see cref="DWORD"/> variable that contains the new value.
        /// </para>
        /// <para>
        /// <see cref="SPI_GETWINARRANGING"/> must be <see cref="TRUE"/> to enable this behavior.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETPENDRAGOUTTHRESHOLD"/>
        /// </para>
        /// <para>
        /// 0x0087
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the threshold in pixels where undocking behavior is triggered
        /// by using a pen to drag a window from the edge of a monitor or monitor array to its center.
        /// The default threshold is 30.
        /// The <paramref name="pvParam"/> parameter must point to a <see cref="DWORD"/> variable that contains the new value.
        /// </para>
        /// <para>
        /// <see cref="SPI_GETWINARRANGING"/> must be <see cref="TRUE"/> to enable this behavior.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETPENSIDEMOVETHRESHOLD"/>
        /// </para>
        /// <para>
        /// 0x008B
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets the threshold in pixels from the top of the monitor where a vertically maximized window is restored when dragged with a pen.
        /// The default threshold is 50. The <paramref name="pvParam"/> parameter must point to a <see cref="DWORD"/> variable that contains the new value.
        /// </para>
        /// <para>
        /// <see cref="SPI_GETWINARRANGING"/> must be <see cref="TRUE"/> to enable this behavior.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETSHOWIMEUI"/>
        /// </para>
        /// <para>
        /// 0x006F
        /// </para>
        /// </term>
        /// <term>
        /// Sets whether the IME status window is visible or not on a per-user basis.
        /// The <paramref name="uiParam"/> parameter specifies <see cref="TRUE"/> for on or <see cref="FALSE"/> for off.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETSNAPSIZING"/>
        /// </para>
        /// <para>
        /// 0x008F
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets whether a window is vertically maximized when it is sized to the top or bottom of the monitor.
        /// Set <paramref name="pvParam"/> to <see cref="TRUE"/> for on or <see cref="FALSE"/> for off.
        /// </para>
        /// <para>
        /// <see cref="SPI_GETWINARRANGING"/> must be <see cref="TRUE"/> to enable this behavior.
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <para>
        /// <see cref="SPI_SETWINARRANGING"/>
        /// </para>
        /// <para>
        /// 0x0083
        /// </para>
        /// </term>
        /// <term>
        /// <para>
        /// Sets whether window arrangement is enabled.
        /// Set <paramref name="pvParam"/> to <see cref="TRUE"/> for on or <see cref="FALSE"/> for off.
        /// </para>
        /// <para>
        /// Window arrangement reduces the number of mouse, pen, or touch interactions needed to
        /// move and size top-level windows by simplifying the default behavior of a window when it is dragged or sized.
        /// </para>
        /// <para>
        /// The following parameters set individual window arrangement settings:
        /// </para>
        /// <para>
        /// <see cref="SPI_SETDOCKMOVING"/>
        /// </para>
        /// <para>
        /// <see cref="SPI_SETMOUSEDOCKTHRESHOLD"/>
        /// </para>
        /// <para>
        /// <see cref="SPI_SETMOUSEDRAGOUTTHRESHOLD"/>
        /// </para>
        /// <para>
        /// <see cref="SPI_SETMOUSESIDEMOVETHRESHOLD"/>
        /// </para>
        /// <para>
        /// <see cref="SPI_SETPENDOCKTHRESHOLD"/>
        /// </para>
        /// <para>
        /// <see cref="SPI_SETPENDRAGOUTTHRESHOLD"/>
        /// </para>
        /// <para>
        /// <see cref="SPI_SETPENSIDEMOVETHRESHOLD"/>
        /// </para>
        /// <para>
        /// <see cref="SPI_SETSNAPSIZING"/>
        /// </para>
        /// <para>
        /// Windows Server 2008, Windows Vista, Windows Server 2003 and Windows XP/2000: This parameter is not supported.
        /// </para>
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// </param>
        /// <param name="uiParam">
        /// A parameter whose usage and format depends on the system parameter being queried or set.
        /// For more information about system-wide parameters, see the <paramref name="uiAction"/> parameter.
        /// If not otherwise indicated, you must specify zero for this parameter.
        /// </param>
        /// <param name="pvParam">
        /// A parameter whose usage and format depends on the system parameter being queried or set.
        /// For more information about system-wide parameters, see the <paramref name="uiAction"/> parameter.
        /// If not otherwise indicated, you must specify <see cref="NULL"/> for this parameter.
        /// For information on the PVOID datatype, see Windows Data Types.
        /// </param>
        /// <param name="fWinIni">
        /// <para>
        /// If a system parameter is being set, specifies whether the user profile is to be updated,
        /// and if so, whether the <see cref="WM_SETTINGCHANGE"/> message is to be broadcast to all top-level windows to notify them of the change.
        /// </para>
        /// <para>
        /// This parameter can be zero if you do not want to update the user profile or broadcast the <see cref="WM_SETTINGCHANGE"/> message,
        /// or it can be one or more of the following values.
        /// </para>
        /// <para>
        /// <list type="table">
        /// <listheader>
        /// <term>
        /// Value
        /// </term>
        /// <term>
        /// Meaning
        /// </term>
        /// </listheader>
        /// <item>
        /// <term>
        /// <see cref="SPIF_UPDATEINIFILE"/>
        /// </term>
        /// <term>
        /// Writes the new system-wide parameter setting to the user profile.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <see cref="SPIF_SENDCHANGE"/>
        /// </term>
        /// <term>
        /// Broadcasts the <see cref="WM_SETTINGCHANGE"/> message after updating the user profile.
        /// </term>
        /// </item>
        /// <item>
        /// <term>
        /// <see cref="SPIF_SENDWININICHANGE"/>
        /// </term>
        /// <term>
        /// Same as <see cref="SPIF_SENDCHANGE"/>.
        /// </term>
        /// </item>
        /// </list>
        /// </para>
        /// </param>
        /// <returns>
        /// <para>
        /// If the function succeeds, the return value is a nonzero value.
        /// </para>
        /// <para>
        /// If the function fails, the return value is zero.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </para>
        /// </returns>
        /// <remarks>
        /// <para>
        /// This function is intended for use with applications that allow the user to customize the environment.
        /// </para>
        /// <para>
        /// A keyboard layout name should be derived from the hexadecimal value of the language identifier corresponding to the layout.
        /// For example, U.S. English has a language identifier of 0x0409, so the primary U.S. English layout is named "00000409".
        /// Variants of U.S. English layout, such as the Dvorak layout, are named "00010409", "00020409" and so on.
        /// For a list of the primary language identifiers and sublanguage identifiers that make up a language identifier, see the <see cref="MAKELANGID"/> macro.
        /// </para>
        /// <para>
        /// There is a difference between the High Contrast color scheme and the High Contrast Mode.
        /// The High Contrast color scheme changes the system colors to colors that have obvious contrast;
        /// you switch to this color scheme by using the Display Options in the control panel.
        /// The High Contrast Mode, which uses <see cref="SPI_GETHIGHCONTRAST"/> and <see cref="SPI_SETHIGHCONTRAST"/>,
        /// advises applications to modify their appearance for visually-impaired users.
        /// It involves such things as audible warning to users and customized color scheme
        /// (using the Accessibility Options in the control panel).
        /// For more information, see <see cref="HIGHCONTRAST"/>.
        /// For more information on general accessibility features, see Accessibility.
        /// </para>
        /// <para>
        /// During the time that the primary button is held down to activate the Mouse ClickLock feature, the user can move the mouse.
        /// After the primary button is locked down, releasing the primary button does not result in a <see cref="WM_LBUTTONUP"/> message.
        /// Thus, it will appear to an application that the primary button is still down.
        /// Any subsequent button message releases the primary button, sending a <see cref="WM_LBUTTONUP"/> message to the application,
        /// thus the button can be unlocked programmatically or through the user clicking any button.
        /// </para>
        /// <para>
        /// This API is not DPI aware, and should not be used if the calling thread is per-monitor DPI aware.
        /// For the DPI-aware version of this API, see <see cref="SystemParametersInfoForDpi"/>.
        /// For more information on DPI awareness, see the Windows High DPI documentation.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.WindowsNT40)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "SystemParametersInfoW", ExactSpelling = true, SetLastError = true)]
        public static extern BOOL SystemParametersInfo([In] SystemParametersInfoParameters uiAction, [In] UINT uiParam,
            [In] PVOID pvParam, [In] SystemParametersInfoFlags fWinIni);

        /// <summary>
        /// <para>
        /// Grants or denies access to a handle to a User object to a job that has a user-interface restriction.
        /// When access is granted, all processes associated with the job can subsequently recognize and use the handle.
        /// When access is denied, the processes can no longer use the handle.
        /// For more information see User Objects.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-userhandlegrantaccess"/>
        /// </para>
        /// </summary>
        /// <param name="hUserHandle">
        /// A handle to the User object.
        /// </param>
        /// <param name="hJob">
        /// A handle to the job to be granted access to the User handle.
        /// The <see cref="CreateJobObject"/> or <see cref="OpenJobObject"/> function returns this handle.
        /// </param>
        /// <param name="bGrant">
        /// If this parameter is <see cref="TRUE"/>, all processes associated with the job can recognize and use the handle.
        /// If the parameter is <see cref="FALSE"/>, the processes cannot use the handle.
        /// </param>
        /// <returns>
        /// <para>
        /// If the function succeeds, the return value is nonzero.
        /// </para>
        /// <para>
        /// If the function fails, the return value is zero.
        /// To get extended error information, call <see cref="GetLastError"/>.
        /// </para>
        /// </returns>
        /// <remarks>
        /// <para>
        /// The <see cref="UserHandleGrantAccess"/> function can be called only from a process
        /// not associated with the job specified by the <paramref name="hJob"/> parameter.
        /// The User handle must not be owned by a process or thread associated with the job.
        /// </para>
        /// <para>
        /// To create user-interface restrictions,
        /// call the <see cref="SetInformationJobObject"/> function with the <see cref="JobObjectBasicUIRestrictions"/> job information class.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.Windows2000)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "UserHandleGrantAccess", ExactSpelling = true, SetLastError = true)]
        public static extern BOOL UserHandleGrantAccess([In] HANDLE hUserHandle, [In] HANDLE hJob, [In] BOOL bGrant);

        /// <summary>
        /// <para>
        /// Removes an event hook function created by a previous call to <see cref="SetWinEventHook"/>.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-unhookwinevent"/>
        /// </para>
        /// </summary>
        /// <param name="hWinEventHook">
        /// Handle to the event hook returned in the previous call to <see cref="SetWinEventHook"/>.
        /// </param>
        /// <returns>
        /// <para>
        /// If successful, returns <see cref="TRUE"/>; otherwise, returns <see cref="FALSE"/>.
        /// </para>
        /// <para>
        /// Three common errors cause this function to fail:
        /// </para>
        /// <para>
        /// <list type="bullet">
        /// <item>
        /// <description>
        /// The <paramref name="hWinEventHook"/> parameter is <see cref="NULL"/> or not valid.
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// The event hook specified by <paramref name="hWinEventHook"/> was already removed.
        /// </description>
        /// </item>
        /// <item>
        /// <description>
        /// <see cref="UnhookWinEvent"/> is called from a thread that is different from the original call to <see cref="SetWinEventHook"/>.
        /// </description>
        /// </item>
        /// </list>
        /// </para>
        /// </returns>
        /// <remarks>
        /// <para>
        /// This function removes the event hook specified by <paramref name="hWinEventHook"/>
        /// that prevents the corresponding callback function from receiving further event notifications.
        /// If the client's thread ends, the system automatically calls this function.
        /// </para>
        /// <para>
        /// Call this function from the same thread that installed the event hook.
        /// <see cref="UnhookWinEvent"/> fails if called from a thread different from the call that corresponds to <see cref="SetWinEventHook"/>.
        /// </para>
        /// <para>
        /// If <see cref="WINEVENT_INCONTEXT"/> was specified when this event hook was installed,
        /// the system attempts to unload the corresponding DLL from all processes that loaded it.
        /// Although unloading does not occur immediately, the hook function is not called after <see cref="UnhookWinEvent"/> returns.
        /// For more information on <see cref="WINEVENT_INCONTEXT"/>, see In-Context Hook Functions.
        /// </para>
        /// </remarks>
        [WindowsVersionRequirement(WindowsVersion.Windows2000)]
        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "UnhookWinEvent", ExactSpelling = true)]
        public static extern BOOL UnhookWinEvent([In] HWINEVENTHOOK hWinEventHook);

        /// <summary>
        /// <para>
        /// Closes the specified device notification handle.
        /// </para>
        /// <para>
        /// From: <see href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-unregisterdevicenotification"/>
        /// </para>
        /// </summary>
        /// <param name="Handle">
        /// Device notification handle returned by the <see cref="RegisterDeviceNotification"/> function.
        /// </param>
